{
  "name": "Lumière French Quiz",
  "description": "An AI-powered adaptive French quiz engine generating structured exercises based on CEFR levels and specific topics."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type CefrLevel = 'A1' | 'A2' | 'B1' | 'B2';
export type Difficulty = 'Easy' | 'Medium' | 'Hard';
export type QuestionType = 'mcq' | 'fill_blank' | 'matching';

export interface MatchingPair {
  left: string;
  right: string;
}

export interface QuestionContent {
  // MCQ
  options?: string[];

  // Fill Blank
  sentence_with_blank?: string;

  // Matching
  pairs?: MatchingPair[];

  // Common
  correct_answer?: string; 
}

export interface Question {
  id: number;
  type: QuestionType;
  question_text: string;
  content: QuestionContent;
  explanation: string;
}

export interface QuizData {
  title: string;
  topic: string;
  cefr_level: string;
  sub_difficulty: string;
  questions: Question[];
}

export interface QuizResponse {
  quiz: QuizData;
}

export interface QuizSettings {
  topic: string;
  level: CefrLevel;
  difficulty: Difficulty;
}

// User Answer Types
export type UserAnswerValue = string | Record<string, string>; // Record is for matching {left: right}

export interface QuizState {
  currentQuestionIndex: number;
  answers: Record<number, UserAnswerValue>;
  isSubmitted: boolean;
  score: number;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { QuizSettings, QuizResponse } from "../types";

const SYSTEM_INSTRUCTION = `
You are the "French Quiz Engine," a specialized API endpoint that generates structured JSON quizzes for French language learners. You possess expert knowledge of French grammar, vocabulary, and CEFR proficiency standards.

**Difficulty Matrix Logic:**
You must adjust the complexity based on the combination of CEFR Level and Sub-Difficulty:
- **Easy:** Focus on the core rule/vocabulary. Simple sentence structures (SVO). High-frequency words.
- **Medium:** Introduce standard sentence structures, slight nuances, and common variations.
- **Hard:** Test exceptions to the rule, use complex sentence structures, varying tenses, or "faux amis" (false friends).

**Content Requirements:**
1. Generate **5 questions** per request.
2. Mix the question types (MCQ, Fill in blank, Matching) to ensure variety.
3. Ensure all French accents (é, à, ù, ç) are correct.
`;

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    quiz: {
      type: Type.OBJECT,
      properties: {
        title: { type: Type.STRING },
        topic: { type: Type.STRING },
        cefr_level: { type: Type.STRING },
        sub_difficulty: { type: Type.STRING },
        questions: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              type: { type: Type.STRING, enum: ["mcq", "fill_blank", "matching"] },
              question_text: { type: Type.STRING },
              explanation: { type: Type.STRING },
              content: {
                type: Type.OBJECT,
                properties: {
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  correct_answer: { type: Type.STRING },
                  sentence_with_blank: { type: Type.STRING },
                  pairs: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        left: { type: Type.STRING },
                        right: { type: Type.STRING },
                      },
                      required: ["left", "right"],
                    },
                  },
                },
              },
            },
            required: ["id", "type", "question_text", "content", "explanation"],
          },
        },
      },
      required: ["title", "topic", "cefr_level", "sub_difficulty", "questions"],
    },
  },
  required: ["quiz"],
};

export const generateQuiz = async (settings: QuizSettings): Promise<QuizResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Topic: ${settings.topic}
    CEFR Level: ${settings.level}
    Sub-Difficulty: ${settings.difficulty}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.7, // Creativity balance for diverse questions
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as QuizResponse;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Question, MatchingPair } from '../types';

interface BaseQuestionProps {
  question: Question;
  currentAnswer: any;
  onAnswer: (answer: any) => void;
  isSubmitted: boolean;
}

// --- MCQ Component ---
export const McqQuestion: React.FC<BaseQuestionProps> = ({ question, currentAnswer, onAnswer, isSubmitted }) => {
  const options = question.content.options || [];

  return (
    <div className="space-y-3">
      {options.map((option, idx) => {
        const isSelected = currentAnswer === option;
        const isCorrect = isSubmitted && option === question.content.correct_answer;
        const isWrong = isSubmitted && isSelected && option !== question.content.correct_answer;

        let baseClasses = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center group";

        if (isSubmitted) {
            if (isCorrect) baseClasses += " bg-green-50 border-green-500 text-green-900";
            else if (isWrong) baseClasses += " bg-red-50 border-red-500 text-red-900";
            else baseClasses += " border-gray-200 opacity-60";
        } else {
            if (isSelected) baseClasses += " border-french-blue bg-blue-50 text-french-blue ring-1 ring-french-blue";
            else baseClasses += " border-gray-200 hover:bg-gray-50 hover:border-gray-300";
        }

        return (
          <button
            key={idx}
            onClick={() => !isSubmitted && onAnswer(option)}
            disabled={isSubmitted}
            className={baseClasses}
          >
            <div className={`w-5 h-5 rounded-full border mr-3 flex items-center justify-center ${isSelected ? 'border-french-blue' : 'border-gray-400'}`}>
                {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-french-blue" />}
            </div>
            <span className="font-medium text-lg">{option}</span>
          </button>
        );
      })}
    </div>
  );
};

// --- Fill In Blank Component ---
export const FillBlankQuestion: React.FC<BaseQuestionProps> = ({ question, currentAnswer, onAnswer, isSubmitted }) => {
  const parts = (question.content.sentence_with_blank || "").split("_____");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onAnswer(e.target.value);
  };

  const isCorrect = isSubmitted && 
    (currentAnswer || "").toLowerCase().trim() === (question.content.correct_answer || "").toLowerCase().trim();

  return (
    <div className="p-6 bg-slate-50 rounded-xl border border-slate-200 text-center">
      <div className="text-xl leading-relaxed text-slate-800 font-serif">
        {parts[0]}
        <span className="inline-block mx-2 relative top-[-2px]">
            <input
                type="text"
                value={currentAnswer || ''}
                onChange={handleChange}
                disabled={isSubmitted}
                placeholder="..."
                className={`
                    min-w-[120px] px-3 py-1 border-b-2 text-center bg-transparent focus:outline-none transition-colors font-bold
                    ${isSubmitted 
                        ? (isCorrect ? 'border-green-500 text-green-700' : 'border-red-500 text-red-700') 
                        : 'border-slate-400 focus:border-french-blue text-french-blue'
                    }
                `}
            />
        </span>
        {parts[1]}
      </div>
      {isSubmitted && !isCorrect && (
          <div className="mt-4 text-sm text-green-600 font-medium">
              Correct Answer: {question.content.correct_answer}
          </div>
      )}
    </div>
  );
};

// --- Matching Component ---
export const MatchingQuestion: React.FC<BaseQuestionProps> = ({ question, currentAnswer, onAnswer, isSubmitted }) => {
  // currentAnswer is Record<string, string> where key is leftItem, value is rightItem
  const answerMap = (currentAnswer as Record<string, string>) || {};

  const [shuffledRight, setShuffledRight] = useState<string[]>([]);
  const [selectedLeft, setSelectedLeft] = useState<string | null>(null);

  // Initialize shuffled right side only once
  useEffect(() => {
    if (question.content.pairs) {
      const rights = question.content.pairs.map(p => p.right);
      // Simple shuffle
      setShuffledRight([...rights].sort(() => Math.random() - 0.5));
    }
  }, [question.id]);

  const pairs = question.content.pairs || [];

  const handleLeftClick = (left: string) => {
    if (isSubmitted) return;
    // If clicking same, deselect
    if (selectedLeft === left) {
        setSelectedLeft(null);
        return;
    }
    setSelectedLeft(left);
  };

  const handleRightClick = (right: string) => {
    if (isSubmitted || !selectedLeft) return;

    const newAnswers = { ...answerMap, [selectedLeft]: right };
    onAnswer(newAnswers);
    setSelectedLeft(null);
  };

  const isPairCorrect = (left: string, right: string) => {
      const correctRight = pairs.find(p => p.left === left)?.right;
      return correctRight === right;
  };

  return (
    <div className="grid grid-cols-2 gap-8 relative">
      {/* Left Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2">Term</h4>
        {pairs.map((pair, idx) => {
          const isSelected = selectedLeft === pair.left;
          const matchedRight = answerMap[pair.left];
          const isCompleted = !!matchedRight;

          let borderColor = "border-slate-200";
          let bgColor = "bg-white";

          if (isSubmitted) {
             if (isCompleted && isPairCorrect(pair.left, matchedRight)) {
                 borderColor = "border-green-400";
                 bgColor = "bg-green-50";
             } else if (isCompleted) {
                 borderColor = "border-red-400";
                 bgColor = "bg-red-50";
             }
          } else {
             if (isSelected) {
                 borderColor = "border-french-blue";
                 bgColor = "bg-blue-50";
             } else if (isCompleted) {
                 borderColor = "border-slate-300";
                 bgColor = "bg-slate-50";
             }
          }

          return (
            <button
              key={`left-${idx}`}
              onClick={() => handleLeftClick(pair.left)}
              disabled={isSubmitted}
              className={`w-full p-3 text-left border rounded-md text-sm font-medium transition-all ${borderColor} ${bgColor} relative`}
            >
              {pair.left}
              {matchedRight && (
                  <span className="absolute right-2 top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-slate-300"></span>
              )}
            </button>
          );
        })}
      </div>

      {/* Right Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2">Match</h4>
        {shuffledRight.map((rightItem, idx) => {
           // Check if this right item is selected in any answer
           const isUsed = Object.values(answerMap).includes(rightItem);

           let borderColor = "border-slate-200";
           let opacity = "opacity-100";

           if (isSubmitted) {
                // Find which left matched this right
                const leftKey = Object.keys(answerMap).find(key => answerMap[key] === rightItem);
                if (leftKey) {
                    if (isPairCorrect(leftKey, rightItem)) {
                        borderColor = "border-green-400 bg-green-50";
                    } else {
                        borderColor = "border-red-400 bg-red-50";
                    }
                }
           } else {
               if (isUsed) {
                   borderColor = "border-slate-300 bg-slate-100 text-slate-400";
               }
           }

          return (
            <button
              key={`right-${idx}`}
              onClick={() => handleRightClick(rightItem)}
              disabled={isSubmitted || (isUsed && !isSubmitted)}
              className={`w-full p-3 text-left border rounded-md text-sm transition-all ${borderColor} ${opacity}`}
            >
              {rightItem}
            </button>
          );
        })}
      </div>

      {/* Helper text */}
      {!isSubmitted && (
          <div className="col-span-2 text-center text-xs text-slate-400 mt-2">
            Select an item on the left, then click the matching item on the right.
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { QuizData, UserAnswerValue } from '../types';
import { McqQuestion, FillBlankQuestion, MatchingQuestion } from './QuestionRenderers';
import { CheckCircleIcon, XCircleIcon, ArrowRightIcon, ArrowPathIcon } from '@heroicons/react/24/solid';

interface QuizInterfaceProps {
  quiz: QuizData;
  onRestart: () => void;
}

export const QuizInterface: React.FC<QuizInterfaceProps> = ({ quiz, onRestart }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, UserAnswerValue>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [score, setScore] = useState(0);

  const currentQuestion = quiz.questions[currentIndex];

  const handleAnswer = (val: UserAnswerValue) => {
    setAnswers(prev => ({ ...prev, [currentQuestion.id]: val }));
  };

  const calculateScore = () => {
    let newScore = 0;
    quiz.questions.forEach(q => {
      const ans = answers[q.id];
      if (!ans) return;

      if (q.type === 'mcq') {
        if (ans === q.content.correct_answer) newScore++;
      } else if (q.type === 'fill_blank') {
        if (typeof ans === 'string' && ans.toLowerCase().trim() === (q.content.correct_answer || '').toLowerCase().trim()) {
          newScore++;
        }
      } else if (q.type === 'matching') {
        // For matching, we require ALL pairs to be correct to get the point
        const userPairs = ans as Record<string, string>;
        const correctPairs = q.content.pairs || [];
        const isAllCorrect = correctPairs.every(p => userPairs[p.left] === p.right);
        if (isAllCorrect && Object.keys(userPairs).length === correctPairs.length) {
          newScore++;
        }
      }
    });
    setScore(newScore);
    setIsSubmitted(true);
  };

  const isLastQuestion = currentIndex === quiz.questions.length - 1;
  const progress = ((currentIndex + 1) / quiz.questions.length) * 100;

  // -- Results View --
  if (isSubmitted) {
    const percentage = Math.round((score / quiz.questions.length) * 100);
    let feedback = "Bon effort!";
    if (percentage === 100) feedback = "Excellent! Parfait!";
    else if (percentage >= 80) feedback = "Très bien!";
    else if (percentage >= 60) feedback = "Bien joué.";

    return (
      <div className="max-w-2xl mx-auto bg-white rounded-2xl shadow-xl overflow-hidden animate-fade-in">
        <div className="bg-french-blue text-white p-8 text-center">
            <h2 className="text-3xl font-serif font-bold mb-2">{feedback}</h2>
            <p className="opacity-90">You scored {score} out of {quiz.questions.length}</p>
        </div>

        <div className="p-8 space-y-8">
            {quiz.questions.map((q, idx) => {
                const ans = answers[q.id];
                // Quick check for correctness for icon display (simplified logic)
                let correct = false;
                if (q.type === 'mcq') correct = ans === q.content.correct_answer;
                else if (q.type === 'fill_blank') correct = typeof ans === 'string' && ans.toLowerCase().trim() === (q.content.correct_answer||'').toLowerCase().trim();
                else if (q.type === 'matching') {
                    const u = ans as Record<string,string> || {};
                    correct = (q.content.pairs||[]).every(p => u[p.left] === p.right);
                }

                return (
                    <div key={q.id} className="border-b border-slate-100 last:border-0 pb-6 last:pb-0">
                        <div className="flex items-start gap-3 mb-2">
                             {correct ? (
                                 <CheckCircleIcon className="w-6 h-6 text-green-500 flex-shrink-0 mt-0.5" />
                             ) : (
                                 <XCircleIcon className="w-6 h-6 text-red-500 flex-shrink-0 mt-0.5" />
                             )}
                             <div>
                                 <h3 className="font-semibold text-slate-800">Q{idx+1}: {q.question_text}</h3>
                                 <p className="text-sm text-slate-600 mt-2 bg-slate-50 p-3 rounded-lg border border-slate-200">
                                     <span className="font-bold text-slate-700">Explanation:</span> {q.explanation}
                                 </p>
                             </div>
                        </div>
                    </div>
                );
            })}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-center">
            <button 
                onClick={onRestart}
                className="flex items-center gap-2 px-8 py-3 bg-french-dark text-white rounded-full font-medium hover:bg-black transition-colors shadow-lg hover:shadow-xl"
            >
                <ArrowPathIcon className="w-5 h-5" />
                Generate New Quiz
            </button>
        </div>
      </div>
    );
  }

  // -- Active Quiz View --
  return (
    <div className="max-w-2xl mx-auto">
      {/* Header Info */}
      <div className="mb-8 flex items-center justify-between text-slate-600">
        <span className="font-serif italic text-french-blue font-bold">{quiz.topic}</span>
        <span className="bg-slate-200 text-xs font-bold px-2 py-1 rounded text-slate-600">{quiz.cefr_level} • {quiz.sub_difficulty}</span>
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-gray-200 rounded-full h-2 mb-8">
        <div 
            className="bg-french-blue h-2 rounded-full transition-all duration-500 ease-out" 
            style={{ width: `${progress}%` }}
        ></div>
      </div>

      {/* Card */}
      <div className="bg-white rounded-2xl shadow-xl p-8 min-h-[400px] flex flex-col relative overflow-hidden">

        {/* Question Header */}
        <div className="mb-6">
            <span className="text-xs font-bold tracking-widest text-slate-400 uppercase">Question {currentIndex + 1} of {quiz.questions.length}</span>
            <h2 className="text-2xl font-bold text-slate-800 mt-2 font-serif leading-tight">
                {currentQuestion.question_text}
            </h2>
        </div>

        {/* Question Content */}
        <div className="flex-grow">
            {currentQuestion.type === 'mcq' && (
                <McqQuestion 
                    question={currentQuestion} 
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={false} 
                />
            )}
            {currentQuestion.type === 'fill_blank' && (
                <FillBlankQuestion 
                    question={currentQuestion} 
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={false} 
                />
            )}
            {currentQuestion.type === 'matching' && (
                <MatchingQuestion 
                    question={currentQuestion} 
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={false} 
                />
            )}
        </div>

        {/* Navigation */}
        <div className="mt-8 pt-6 border-t border-slate-100 flex justify-between items-center">
             <button 
                onClick={() => setCurrentIndex(prev => Math.max(0, prev - 1))}
                disabled={currentIndex === 0}
                className="text-slate-400 hover:text-slate-600 font-medium disabled:opacity-30 px-4 py-2"
             >
                 Back
             </button>

             {isLastQuestion ? (
                 <button
                    onClick={calculateScore}
                    disabled={!answers[currentQuestion.id]} // basic validation
                    className="bg-french-red text-white px-8 py-3 rounded-full font-bold shadow-lg hover:bg-red-600 hover:shadow-xl transition-all disabled:opacity-50 disabled:shadow-none"
                 >
                     Submit Quiz
                 </button>
             ) : (
                 <button
                    onClick={() => setCurrentIndex(prev => Math.min(quiz.questions.length - 1, prev + 1))}
                    className="flex items-center gap-2 bg-french-blue text-white px-6 py-3 rounded-full font-medium shadow-lg hover:bg-blue-700 hover:shadow-xl transition-all"
                 >
                     Next
                     <ArrowRightIcon className="w-4 h-4" />
                 </button>
             )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSettings, CefrLevel, Difficulty } from '../types';
import { SparklesIcon } from '@heroicons/react/24/solid';

interface QuizFormProps {
  onSubmit: (settings: QuizSettings) => void;
  isLoading: boolean;
}

export const QuizForm: React.FC<QuizFormProps> = ({ onSubmit, isLoading }) => {
  const [topic, setTopic] = useState("Le Subjonctif");
  const [level, setLevel] = useState<CefrLevel>("B1");
  const [difficulty, setDifficulty] = useState<Difficulty>("Medium");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (topic.trim()) {
      onSubmit({ topic, level, difficulty });
    }
  };

  return (
    <div className="w-full max-w-lg mx-auto bg-white rounded-2xl shadow-xl overflow-hidden">
      <div className="bg-french-dark p-8 text-center relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-french-blue via-white to-french-red"></div>
        <h2 className="text-3xl font-serif text-white font-bold mb-2">Configure Quiz</h2>
        <p className="text-slate-400 text-sm">Customize your French learning path</p>
      </div>

      <form onSubmit={handleSubmit} className="p-8 space-y-6">
        {/* Topic Input */}
        <div>
          <label className="block text-sm font-semibold text-slate-700 mb-2 uppercase tracking-wide">Topic / Subject</label>
          <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            className="w-full px-4 py-3 rounded-lg bg-slate-50 border border-slate-200 focus:border-french-blue focus:ring-2 focus:ring-blue-100 outline-none transition-all font-medium text-slate-800"
            placeholder="e.g., Food Vocabulary, Past Tense..."
            disabled={isLoading}
          />
        </div>

        <div className="grid grid-cols-2 gap-6">
          {/* Level Select */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2 uppercase tracking-wide">CEFR Level</label>
            <div className="relative">
                <select
                value={level}
                onChange={(e) => setLevel(e.target.value as CefrLevel)}
                className="w-full appearance-none px-4 py-3 rounded-lg bg-slate-50 border border-slate-200 focus:border-french-blue focus:ring-2 focus:ring-blue-100 outline-none transition-all font-medium text-slate-800 cursor-pointer"
                disabled={isLoading}
                >
                <option value="A1">A1 (Beginner)</option>
                <option value="A2">A2 (Elementary)</option>
                <option value="B1">B1 (Intermediate)</option>
                <option value="B2">B2 (Upper Inter.)</option>
                </select>
                <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none">
                    <svg className="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                </div>
            </div>
          </div>

          {/* Difficulty Select */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2 uppercase tracking-wide">Difficulty</label>
             <div className="relative">
                <select
                    value={difficulty}
                    onChange={(e) => setDifficulty(e.target.value as Difficulty)}
                    className="w-full appearance-none px-4 py-3 rounded-lg bg-slate-50 border border-slate-200 focus:border-french-blue focus:ring-2 focus:ring-blue-100 outline-none transition-all font-medium text-slate-800 cursor-pointer"
                    disabled={isLoading}
                >
                    <option value="Easy">Easy</option>
                    <option value="Medium">Medium</option>
                    <option value="Hard">Hard</option>
                </select>
                <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none">
                    <svg className="w-4 h-4 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                </div>
            </div>
          </div>
        </div>

        <button
          type="submit"
