import React, { useState, useEffect } from 'react';
import { Question, GlossaryEntry } from '../types';
import { InteractiveText } from './InteractiveText';

interface BaseQuestionProps {
  question: Question;
  glossary: GlossaryEntry[];
  currentAnswer: any;
  onAnswer: (answer: any) => void;
  isSubmitted: boolean;
}

// --- MCQ Component ---
export const McqQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted }) => {
  const options = question.content.options || [];

  return (
    <div className="space-y-3">
      {options.map((option, idx) => {
        const isSelected = currentAnswer === option;
        const isCorrect = isSubmitted && option === question.content.correct_answer;
        const isWrong = isSubmitted && isSelected && option !== question.content.correct_answer;

        let baseClasses = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center group relative";

        if (isSubmitted) {
            if (isCorrect) baseClasses += " bg-green-50 border-green-500 text-green-900";
            else if (isWrong) baseClasses += " bg-red-50 border-red-500 text-red-900";
            else baseClasses += " border-gray-200 opacity-60";
        } else {
            if (isSelected) baseClasses += " border-french-blue bg-blue-50 text-french-blue ring-1 ring-french-blue";
            else baseClasses += " border-gray-200 hover:bg-gray-50 hover:border-gray-300";
        }

        return (
          <button
            key={idx}
            onClick={() => !isSubmitted && onAnswer(option)}
            disabled={isSubmitted}
            className={baseClasses}
          >
            <div className={`w-5 h-5 rounded-full border mr-3 flex-shrink-0 flex items-center justify-center ${isSelected ? 'border-french-blue' : 'border-gray-400'}`}>
                {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-french-blue" />}
            </div>
            {/* 
               Note: We use InteractiveText here. 
               However, since clicking the button selects the answer, we need to make sure tooltip interaction doesn't conflict. 
               The tooltip is hover-only, so it generally works fine.
            */}
            <span className="font-medium text-lg flex-grow">
                <InteractiveText text={option} glossary={glossary} />
            </span>
          </button>
        );
      })}
    </div>
  );
};

// --- Fill In Blank Component ---
export const FillBlankQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted }) => {
  const parts = (question.content.sentence_with_blank || "").split("_____");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onAnswer(e.target.value);
  };

  const isCorrect = isSubmitted && 
    (currentAnswer || "").toLowerCase().trim() === (question.content.correct_answer || "").toLowerCase().trim();

  return (
    <div className="p-6 bg-slate-50 rounded-xl border border-slate-200 text-center">
      <div className="text-xl leading-relaxed text-slate-800 font-serif">
        <InteractiveText text={parts[0]} glossary={glossary} />
        <span className="inline-block mx-2 relative top-[-2px]">
            <input
                type="text"
                value={currentAnswer || ''}
                onChange={handleChange}
                disabled={isSubmitted}
                placeholder="..."
                className={`
                    min-w-[120px] px-3 py-1 border-b-2 text-center bg-transparent focus:outline-none transition-colors font-bold
                    ${isSubmitted 
                        ? (isCorrect ? 'border-green-500 text-green-700' : 'border-red-500 text-red-700') 
                        : 'border-slate-400 focus:border-french-blue text-french-blue'
                    }
                `}
            />
        </span>
        <InteractiveText text={parts[1] || ""} glossary={glossary} />
      </div>
      {isSubmitted && !isCorrect && (
          <div className="mt-4 text-sm text-green-600 font-medium">
              Correct Answer: {question.content.correct_answer}
          </div>
      )}
    </div>
  );
};

// --- Matching Component ---
export const MatchingQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted }) => {
  const answerMap = (currentAnswer as Record<string, string>) || {};

  const [shuffledRight, setShuffledRight] = useState<string[]>([]);
  const [selectedLeft, setSelectedLeft] = useState<string | null>(null);

  useEffect(() => {
    if (question.content.pairs) {
      const rights = question.content.pairs.map(p => p.right);
      setShuffledRight([...rights].sort(() => Math.random() - 0.5));
    }
  }, [question.id]);

  const pairs = question.content.pairs || [];

  const handleLeftClick = (left: string) => {
    if (isSubmitted) return;
    if (selectedLeft === left) {
        setSelectedLeft(null);
        return;
    }
    setSelectedLeft(left);
  };

  const handleRightClick = (right: string) => {
    if (isSubmitted || !selectedLeft) return;
    const newAnswers = { ...answerMap, [selectedLeft]: right };
    onAnswer(newAnswers);
    setSelectedLeft(null);
  };

  const isPairCorrect = (left: string, right: string) => {
      const correctRight = pairs.find(p => p.left === left)?.right;
      return correctRight === right;
  };

  return (
    <div className="grid grid-cols-2 gap-8 relative">
      {/* Left Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2">Term</h4>
        {pairs.map((pair, idx) => {
          const isSelected = selectedLeft === pair.left;
          const matchedRight = answerMap[pair.left];
          const isCompleted = !!matchedRight;

          let borderColor = "border-slate-200";
          let bgColor = "bg-white";

          if (isSubmitted) {
             if (isCompleted && isPairCorrect(pair.left, matchedRight)) {
                 borderColor = "border-green-400";
                 bgColor = "bg-green-50";
             } else if (isCompleted) {
                 borderColor = "border-red-400";
                 bgColor = "bg-red-50";
             }
          } else {
             if (isSelected) {
                 borderColor = "border-french-blue";
                 bgColor = "bg-blue-50";
             } else if (isCompleted) {
                 borderColor = "border-slate-300";
                 bgColor = "bg-slate-50";
             }
          }

          return (
            <button
              key={`left-${idx}`}
              onClick={() => handleLeftClick(pair.left)}
              disabled={isSubmitted}
              className={`w-full p-3 text-left border rounded-md text-sm font-medium transition-all ${borderColor} ${bgColor} relative`}
            >
              <InteractiveText text={pair.left} glossary={glossary} />
              {matchedRight && (
                  <span className="absolute right-2 top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-slate-300"></span>
              )}
            </button>
          );
        })}
      </div>

      {/* Right Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2">Match</h4>
        {shuffledRight.map((rightItem, idx) => {
           const isUsed = Object.values(answerMap).includes(rightItem);

           let borderColor = "border-slate-200";
           let opacity = "opacity-100";

           if (isSubmitted) {
                const leftKey = Object.keys(answerMap).find(key => answerMap[key] === rightItem);
                if (leftKey) {
                    if (isPairCorrect(leftKey, rightItem)) {
                        borderColor = "border-green-400 bg-green-50";
                    } else {
                        borderColor = "border-red-400 bg-red-50";
                    }
                }
           } else {
               if (isUsed) {
                   borderColor = "border-slate-300 bg-slate-100 text-slate-400";
               }
           }

          return (
            <button
              key={`right-${idx}`}
              onClick={() => handleRightClick(rightItem)}
              disabled={isSubmitted || (isUsed && !isSubmitted)}
              className={`w-full p-3 text-left border rounded-md text-sm transition-all ${borderColor} ${opacity}`}
            >
              <InteractiveText text={rightItem} glossary={glossary} />
            </button>
          );
        })}
      </div>

      {!isSubmitted && (
          <div className="col-span-2 text-center text-xs text-slate-400 mt-2">
            Select an item on the left, then click the matching item on the right.
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { QuizData, UserAnswerValue } from '../types';
import { McqQuestion, FillBlankQuestion, MatchingQuestion } from './QuestionRenderers';
import { InteractiveText } from './InteractiveText';
import { CheckCircleIcon, XCircleIcon, ArrowRightIcon, ArrowPathIcon } from '@heroicons/react/24/solid';

interface QuizInterfaceProps {
  quiz: QuizData;
  onRestart: () => void;
}

export const QuizInterface: React.FC<QuizInterfaceProps> = ({ quiz, onRestart }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, UserAnswerValue>>({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [score, setScore] = useState(0);

  const currentQuestion = quiz.questions[currentIndex];
  // Ensure glossary exists (backward compatibility or safety)
  const glossary = quiz.glossary || [];

  const handleAnswer = (val: UserAnswerValue) => {
    setAnswers(prev => ({ ...prev, [currentQuestion.id]: val }));
  };

  const calculateScore = () => {
    let newScore = 0;
    quiz.questions.forEach(q => {
      const ans = answers[q.id];
      if (!ans) return;

      if (q.type === 'mcq') {
        if (ans === q.content.correct_answer) newScore++;
      } else if (q.type === 'fill_blank') {
        if (typeof ans === 'string' && ans.toLowerCase().trim() === (q.content.correct_answer || '').toLowerCase().trim()) {
          newScore++;
        }
      } else if (q.type === 'matching') {
        // For matching, we require ALL pairs to be correct to get the point
        const userPairs = ans as Record<string, string>;
        const correctPairs = q.content.pairs || [];
        const isAllCorrect = correctPairs.every(p => userPairs[p.left] === p.right);
        if (isAllCorrect && Object.keys(userPairs).length === correctPairs.length) {
          newScore++;
        }
      }
    });
    setScore(newScore);
    setIsSubmitted(true);
  };

  const isLastQuestion = currentIndex === quiz.questions.length - 1;
  const progress = ((currentIndex + 1) / quiz.questions.length) * 100;

  // -- Results View --
  if (isSubmitted) {
    const percentage = Math.round((score / quiz.questions.length) * 100);
    let feedback = "Bon effort!";
    if (percentage === 100) feedback = "Excellent! Parfait!";
    else if (percentage >= 80) feedback = "Très bien!";
    else if (percentage >= 60) feedback = "Bien joué.";

    return (
      <div className="max-w-2xl mx-auto bg-white rounded-2xl shadow-xl overflow-hidden animate-fade-in">
        <div className="bg-french-blue text-white p-8 text-center">
            <h2 className="text-3xl font-serif font-bold mb-2">{feedback}</h2>
            <p className="opacity-90">You scored {score} out of {quiz.questions.length}</p>
        </div>

        <div className="p-8 space-y-8">
            {quiz.questions.map((q, idx) => {
                const ans = answers[q.id];
                // Quick check for correctness for icon display (simplified logic)
                let correct = false;
                if (q.type === 'mcq') correct = ans === q.content.correct_answer;
                else if (q.type === 'fill_blank') correct = typeof ans === 'string' && ans.toLowerCase().trim() === (q.content.correct_answer||'').toLowerCase().trim();
                else if (q.type === 'matching') {
                    const u = ans as Record<string,string> || {};
                    correct = (q.content.pairs||[]).every(p => u[p.left] === p.right);
                }

                return (
                    <div key={q.id} className="border-b border-slate-100 last:border-0 pb-6 last:pb-0">
                        <div className="flex items-start gap-3 mb-2">
                             {correct ? (
                                 <CheckCircleIcon className="w-6 h-6 text-green-500 flex-shrink-0 mt-0.5" />
                             ) : (
                                 <XCircleIcon className="w-6 h-6 text-red-500 flex-shrink-0 mt-0.5" />
                             )}
                             <div>
                                 <h3 className="font-semibold text-slate-800 flex flex-wrap gap-1">
                                     <span className="mr-1">Q{idx+1}:</span>
                                     <InteractiveText text={q.question_text} glossary={glossary} />
                                 </h3>
                                 <p className="text-sm text-slate-600 mt-2 bg-slate-50 p-3 rounded-lg border border-slate-200">
                                     <span className="font-bold text-slate-700">Explanation:</span> {q.explanation}
                                 </p>
                             </div>
                        </div>
                    </div>
                );
            })}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-center">
            <button 
                onClick={onRestart}
                className="flex items-center gap-2 px-8 py-3 bg-french-dark text-white rounded-full font-medium hover:bg-black transition-colors shadow-lg hover:shadow-xl"
            >
                <ArrowPathIcon className="w-5 h-5" />
                Generate New Quiz
            </button>
        </div>
      </div>
    );
  }

  // -- Active Quiz View --
  return (
    <div className="max-w-2xl mx-auto">
      {/* Header Info */}
      <div className="mb-8 flex items-center justify-between text-slate-600">
        <span className="font-serif italic text-french-blue font-bold">{quiz.topic}</span>
        <span className="bg-slate-200 text-xs font-bold px-2 py-1 rounded text-slate-600">{quiz.cefr_level} • {quiz.sub_difficulty}</span>
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-gray-200 rounded-full h-2 mb-8">
        <div 
            className="bg-french-blue h-2 rounded-full transition-all duration-500 ease-out" 
            style={{ width: `${progress}%` }}
        ></div>
      </div>

      {/* Card */}
      <div className="bg-white rounded-2xl shadow-xl p-8 min-h-[400px] flex flex-col relative overflow-visible z-10">

        {/* Question Header */}
        <div className="mb-6">
            <span className="text-xs font-bold tracking-widest text-slate-400 uppercase">Question {currentIndex + 1} of {quiz.questions.length}</span>
            <h2 className="text-2xl font-bold text-slate-800 mt-2 font-serif leading-tight">
                <InteractiveText text={currentQuestion.question_text} glossary={glossary} />
            </h2>
        </div>

        {/* Question Content */}
        <div className="flex-grow">
            {currentQuestion.type === 'mcq' && (
                <McqQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={false} 
                />
            )}
            {currentQuestion.type === 'fill_blank' && (
                <FillBlankQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={false} 
                />
            )}
            {currentQuestion.type === 'matching' && (
                <MatchingQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={false} 
                />
            )}
        </div>

        {/* Navigation */}
        <div className="mt-8 pt-6 border-t border-slate-100 flex justify-between items-center">
             <button 
                onClick={() => setCurrentIndex(prev => Math.max(0, prev - 1))}
                disabled={currentIndex === 0}
                className="text-slate-400 hover:text-slate-600 font-medium disabled:opacity-30 px-4 py-2"
             >
                 Back
             </button>

             {isLastQuestion ? (
                 <button
                    onClick={calculateScore}
                    disabled={!answers[currentQuestion.id]} // basic validation
                    className="bg-french-red text-white px-8 py-3 rounded-full font-bold shadow-lg hover:bg-red-600 hover:shadow-xl transition-all disabled:opacity-50 disabled:shadow-none"
                 >
                     Submit Quiz
                 </button>
             ) : (
                 <button
                    onClick={() => setCurrentIndex(prev => Math.min(quiz.questions.length - 1, prev + 1))}
                    className="flex items-center gap-2 bg-french-blue text-white px-6 py-3 rounded-full font-medium shadow-lg hover:bg-blue-700 hover:shadow-xl transition-all"
                 >
                     Next
                     <ArrowRightIcon className="w-4 h-4" />
                 </button>
             )}
        </div>
      </div>
    </div>
  );
};

export type CefrLevel = 'A1' | 'A2' | 'B1' | 'B2';
export type Difficulty = 'Easy' | 'Medium' | 'Hard';
export type QuestionType = 'mcq' | 'fill_blank' | 'matching';

export interface MatchingPair {
  left: string;
  right: string;
}

export interface QuestionContent {
  // MCQ
  options?: string[];

  // Fill Blank
  sentence_with_blank?: string;

  // Matching
  pairs?: MatchingPair[];

  // Common
  correct_answer?: string; 
}

export interface Question {
  id: number;
  type: QuestionType;
  question_text: string;
  content: QuestionContent;
  explanation: string;
}

export interface GlossaryEntry {
