  isSubmitted: boolean;
  score: number;
}

import { QuizData, SavedQuiz } from '../types';

const STORAGE_KEY = 'lumiere_quizzes_v1';

export const saveQuizToHistory = (quiz: QuizData): SavedQuiz => {
  const saved: SavedQuiz = {
    // Use crypto.randomUUID if available, else fallback to date+random
    id: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : Date.now().toString() + Math.random().toString().slice(2),
    created_at: Date.now(),
    data: quiz
  };

  const existing = getSavedQuizzes();
  // Add to top of list
  const updated = [saved, ...existing];
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  } catch (e) {
    console.error("Failed to save quiz to local storage", e);
  }
  return saved;
};

export const getSavedQuizzes = (): SavedQuiz[] => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    console.error("Failed to parse quiz history", e);
    return [];
  }
};

export const deleteSavedQuiz = (id: string): SavedQuiz[] => {
  const existing = getSavedQuizzes();
  const updated = existing.filter(q => q.id !== id);
  localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
  return updated;
};

