        data: row.data
      }));

  } catch (err: any) {
      // Suppress "table not found" errors to avoid scary console logs for users who haven't run SQL migration yet
      if (err.code === '42P01') { 
          console.info("Supabase 'quizzes' table not found. Using local storage only.");
