import { createClient } from '@supabase/supabase-js';

// Helper to reliably get environment variables across different environments (Vite, CRA, Node)
const getEnv = (key: string): string => {
  // 1. Try Vite's import.meta.env (if available)
  // @ts-ignore
  if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[key]) {
    // @ts-ignore
    return import.meta.env[key];
  }

  // 2. Try standard process.env (CRA, Next.js, Node)
  if (typeof process !== 'undefined' && process.env && process.env[key]) {
    return process.env[key];
  }

  return '';
};

// Check all common naming conventions for Supabase keys
const getSupabaseUrl = () => 
  getEnv('VITE_SUPABASE_URL') || 
  getEnv('REACT_APP_SUPABASE_URL') || 
  getEnv('SUPABASE_URL') || 
  '';

const getSupabaseKey = () => 
  getEnv('VITE_SUPABASE_ANON_KEY') || 
  getEnv('REACT_APP_SUPABASE_ANON_KEY') || 
  getEnv('REACT_APP_SUPABASE_PUBLISHABLE_DEFAULT_KEY') || 
  getEnv('SUPABASE_ANON_KEY') || 
  '';

const supabaseUrl = getSupabaseUrl().trim();
const supabaseKey = getSupabaseKey().trim();

// Debug log to help troubleshoot (remove in production if needed)
if (!supabaseUrl || !supabaseKey) {
  console.warn("Supabase Credentials not found. Checking: VITE_SUPABASE_URL, REACT_APP_SUPABASE_URL, SUPABASE_URL");
}

// Use placeholders if env vars are missing to prevent client initialization errors
// We use a specific placeholder to detect this state later
const PLACEHOLDER_URL = 'https://placeholder.supabase.co';
const url = supabaseUrl || PLACEHOLDER_URL;
const key = supabaseKey || 'placeholder';

export const supabase = createClient(url, key);

// Helper to check if we are actually connected to a real backend
export const isSupabaseConfigured = (): boolean => {
  return url !== PLACEHOLDER_URL && key !== 'placeholder';
};

import { supabase, isSupabaseConfigured } from './supabaseClient';
import { QuizData, SavedQuiz } from '../types';

/* 
  SUPABASE TABLE SCHEMA REQUIREMENT:
  Table Name: 'quizzes'
  Columns:
    - id: uuid (Primary Key, default: gen_random_uuid())
    - user_id: uuid (To group quizzes by device/browser)
    - data: jsonb (Stores the full quiz object)
    - created_at: timestamptz (default: now())
*/

const LOCAL_STORAGE_KEY = 'lumiere_local_quizzes';

// Generate a random ID for the browser session to group quizzes
const getUserId = () => {
  const KEY = 'lumiere_device_id';
  let id = localStorage.getItem(KEY);
  if (!id) {
    id = crypto.randomUUID();
    localStorage.setItem(KEY, id);
  }
  return id;
};

// Helper for local storage fallback
const getLocalHistory = (): SavedQuiz[] => {
    try {
        const item = localStorage.getItem(LOCAL_STORAGE_KEY);
        return item ? JSON.parse(item) : [];
    } catch {
        return [];
    }
};

const saveLocalHistory = (quizzes: SavedQuiz[]) => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(quizzes));
};

export const checkSupabaseConnection = async (): Promise<boolean> => {
  // Fail fast if no keys are present
  if (!isSupabaseConfigured()) {
    console.log("Supabase not configured (missing env vars). Using local storage.");
    return false;
  }

  try {
    // Lightweight check: verify we can access the table structure
    const { error } = await supabase
      .from('quizzes')
      .select('*', { count: 'exact', head: true });

    if (error) {
      console.warn("Supabase Access Check Failed:", error.message);
      return false;
    }
    return true;
  } catch (e) {
    console.error("Supabase Connection Error:", e);
    return false;
  }
};

export const saveQuizToHistory = async (quiz: QuizData): Promise<SavedQuiz> => {
  const userId = getUserId();
  const timestamp = Date.now();

  // Try Supabase only if configured
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase
          .from('quizzes')
          .insert([
            { 
              user_id: userId,
              data: quiz 
            }
          ])
          .select()
          .single();

        if (error) throw error;

        return {
          id: data.id,
          created_at: new Date(data.created_at).getTime(),
          data: data.data
        };
    } catch (err: any) {
        console.warn("Supabase save failed (falling back to localStorage):", err.message || err);
    }
  }

  // Fallback to local storage (either if not configured OR if save failed)
  const newSavedQuiz: SavedQuiz = {
      id: crypto.randomUUID(),
      created_at: timestamp,
      data: quiz
  };

  const current = getLocalHistory();
  saveLocalHistory([newSavedQuiz, ...current]);

  return newSavedQuiz;
};

export const getSavedQuizzes = async (): Promise<SavedQuiz[]> => {
  const userId = getUserId();

  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase
          .from('quizzes')
          .select('*')
          .eq('user_id', userId)
          .order('created_at', { ascending: false });

        if (error) throw error;

        return data.map((row: any) => ({
          id: row.id,
          created_at: new Date(row.created_at).getTime(),
          data: row.data
        }));

    } catch (err: any) {
        if (err.code === '42P01') { 
            console.info("Supabase 'quizzes' table not found. Using local storage only.");
        } else {
            console.warn('Error fetching history from Supabase:', err.message || err);
        }
    }
  }

  return getLocalHistory();
};

export const deleteSavedQuiz = async (id: string): Promise<void> => {
  let supabaseFailed = false;

  if (isSupabaseConfigured()) {
    try {
        const { error } = await supabase
          .from('quizzes')
          .delete()
          .eq('id', id);

        if (error) throw error;
    } catch (err) {
        supabaseFailed = true;
    }
  }

  // Always try to delete from local storage as well to keep sync
  try {
      const current = getLocalHistory();
      const updated = current.filter(q => q.id !== id);
      if (current.length !== updated.length) {
          saveLocalHistory(updated);
      } else if (supabaseFailed) {
          console.warn("Could not delete quiz from cloud storage.");
      }
  } catch (e) {
      console.error("Local delete failed", e);
  }
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { QuizSettings, QuizResponse } from "../types";

const SYSTEM_INSTRUCTION = `
You are the "French Quiz Engine," a specialized API endpoint that generates structured JSON quizzes for French language learners. You possess expert knowledge of French grammar, vocabulary, and CEFR proficiency standards.

**Difficulty Matrix Logic:**
You must adjust the complexity based on the combination of CEFR Level and Sub-Difficulty:
- **Easy:** Focus on the core rule/vocabulary. Simple sentence structures (SVO). High-frequency words.
- **Medium:** Introduce standard sentence structures, slight nuances, and common variations.
- **Hard:** Test exceptions to the rule, use complex sentence structures, varying tenses, or "faux amis" (false friends).

**Content Requirements:**
1. Generate **5 questions** per request.
2. Mix the question types (MCQ, Fill in blank, Matching) to ensure variety.
3. Ensure all French accents (é, à, ù, ç) are correct.

**Glossary Requirement:**
You MUST include a "glossary" array in the response. 
- Identify key French words used in the questions and answers.
- For each unique word, provide:
  - English definition (context-aware).
  - Phonetics (IPA format).
  - A short example sentence in French using the word.
- Ensure the glossary covers nouns, verbs, and adjectives used in the quiz content.
`;

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    quiz: {
      type: Type.OBJECT,
      properties: {
        title: { type: Type.STRING },
        topic: { type: Type.STRING },
        cefr_level: { type: Type.STRING },
        sub_difficulty: { type: Type.STRING },
        questions: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              type: { type: Type.STRING, enum: ["mcq", "fill_blank", "matching"] },
              question_text: { type: Type.STRING },
              explanation: { type: Type.STRING },
              content: {
                type: Type.OBJECT,
                properties: {
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  correct_answer: { type: Type.STRING },
                  sentence_with_blank: { type: Type.STRING },
                  pairs: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        left: { type: Type.STRING },
                        right: { type: Type.STRING },
                      },
                      required: ["left", "right"],
                    },
                  },
                },
              },
            },
            required: ["id", "type", "question_text", "content", "explanation"],
          },
        },
        glossary: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING, description: "The word in lowercase" },
              definition: { type: Type.STRING, description: "English meaning" },
              phonetics: { type: Type.STRING, description: "IPA pronunciation" },
              example: { type: Type.STRING, description: "Short French example sentence" }
            },
            required: ["word", "definition", "phonetics", "example"]
          }
        }
      },
      required: ["title", "topic", "cefr_level", "sub_difficulty", "questions", "glossary"],
    },
  },
  required: ["quiz"],
};

// Helper to check configuration status
export const checkApiKeyConfigured = (): boolean => {
  return !!process.env.API_KEY;
};

export const generateQuiz = async (settings: QuizSettings): Promise<QuizResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please add API_KEY to your .env file.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Topic: ${settings.topic}
    CEFR Level: ${settings.level}
    Sub-Difficulty: ${settings.difficulty}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-lite",
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.7, 
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as QuizResponse;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

