import React, { useState, useEffect } from 'react';
import { generateQuiz, generateStory, checkApiKeyConfigured } from './services/geminiService';
import { 
    saveQuizToHistory, getSavedQuizzes, deleteSavedQuiz, 
    saveStoryToHistory, getSavedStories, deleteSavedStory,
    checkSupabaseConnection 
} from './services/storageService';
import { QuizSettings, QuizData, StoryData, SavedQuiz, SavedStory } from './types';
import { QuizForm } from './components/QuizForm';
import { QuizInterface } from './components/QuizInterface';
import { StoryInterface } from './components/StoryInterface';
import { QuizHistory } from './components/QuizHistory';
import { StoryHistory } from './components/StoryHistory';
import { BookOpenIcon, AcademicCapIcon, RectangleStackIcon } from '@heroicons/react/24/outline';

type Tab = 'quiz' | 'stories';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('quiz');
  const [cloudStatus, setCloudStatus] = useState<'connected' | 'offline'>('offline');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // --- QUIZ STATE ---
  const [quizData, setQuizData] = useState<QuizData | null>(null);
  const [savedQuizzes, setSavedQuizzes] = useState<SavedQuiz[]>([]);
  const [showQuizHistory, setShowQuizHistory] = useState(false);

  // --- STORY STATE ---
  const [storyData, setStoryData] = useState<StoryData | null>(null);
  const [savedStories, setSavedStories] = useState<SavedStory[]>([]);
  const [showStoryHistory, setShowStoryHistory] = useState(false);

  // Initialize App
  useEffect(() => {
    const initApp = async () => {
        const hasKey = checkApiKeyConfigured();
        const isConnected = await checkSupabaseConnection();
        console.log(`Diagnostic: API Key ${hasKey}, DB ${isConnected}`);
        setCloudStatus(isConnected ? 'connected' : 'offline');

        try {
            const [qHistory, sHistory] = await Promise.all([
                getSavedQuizzes(),
                getSavedStories()
            ]);
            setSavedQuizzes(qHistory);
            setSavedStories(sHistory);
        } catch (e) {
            console.error("Failed to load history", e);
        }
    };
    initApp();
  }, []);

  // --- QUIZ HANDLERS ---
  const handleCreateQuiz = async (settings: QuizSettings) => {
    setLoading(true);
    setError(null);
    try {
      const response = await generateQuiz(settings);
      if (response && response.quiz) {
          setQuizData(response.quiz);
          setShowQuizHistory(false);
          try {
             const saved = await saveQuizToHistory(response.quiz);
             setSavedQuizzes(prev => [saved, ...prev]);
          } catch (e) { console.error("DB Save failed", e); }
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectQuiz = (quiz: QuizData) => {
    setQuizData(quiz);
    setShowQuizHistory(false);
  };

  const handleDeleteQuiz = async (id: string) => {
    const prev = savedQuizzes;
    setSavedQuizzes(p => p.filter(q => q.id !== id));
    try { await deleteSavedQuiz(id); } 
    catch { setSavedQuizzes(prev); }
  };

  const closeQuiz = () => {
      setQuizData(null);
  };

  // --- STORY HANDLERS ---
  const handleCreateStory = async (settings: QuizSettings) => {
    setLoading(true);
    setError(null);
    try {
      const response = await generateStory(settings);
      if (response && response.story) {
          setStoryData(response.story);
          setShowStoryHistory(false);
          try {
             const saved = await saveStoryToHistory(response.story);
             setSavedStories(prev => [saved, ...prev]);
          } catch (e) { console.error("DB Save failed", e); }
      }
    } catch (err: any) {
        setError(err.message);
    } finally {
        setLoading(false);
    }
  };

  const handleSelectStory = (story: StoryData) => {
      setStoryData(story);
      setShowStoryHistory(false);
  };

  const handleDeleteStory = async (id: string) => {
      const prev = savedStories;
      setSavedStories(p => p.filter(s => s.id !== id));
      try { await deleteSavedStory(id); }
      catch { setSavedStories(prev); }
  };

  const closeStory = () => {
      setStoryData(null);
  };

  // --- RENDER HELPERS ---

  const renderQuizTab = () => {
      if (quizData) {
          return <div className="animate-fade-in-up w-full"><QuizInterface quiz={quizData} onRestart={closeQuiz} /></div>;
      }
      if (showQuizHistory) {
          return (
            <QuizHistory 
                quizzes={savedQuizzes} 
                onSelect={handleSelectQuiz} 
                onDelete={handleDeleteQuiz}
                onBack={() => setShowQuizHistory(false)}
            />
          );
      }
      return (
          <div className="w-full flex flex-col items-center">
              <div className="text-center mb-10 max-w-2xl animate-fade-in">
                  <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 mb-6">Test Your Skills</h1>
                  <p className="text-lg text-slate-500 mb-6">
                      Generate adaptive quizzes tailored to your proficiency level.
                  </p>
                  {savedQuizzes.length > 0 && (
                      <button 
                        onClick={() => setShowQuizHistory(true)}
                        className="inline-flex items-center gap-2 px-5 py-2 bg-white border border-slate-200 rounded-full text-slate-600 text-sm font-medium hover:text-french-blue hover:border-french-blue transition-colors shadow-sm"
                      >
                          <RectangleStackIcon className="w-4 h-4" />
                          View Saved Quizzes ({savedQuizzes.length})
                      </button>
                  )}
              </div>
              <div className="animate-fade-in-up w-full flex justify-center">
                  <QuizForm onSubmit={handleCreateQuiz} isLoading={loading} />
              </div>
          </div>
      );
  };

  const renderStoryTab = () => {
      if (storyData) {
          return <div className="animate-fade-in-up w-full"><StoryInterface story={storyData} onBack={closeStory} /></div>;
      }
      if (showStoryHistory) {
          return (
            <StoryHistory 
                stories={savedStories}
                onSelect={handleSelectStory}
                onDelete={handleDeleteStory}
                onBack={() => setShowStoryHistory(false)}
            />
          );
      }
      return (
          <div className="w-full flex flex-col items-center">
              <div className="text-center mb-10 max-w-2xl animate-fade-in">
                  <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 mb-6">Learn through Stories</h1>
                  <p className="text-lg text-slate-500 mb-6">
                      Generate immersive short stories with instant hover-translation.
                  </p>
                  {savedStories.length > 0 && (
                      <button 
                        onClick={() => setShowStoryHistory(true)}
                        className="inline-flex items-center gap-2 px-5 py-2 bg-white border border-slate-200 rounded-full text-slate-600 text-sm font-medium hover:text-french-blue hover:border-french-blue transition-colors shadow-sm"
                      >
                          <RectangleStackIcon className="w-4 h-4" />
                          View Saved Stories ({savedStories.length})
                      </button>
                  )}
              </div>
              <div className="animate-fade-in-up w-full flex justify-center">
                  <QuizForm onSubmit={handleCreateStory} isLoading={loading} />
              </div>
          </div>
      );
  };

  return (
    <div className="min-h-screen flex flex-col font-sans bg-slate-50 text-slate-900 selection:bg-french-blue selection:text-white">
      {/* Navbar */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => { setQuizData(null); setStoryData(null); }}>
             <div className="flex h-6 w-8 shadow-sm border border-slate-100 rounded-sm overflow-hidden">
                <div className="w-1/3 bg-french-blue h-full"></div>
                <div className="w-1/3 bg-french-white h-full"></div>
                <div className="w-1/3 bg-french-red h-full"></div>
             </div>
             <h1 className="font-serif font-bold text-xl tracking-tight text-slate-800">Lumière</h1>
          </div>

          <nav className="flex gap-2 bg-slate-100 p-1 rounded-full">
              <button 
                onClick={() => setActiveTab('quiz')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${activeTab === 'quiz' ? 'bg-white shadow-sm text-french-blue' : 'text-slate-500 hover:text-slate-700'}`}
              >
                  <AcademicCapIcon className="w-4 h-4" />
                  Quiz
              </button>
              <button 
                onClick={() => setActiveTab('stories')}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${activeTab === 'stories' ? 'bg-white shadow-sm text-french-blue' : 'text-slate-500 hover:text-slate-700'}`}
              >
                  <BookOpenIcon className="w-4 h-4" />
                  Stories
              </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow container mx-auto px-4 py-12 flex flex-col items-center justify-center">

        {error && (
            <div className="mb-8 w-full max-w-lg bg-red-50 border-l-4 border-red-500 p-4 rounded shadow-sm animate-fade-in">
                <p className="text-sm text-red-700">{error}</p>
            </div>
        )}

        {activeTab === 'quiz' ? renderQuizTab() : renderStoryTab()}

      </main>

      {/* Footer */}
      <footer className="py-8 text-center text-slate-400 text-sm flex flex-col items-center gap-2">
        <p>&copy; {new Date().getFullYear()} Lumière French Engine. Powered by Google Gemini.</p>
        <div className="flex items-center gap-2 text-xs font-medium" title={cloudStatus === 'offline' ? "Check console for .env diagnostic" : "Connected"}>
             {cloudStatus === 'connected' ? (
                 <span className="flex items-center gap-1.5 text-green-600 bg-green-50 px-2 py-1 rounded-full border border-green-100">
                     <span className="relative flex h-2 w-2"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span><span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span></span>
                     Database Connected
                 </span>
             ) : (
                 <span className="flex items-center gap-1.5 text-slate-500 bg-slate-100 px-2 py-1 rounded-full border border-slate-200">
                     <span className="inline-flex rounded-full h-2 w-2 bg-slate-400"></span>
                     Local Mode
                 </span>
             )}
        </div>
      </footer>

      <style>{`
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in {
            animation: fadeIn 0.4s ease-out forwards;
        }
        .animate-fade-in-up {
            animation: fadeIn 0.6s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { QuizSettings, QuizResponse, StoryResponse } from "../types";

const SYSTEM_INSTRUCTION = `
You are the "French Quiz Engine," a specialized API endpoint that generates structured JSON quizzes for French language learners. You possess expert knowledge of French grammar, vocabulary, and CEFR proficiency standards.

**Difficulty Matrix Logic:**
You must adjust the complexity based on the combination of CEFR Level and Sub-Difficulty:
- **Easy:** Focus on the core rule/vocabulary. Simple sentence structures (SVO). High-frequency words.
- **Medium:** Introduce standard sentence structures, slight nuances, and common variations.
- **Hard:** Test exceptions to the rule, use complex sentence structures, varying tenses, or "faux amis" (false friends).

**Content Requirements:**
1. Generate **10 questions** per request.
2. Mix the question types (MCQ, Fill in blank, Matching) to ensure variety.
3. Ensure all French accents (é, à, ù, ç) are correct.
4. **Fill-in-the-blank Rule:** For 'fill_blank' questions, you MUST use exactly five underscores '_____' to denote the missing word in the 'sentence_with_blank' field. Do not use ellipses (...) or brackets.

**Glossary Requirement:**
You MUST include a "glossary" array in the response. 
- Identify key French words used in the questions and answers.
- For each unique word, provide:
  - English definition (context-aware).
  - Phonetics (IPA format).
  - A short example sentence in French using the word.
- Ensure the glossary covers nouns, verbs, and adjectives used in the quiz content.
`;

const STORY_SYSTEM_INSTRUCTION = `
You are a French Storyteller Engine. You write engaging, level-appropriate short stories in French.

**Difficulty Matrix Logic:**
- **Easy:** Simple sentences, core vocabulary, present tense mostly.
- **Medium:** Compound sentences, varied tenses (Passé Composé, Imparfait).
- **Hard:** Literary tenses (Passé Simple), complex relative clauses, subjunctive.

**Output:**
Return a valid JSON object.
- **content**: A short story (approx 150-300 words). Use '\\n' to separate paragraphs.
- **glossary**: A COMPREHENSIVE array of glossary entries for the words used in the story.
  - CRITICAL: To support a "hover to translate" feature, you must generate glossary entries for the majority of words in the text (nouns, verbs, adjectives, adverbs, prepositions).
  - The 'word' field in the glossary MUST match the EXACT spelling/conjugation found in the text so it can be automatically linked (e.g. if text has "mangé", glossary word should be "mangé" or "a mangé", but ideally just the word token "mangé").
  - If a word appears multiple times, include it once.
`;

const RESPONSE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    quiz: {
      type: Type.OBJECT,
      properties: {
        title: { type: Type.STRING },
        topic: { type: Type.STRING },
        cefr_level: { type: Type.STRING },
        sub_difficulty: { type: Type.STRING },
        questions: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              type: { type: Type.STRING, enum: ["mcq", "fill_blank", "matching"] },
              question_text: { type: Type.STRING },
              explanation: { type: Type.STRING },
              content: {
                type: Type.OBJECT,
                properties: {
                  options: { type: Type.ARRAY, items: { type: Type.STRING } },
                  correct_answer: { type: Type.STRING },
                  sentence_with_blank: { type: Type.STRING },
                  pairs: {
                    type: Type.ARRAY,
                    items: {
                      type: Type.OBJECT,
                      properties: {
                        left: { type: Type.STRING },
                        right: { type: Type.STRING },
                      },
                      required: ["left", "right"],
                    },
                  },
                },
              },
            },
            required: ["id", "type", "question_text", "content", "explanation"],
          },
        },
        glossary: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING, description: "The word in lowercase" },
              definition: { type: Type.STRING, description: "English meaning" },
              phonetics: { type: Type.STRING, description: "IPA pronunciation" },
              example: { type: Type.STRING, description: "Short French example sentence" }
            },
            required: ["word", "definition", "phonetics", "example"]
          }
        }
      },
      required: ["title", "topic", "cefr_level", "sub_difficulty", "questions", "glossary"],
    },
  },
  required: ["quiz"],
};

const STORY_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    story: {
      type: Type.OBJECT,
      properties: {
        title: { type: Type.STRING },
        topic: { type: Type.STRING },
        cefr_level: { type: Type.STRING },
        sub_difficulty: { type: Type.STRING },
        content: { type: Type.STRING },
        glossary: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              word: { type: Type.STRING },
              definition: { type: Type.STRING },
