// Helper to check configuration status
export const checkApiKeyConfigured = (): boolean => {
  return !!process.env.API_KEY;
};

export const generateQuiz = async (settings: QuizSettings): Promise<QuizResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please add API_KEY to your .env file.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Topic: ${settings.topic}
    CEFR Level: ${settings.level}
    Sub-Difficulty: ${settings.difficulty}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-lite",
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: RESPONSE_SCHEMA,
        temperature: 0.7, 
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as QuizResponse;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const generateStory = async (settings: QuizSettings): Promise<StoryResponse> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please add API_KEY to your .env file.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    Topic: ${settings.topic}
    CEFR Level: ${settings.level}
    Sub-Difficulty: ${settings.difficulty}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-lite",
      contents: prompt,
      config: {
        systemInstruction: STORY_SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: STORY_SCHEMA,
        temperature: 0.8, // Slightly higher for creativity
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    return JSON.parse(text) as StoryResponse;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Question, GlossaryEntry } from '../types';
import { InteractiveText } from './InteractiveText';
import { PencilSquareIcon } from '@heroicons/react/24/solid';

interface BaseQuestionProps {
  question: Question;
  glossary: GlossaryEntry[];
  currentAnswer: any;
  onAnswer: (answer: any) => void;
  isSubmitted: boolean;
}

// --- MCQ Component ---
export const McqQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted }) => {
  const options = question.content.options || [];

  return (
    <div className="space-y-3">
      {options.map((option, idx) => {
        const isSelected = currentAnswer === option;
        const isCorrect = isSubmitted && option === question.content.correct_answer;
        const isWrong = isSubmitted && isSelected && option !== question.content.correct_answer;

        let baseClasses = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center group relative";

        if (isSubmitted) {
            if (isCorrect) baseClasses += " bg-green-50 border-green-500 text-green-900";
            else if (isWrong) baseClasses += " bg-red-50 border-red-500 text-red-900";
            else baseClasses += " border-gray-200 opacity-60";
        } else {
            if (isSelected) baseClasses += " border-french-blue bg-blue-50 text-french-blue ring-1 ring-french-blue";
            else baseClasses += " border-gray-200 hover:bg-gray-50 hover:border-gray-300";
        }

        return (
          <button
            key={idx}
            onClick={() => !isSubmitted && onAnswer(option)}
            disabled={isSubmitted}
            className={baseClasses}
          >
            <div className={`w-5 h-5 rounded-full border mr-3 flex-shrink-0 flex items-center justify-center ${isSelected ? 'border-french-blue' : 'border-gray-400'}`}>
                {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-french-blue" />}
            </div>
            {/* 
               Note: We use InteractiveText here. 
               However, since clicking the button selects the answer, we need to make sure tooltip interaction doesn't conflict. 
               The tooltip is hover-only, so it generally works fine.
            */}
            <span className="font-medium text-lg flex-grow">
                <InteractiveText text={option} glossary={glossary} />
            </span>
          </button>
        );
      })}
    </div>
  );
};

// --- Fill In Blank Component ---
export const FillBlankQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted }) => {
  // Safe split: AI is instructed to use "_____" but we check carefully.
  const rawParts = (question.content.sentence_with_blank || "").split("_____");
  const parts = rawParts.length >= 2 ? rawParts : ["", ""];

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onAnswer(e.target.value);
  };

  const isCorrect = isSubmitted && 
    (currentAnswer || "").toLowerCase().trim() === (question.content.correct_answer || "").toLowerCase().trim();

  return (
    <div className="py-8 px-4 bg-slate-50 rounded-xl border border-slate-200 flex flex-col items-center">
      <div className="text-xl md:text-2xl leading-[2.5] text-slate-800 font-serif text-center w-full max-w-2xl">
        <InteractiveText text={parts[0]} glossary={glossary} className="mr-1" />

        <span className="inline-block relative align-baseline mx-1 group">
            <input
                type="text"
                value={currentAnswer || ''}
                onChange={handleChange}
                disabled={isSubmitted}
                placeholder="type answer"
                autoComplete="off"
                className={`
                    min-w-[140px] px-2 py-0.5 border-b-2 text-center bg-transparent 
                    focus:outline-none transition-all font-bold placeholder:text-slate-300 placeholder:font-sans placeholder:text-base
                    ${isSubmitted 
                        ? (isCorrect ? 'border-green-500 text-green-700 bg-green-50/50' : 'border-red-500 text-red-700 bg-red-50/50') 
                        : 'border-slate-300 focus:border-french-blue text-french-blue focus:bg-white/50'
                    }
                `}
            />
            {/* Edit Icon hint (only when not submitted and empty) */}
            {!isSubmitted && !currentAnswer && (
                 <PencilSquareIcon className="w-4 h-4 text-slate-300 absolute -top-4 right-0 opacity-0 group-hover:opacity-100 transition-opacity" />
            )}
        </span>

        <InteractiveText text={parts[1] || ""} glossary={glossary} className="ml-1" />
      </div>

      {/* Answer Feedback */}
      {isSubmitted && !isCorrect && (
          <div className="mt-6 flex flex-col items-center animate-fade-in">
              <span className="text-xs uppercase tracking-wider font-bold text-slate-400 mb-1">Correct Answer</span>
              <div className="px-4 py-2 bg-green-100 text-green-800 rounded-lg font-bold shadow-sm border border-green-200">
                 {question.content.correct_answer}
              </div>
          </div>
      )}
    </div>
  );
};

// --- Matching Component ---
export const MatchingQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted }) => {
  const answerMap = (currentAnswer as Record<string, string>) || {};

  const [shuffledRight, setShuffledRight] = useState<string[]>([]);
  const [selectedLeft, setSelectedLeft] = useState<string | null>(null);

  useEffect(() => {
    if (question.content.pairs) {
      const rights = question.content.pairs.map(p => p.right);
      setShuffledRight([...rights].sort(() => Math.random() - 0.5));
    }
  }, [question.id]);

  const pairs = question.content.pairs || [];

  const handleLeftClick = (left: string) => {
    if (isSubmitted) return;
    if (selectedLeft === left) {
        setSelectedLeft(null);
        return;
    }
    setSelectedLeft(left);
  };

  const handleRightClick = (right: string) => {
    if (isSubmitted || !selectedLeft) return;
    const newAnswers = { ...answerMap, [selectedLeft]: right };
    onAnswer(newAnswers);
    setSelectedLeft(null);
  };

  const isPairCorrect = (left: string, right: string) => {
      const correctRight = pairs.find(p => p.left === left)?.right;
      return correctRight === right;
  };

  return (
    <div className="grid grid-cols-2 gap-8 relative">
      {/* Left Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2">Term</h4>
        {pairs.map((pair, idx) => {
          const isSelected = selectedLeft === pair.left;
          const matchedRight = answerMap[pair.left];
          const isCompleted = !!matchedRight;

          let borderColor = "border-slate-200";
          let bgColor = "bg-white";

          if (isSubmitted) {
             if (isCompleted && isPairCorrect(pair.left, matchedRight)) {
                 borderColor = "border-green-400";
                 bgColor = "bg-green-50";
             } else if (isCompleted) {
                 borderColor = "border-red-400";
                 bgColor = "bg-red-50";
             }
          } else {
             if (isSelected) {
                 borderColor = "border-french-blue";
                 bgColor = "bg-blue-50";
             } else if (isCompleted) {
                 borderColor = "border-slate-300";
                 bgColor = "bg-slate-50";
             }
          }

          return (
            <button
              key={`left-${idx}`}
              onClick={() => handleLeftClick(pair.left)}
              disabled={isSubmitted}
              className={`w-full p-3 text-left border rounded-md text-sm font-medium transition-all ${borderColor} ${bgColor} relative`}
            >
              <InteractiveText text={pair.left} glossary={glossary} />
              {matchedRight && (
                  <span className="absolute right-2 top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-slate-300"></span>
              )}
            </button>
          );
        })}
      </div>

      {/* Right Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2">Match</h4>
        {shuffledRight.map((rightItem, idx) => {
           const isUsed = Object.values(answerMap).includes(rightItem);

           let borderColor = "border-slate-200";
           let opacity = "opacity-100";

           if (isSubmitted) {
                const leftKey = Object.keys(answerMap).find(key => answerMap[key] === rightItem);
                if (leftKey) {
                    if (isPairCorrect(leftKey, rightItem)) {
                        borderColor = "border-green-400 bg-green-50";
                    } else {
                        borderColor = "border-red-400 bg-red-50";
                    }
                }
           } else {
               if (isUsed) {
                   borderColor = "border-slate-300 bg-slate-100 text-slate-400";
               }
           }

          return (
            <button
              key={`right-${idx}`}
              onClick={() => handleRightClick(rightItem)}
              disabled={isSubmitted || (isUsed && !isSubmitted)}
              className={`w-full p-3 text-left border rounded-md text-sm transition-all ${borderColor} ${opacity}`}
            >
              <InteractiveText text={rightItem} glossary={glossary} />
            </button>
          );
        })}
      </div>

      {!isSubmitted && (
          <div className="col-span-2 text-center text-xs text-slate-400 mt-2">
            Select an item on the left, then click the matching item on the right.
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { QuizData, UserAnswerValue, Question } from '../types';
import { McqQuestion, FillBlankQuestion, MatchingQuestion } from './QuestionRenderers';
import { InteractiveText } from './InteractiveText';
import { CheckCircleIcon, XCircleIcon, ArrowRightIcon, ArrowPathIcon, CheckIcon } from '@heroicons/react/24/solid';

interface QuizInterfaceProps {
  quiz: QuizData;
  onRestart: () => void;
}

export const QuizInterface: React.FC<QuizInterfaceProps> = ({ quiz, onRestart }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, UserAnswerValue>>({});
  const [checkedState, setCheckedState] = useState<Record<number, boolean>>({});
  const [isFinished, setIsFinished] = useState(false);
  const [score, setScore] = useState(0);

  const currentQuestion = quiz.questions[currentIndex];
  const glossary = quiz.glossary || [];
  const isChecked = !!checkedState[currentQuestion.id];

  const handleAnswer = (val: UserAnswerValue) => {
    if (isChecked) return; // Prevent changing answer after checking
    setAnswers(prev => ({ ...prev, [currentQuestion.id]: val }));
  };

  const checkCorrectness = (q: Question, ans: UserAnswerValue) => {
      if (!ans) return false;
      if (q.type === 'mcq') {
        return ans === q.content.correct_answer;
      } else if (q.type === 'fill_blank') {
        return typeof ans === 'string' && ans.toLowerCase().trim() === (q.content.correct_answer || '').toLowerCase().trim();
      } else if (q.type === 'matching') {
        const userPairs = ans as Record<string, string>;
        const correctPairs = q.content.pairs || [];
        // Must match all pairs
        if (Object.keys(userPairs).length !== correctPairs.length) return false;
        return correctPairs.every(p => userPairs[p.left] === p.right);
      }
      return false;
  };

  const handleCheck = () => {
    const ans = answers[currentQuestion.id];
    const isCorrect = checkCorrectness(currentQuestion, ans);

    if (isCorrect) {
        setScore(prev => prev + 1);
    }
    setCheckedState(prev => ({ ...prev, [currentQuestion.id]: true }));
  };

  const handleNext = () => {
    if (currentIndex < quiz.questions.length - 1) {
        setCurrentIndex(prev => prev + 1);
    } else {
        setIsFinished(true);
    }
  };

  const isCurrentCorrect = isChecked && checkCorrectness(currentQuestion, answers[currentQuestion.id]);

  const canCheck = () => {
      const ans = answers[currentQuestion.id];
      if (!ans) return false;
      if (currentQuestion.type === 'matching') {
           const pairs = currentQuestion.content.pairs || [];
           const userPairs = ans as Record<string, string>;
           return Object.keys(userPairs).length === pairs.length;
      }
      if (typeof ans === 'string' && ans.trim() === '') return false;
      return true;
  };

  const isLastQuestion = currentIndex === quiz.questions.length - 1;
  const progress = ((currentIndex + (isChecked ? 1 : 0)) / quiz.questions.length) * 100;

  // -- Results View (Final Summary) --
  if (isFinished) {
    const percentage = Math.round((score / quiz.questions.length) * 100);
    let feedback = "Bon effort!";
    if (percentage === 100) feedback = "Excellent! Parfait!";
    else if (percentage >= 80) feedback = "Très bien!";
    else if (percentage >= 60) feedback = "Bien joué.";

    return (
      <div className="max-w-2xl mx-auto bg-white rounded-2xl shadow-xl overflow-hidden animate-fade-in">
        <div className="bg-french-blue text-white p-8 text-center">
            <h2 className="text-3xl font-serif font-bold mb-2">{feedback}</h2>
            <p className="opacity-90">You scored {score} out of {quiz.questions.length}</p>
        </div>

        <div className="p-8 space-y-4">
            <h3 className="font-bold text-slate-800 text-lg mb-4">Summary</h3>
            {quiz.questions.map((q, idx) => {
                const ans = answers[q.id];
                const correct = checkCorrectness(q, ans);

                return (
                    <div key={q.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-lg border border-slate-100">
                        <div className="flex items-center gap-3">
                             {correct ? (
                                 <CheckCircleIcon className="w-5 h-5 text-green-500" />
                             ) : (
                                 <XCircleIcon className="w-5 h-5 text-red-500" />
                             )}
                             <span className="text-sm font-medium text-slate-700">Question {idx+1}</span>
                        </div>
                        <div className="text-sm text-slate-500">
                            {correct ? "Correct" : "Incorrect"}
                        </div>
                    </div>
                );
            })}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-center">
            <button 
                onClick={onRestart}
                className="flex items-center gap-2 px-8 py-3 bg-french-dark text-white rounded-full font-medium hover:bg-black transition-colors shadow-lg hover:shadow-xl"
            >
                <ArrowPathIcon className="w-5 h-5" />
                Generate New Quiz
            </button>
        </div>
      </div>
    );
  }

  // -- Active Quiz View --
  return (
    <div className="max-w-2xl mx-auto">
      {/* Header Info */}
      <div className="mb-8 flex items-center justify-between text-slate-600">
        <span className="font-serif italic text-french-blue font-bold">{quiz.topic}</span>
        <span className="bg-slate-200 text-xs font-bold px-2 py-1 rounded text-slate-600">{quiz.cefr_level} • {quiz.sub_difficulty}</span>
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-gray-200 rounded-full h-2 mb-8">
        <div 
            className="bg-french-blue h-2 rounded-full transition-all duration-500 ease-out" 
            style={{ width: `${progress}%` }}
        ></div>
      </div>

      {/* Card */}
      <div className="bg-white rounded-2xl shadow-xl p-8 min-h-[400px] flex flex-col relative overflow-visible z-10 transition-all">

        {/* Question Header */}
        <div className="mb-6">
            <div className="flex justify-between items-start">
                <span className="text-xs font-bold tracking-widest text-slate-400 uppercase">Question {currentIndex + 1} of {quiz.questions.length}</span>
                {isChecked && (
                    <span className={`flex items-center gap-1 text-sm font-bold ${isCurrentCorrect ? 'text-green-600' : 'text-red-500'}`}>
                        {isCurrentCorrect ? (
                            <>
                                <CheckCircleIcon className="w-5 h-5" /> Correct
                            </>
                        ) : (
                            <>
                                <XCircleIcon className="w-5 h-5" /> Incorrect
                            </>
                        )}
                    </span>
                )}
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mt-2 font-serif leading-tight">
                <InteractiveText text={currentQuestion.question_text} glossary={glossary} />
            </h2>
        </div>

        {/* Question Content */}
        <div className="flex-grow">
            {currentQuestion.type === 'mcq' && (
                <McqQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={isChecked} 
                />
            )}
            {currentQuestion.type === 'fill_blank' && (
                <FillBlankQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={isChecked} 
                />
            )}
            {currentQuestion.type === 'matching' && (
                <MatchingQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={isChecked} 
                />
            )}
        </div>

        {/* Explanation Block (Immediate Feedback) */}
        {isChecked && (
             <div className={`mt-8 p-5 rounded-xl border animate-fade-in ${isCurrentCorrect ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                 <h4 className={`text-sm font-bold uppercase tracking-wide mb-2 ${isCurrentCorrect ? 'text-green-800' : 'text-red-800'}`}>
                    Explanation
                 </h4>
                 <p className="text-slate-700 leading-relaxed">
                    {currentQuestion.explanation}
                 </p>
             </div>
        )}

        {/* Navigation */}
        <div className="mt-8 pt-6 border-t border-slate-100 flex justify-between items-center">
             <button 
                onClick={() => setCurrentIndex(prev => Math.max(0, prev - 1))}
                disabled={currentIndex === 0}
                className="text-slate-400 hover:text-slate-600 font-medium disabled:opacity-30 px-4 py-2"
             >
                 Back
             </button>

             {!isChecked ? (
                 <button
                    onClick={handleCheck}
                    disabled={!canCheck()}
                    className="flex items-center gap-2 bg-french-dark text-white px-8 py-3 rounded-full font-bold shadow-lg hover:bg-black transition-all disabled:opacity-50 disabled:shadow-none"
                 >
                     Check Answer
                     <CheckIcon className="w-4 h-4" />
                 </button>
             ) : (
                 <button
                    onClick={handleNext}
                    className="flex items-center gap-2 bg-french-blue text-white px-8 py-3 rounded-full font-bold shadow-lg hover:bg-blue-700 hover:shadow-xl transition-all"
                 >
                     {isLastQuestion ? "Finish Quiz" : "Next Question"}
                     <ArrowRightIcon className="w-4 h-4" />
                 </button>
             )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { QuizSettings, CefrLevel, Difficulty } from '../types';
import { ChevronRightIcon, ArrowLeftIcon, SparklesIcon } from '@heroicons/react/24/solid';

interface QuizFormProps {
  onSubmit: (settings: QuizSettings) => void;
  isLoading: boolean;
  mode: 'quiz' | 'story';
}

const LEVELS: { id: CefrLevel; label: string; desc: string }[] = [
  { id: 'A1', label: 'A1 Beginner', desc: 'Basic vocabulary and simple sentences' },
  { id: 'A2', label: 'A2 Elementary', desc: 'Routine tasks and familiar topics' },
  { id: 'B1', label: 'B1 Intermediate', desc: 'Standard speech and opinions' },
  { id: 'B2', label: 'B2 Upper Inter.', desc: 'Complex texts and fluency' },
];

const TOPICS_BY_LEVEL: Record<CefrLevel, string[]> = {
  'A1': ['Greetings & Introductions', 'Numbers & Colors', 'Family & Friends', 'Food & Drink', 'Present Tense Verbs', 'Common Adjectives'],
  'A2': ['Daily Routine', 'Shopping & Clothing', 'Travel & Directions', 'Passé Composé', 'Future Proche', 'House & Home'],
  'B1': ['Work & Education', 'Holidays & Culture', 'Imparfait vs Passé Composé', 'Future Simple', 'Pronouns (y, en)', 'Health & Fitness'],
  'B2': ['Media & News', 'Environment', 'Subjunctive Mood', 'Conditional Tenses', 'Abstract Concepts', 'Politics & Society'],
};

const DIFFICULTIES: { id: Difficulty; label: string; desc: string }[] = [
  { id: 'Easy', label: 'Easy', desc: 'Core rules, simple structures' },
  { id: 'Medium', label: 'Medium', desc: 'Standard nuances and variations' },
  { id: 'Hard', label: 'Hard', desc: 'Complex cases and exceptions' },
];

export const QuizForm: React.FC<QuizFormProps> = ({ onSubmit, isLoading, mode }) => {
  const [step, setStep] = useState(1);
  const [level, setLevel] = useState<CefrLevel | null>(null);
  const [topic, setTopic] = useState<string>('');
  const [customTopic, setCustomTopic] = useState('');
  const [difficulty, setDifficulty] = useState<Difficulty | null>(null);

  const handleLevelSelect = (lvl: CefrLevel) => {
    setLevel(lvl);
    if (mode === 'story') {
      // Skip topic selection for stories, default to Surprise Me
      setTopic('Surprise Me');
      setStep(3);
    } else {
      setTopic(''); // Reset topic if level changes
      setStep(2);
    }
  };

  const handleTopicSelect = (t: string) => {
    setTopic(t);
    setStep(3);
  };

  const handleCustomTopicSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (customTopic.trim()) {
      setTopic(customTopic);
      setStep(3);
    }
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    setDifficulty(diff);
    // Proceed to submit if we have level and topic
    if (level && (topic || customTopic)) {
      onSubmit({ 
        level: level, 
        topic: topic || customTopic, 
        difficulty: diff 
      });
    }
  };

  const handleBack = () => {
    // If in story mode and at step 3, go back to step 1 (skipping step 2)
    if (mode === 'story' && step === 3) {
      setStep(1);
    } else {
      setStep(prev => prev - 1);
    }
  };

  if (isLoading) {
    const isQuiz = mode === 'quiz';
    return (
       <div className="w-full max-w-2xl mx-auto bg-white rounded-2xl shadow-xl p-12 flex flex-col items-center justify-center min-h-[400px]">
          <div className="relative mb-8">
            <div className="w-20 h-20 border-4 border-slate-100 rounded-full"></div>
            <div className={`w-20 h-20 border-4 ${isQuiz ? 'border-french-blue' : 'border-french-red'} rounded-full border-t-transparent animate-spin absolute top-0 left-0`}></div>
          </div>
          <h3 className="text-2xl font-serif font-bold text-slate-800 animate-pulse">
            {isQuiz ? "Génération du Quiz..." : "Rédaction de l'Histoire..."}
          </h3>
          <p className="text-slate-500 mt-2">
             {isQuiz 
               ? `Crafting your custom exercises tailored to ${level} • ${topic}`
               : `Writing a creative story for ${level} proficiency...`
             }
          </p>
       </div>
    );
  }

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-2xl shadow-xl overflow-hidden min-h-[500px] flex flex-col transition-all duration-300">
      {/* Header */}
      <div className="bg-french-dark p-6 text-center relative">
         <div className={`absolute top-0 left-0 w-full h-1 bg-gradient-to-r ${mode === 'quiz' ? 'from-french-blue via-white to-french-blue' : 'from-french-red via-white to-french-red'}`}></div>
         {step > 1 && (
             <button onClick={handleBack} className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white transition-colors p-2">
                 <ArrowLeftIcon className="w-6 h-6" />
             </button>
         )}
         <h2 className="text-2xl font-serif text-white font-bold tracking-wide">
            {step === 1 && "Select Level"}
            {step === 2 && "Choose Topic"}
            {step === 3 && "Select Difficulty"}
         </h2>
         <div className="flex justify-center gap-2 mt-4">
             {/* Dynamic Progress Dots */}
             {(mode === 'story' ? [1, 3] : [1, 2, 3]).map((i, idx) => (
                 <div key={i} className={`h-1.5 rounded-full transition-all duration-500 ${step >= i ? `w-12 ${mode === 'quiz' ? 'bg-french-blue' : 'bg-french-red'}` : 'w-3 bg-slate-700'}`} />
             ))}
         </div>
      </div>

      <div className="p-8 flex-grow flex flex-col">
        {/* Step 1: Level */}
        {step === 1 && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in flex-grow">
                {LEVELS.map((lvl) => (
                    <button
                        key={lvl.id}
                        onClick={() => handleLevelSelect(lvl.id)}
                        className={`group relative p-6 border-2 border-slate-100 rounded-xl hover:bg-blue-50/30 transition-all text-left flex flex-col justify-center ${mode === 'quiz' ? 'hover:border-french-blue' : 'hover:border-french-red'}`}
                    >
                        <span className="text-4xl font-black text-slate-100 group-hover:text-slate-200 absolute right-4 top-4 transition-colors">{lvl.id}</span>
                        <h3 className={`text-lg font-bold text-slate-800 mb-1 transition-colors ${mode === 'quiz' ? 'group-hover:text-french-blue' : 'group-hover:text-french-red'}`}>{lvl.label}</h3>
                        <p className="text-sm text-slate-500 leading-relaxed group-hover:text-slate-600">{lvl.desc}</p>
                    </button>
                ))}
            </div>
        )}

        {/* Step 2: Topic (Quiz Only) */}
        {step === 2 && level && mode === 'quiz' && (
            <div className="animate-fade-in flex flex-col h-full">
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3 mb-8">
                    {TOPICS_BY_LEVEL[level].map((t) => (
                        <button
                            key={t}
                            onClick={() => handleTopicSelect(t)}
                            className="p-4 border border-slate-200 rounded-xl hover:border-french-blue hover:bg-blue-50 text-slate-700 font-medium hover:text-french-blue transition-all text-center flex items-center justify-center h-full text-sm md:text-base shadow-sm hover:shadow-md"
                        >
                            {t}
                        </button>
                    ))}
                </div>

                <div className="mt-auto border-t border-slate-100 pt-6">
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 text-center">Or type your own</p>
                    <form onSubmit={handleCustomTopicSubmit} className="flex gap-2">
                        <input 
                            type="text" 
                            value={customTopic}
                            onChange={(e) => setCustomTopic(e.target.value)}
                            placeholder="e.g. French Cinema, Slang, History..."
                            className="flex-grow px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:border-french-blue focus:ring-1 focus:ring-french-blue outline-none transition-all"
                        />
                        <button 
                            type="submit"
                            disabled={!customTopic.trim()}
                            className="px-6 py-3 bg-slate-800 text-white rounded-xl font-medium hover:bg-slate-900 disabled:opacity-50 transition-colors shadow-md"
                        >
                            Next
                        </button>
                    </form>
                </div>
            </div>
        )}

        {/* Step 3: Difficulty */}
        {step === 3 && (
            <div className="flex flex-col gap-4 animate-fade-in max-w-md mx-auto w-full my-auto">
                <div className="mb-4 text-center">
                   {mode === 'story' && (
                     <div className="inline-flex items-center gap-2 px-4 py-2 bg-yellow-50 text-yellow-700 rounded-full text-sm font-medium border border-yellow-200 mb-4">
                        <SparklesIcon className="w-4 h-4" />
                        Topic: Surprise Me
                     </div>
                   )}
                </div>

                {DIFFICULTIES.map((diff) => (
                    <button
                        key={diff.id}
                        onClick={() => handleDifficultySelect(diff.id)}
                        className={`group flex items-center p-5 border-2 border-slate-100 rounded-xl hover:bg-blue-50 transition-all text-left shadow-sm hover:shadow-md ${mode === 'quiz' ? 'hover:border-french-blue' : 'hover:border-french-red'}`}
                    >
                        <div className={`w-12 h-12 rounded-full flex items-center justify-center mr-5 transition-colors flex-shrink-0 ${
                            diff.id === 'Easy' ? 'bg-green-100 text-green-600 group-hover:bg-green-200' :
                            diff.id === 'Medium' ? 'bg-yellow-100 text-yellow-600 group-hover:bg-yellow-200' :
                            'bg-red-100 text-red-600 group-hover:bg-red-200'
                        }`}>
                            {diff.id === 'Easy' && <span className="text-xl">🌱</span>}
                            {diff.id === 'Medium' && <span className="text-xl">🌿</span>}
                            {diff.id === 'Hard' && <span className="text-xl">🌳</span>}
