                    className="group relative p-8 border-2 border-slate-100 dark:border-slate-800 rounded-2xl hover:bg-white dark:hover:bg-slate-800 hover:border-french-blue dark:hover:border-blue-500 transition-all text-left flex flex-col justify-center bg-white dark:bg-slate-900 shadow-sm hover:shadow-xl"
                >
                    <span className="text-5xl font-black text-slate-100 dark:text-slate-700 group-hover:text-blue-50 dark:group-hover:text-slate-600 absolute right-6 top-6 transition-colors">{lvl.id}</span>
                    <h3 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mb-2 group-hover:text-french-blue dark:group-hover:text-blue-400 transition-colors relative z-10">{lvl.label}</h3>
                    <p className="text-slate-500 dark:text-slate-400 leading-relaxed group-hover:text-slate-600 dark:group-hover:text-slate-300 relative z-10">{lvl.desc}</p>
                </button>
            ))}
        </div>
      </div>
    );
  }

  // --- VIEW 2: WORD LIST ---
  if (view === 'list') {
    return (
      <div className="w-full max-w-4xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl min-h-[600px] flex flex-col animate-fade-in transition-colors">
         <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-french-blue dark:bg-slate-800 rounded-t-2xl text-white">
            <div className="flex items-center gap-4">
                <button onClick={goBack} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                    <ArrowLeftIcon className="w-5 h-5" />
                </button>
                <div>
                    <span className="text-xs font-bold uppercase tracking-wider opacity-80">Level {selectedLevel}</span>
                    <h2 className="text-2xl font-serif font-bold">Word Bank</h2>
                </div>
            </div>
         </div>

         <div className="p-8 grid grid-cols-2 md:grid-cols-4 gap-4 overflow-y-auto">
            {wordList.map((item, idx) => (
                <button 
                  key={idx}
                  onClick={() => handleWordSelect(item.word)}
                  className="p-4 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 hover:border-french-blue dark:hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 text-left transition-all group"
                >
                    <div className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase mb-1 flex justify-between">
                        {item.type}
                        <ArrowLeftIcon className="w-3 h-3 rotate-180 opacity-0 group-hover:opacity-100 transition-opacity text-french-blue dark:text-blue-400" />
                    </div>
                    <div className="font-bold text-slate-800 dark:text-slate-100 text-lg mb-1 capitalize">{item.word}</div>
                    <div className="text-sm text-slate-500 dark:text-slate-400 italic truncate">{item.translation}</div>
                </button>
            ))}
         </div>
      </div>
    );
  }

  // --- VIEW 3: DETAIL ---
  const d = selectedWord!;
  const isVerb = d.type === 'verb';

  return (
    <div className="w-full max-w-4xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-hidden animate-fade-in transition-colors">
        {/* Header */}
        <div className="bg-french-dark dark:bg-slate-950 text-white p-8 relative">
            <button onClick={goBack} className="absolute top-8 left-8 p-2 text-slate-400 hover:text-white transition-colors">
                <ArrowLeftIcon className="w-6 h-6" />
            </button>
            <div className="text-center mt-4">
                <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold tracking-wider mb-3 uppercase 
                    ${isVerb ? 'bg-red-500/20 text-red-300 border border-red-500/30' : 'bg-blue-500/20 text-blue-300 border border-blue-500/30'}`}>
                    {d.type}
                </span>
                <h1 className="text-5xl font-serif font-bold mb-2 capitalize">{d.word}</h1>
                <p className="text-xl opacity-90 font-light">{d.translation}</p>
            </div>
            {isVerb && (
                <div className="flex justify-center gap-4 mt-6 text-sm text-slate-400">
                    {d.verb_group && <span>Group: <span className="text-white">{d.verb_group}</span></span>}
                    {d.auxiliary_verb && <span>Aux: <span className="text-white">{d.auxiliary_verb}</span></span>}
                </div>
            )}
        </div>

        <div className="p-8">
            {/* Definition & Examples */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-xl border border-slate-100 dark:border-slate-800">
                    <h3 className="font-bold text-slate-400 dark:text-slate-500 text-xs uppercase tracking-wider mb-4 flex items-center gap-2">
                        <BookOpenIcon className="w-4 h-4" /> Definition
                    </h3>
                    <p className="text-lg text-slate-800 dark:text-slate-200 leading-relaxed mb-4">{d.definition}</p>
                    {d.exceptions_or_notes && (
                        <div className="text-sm text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 p-3 rounded-lg border border-amber-100 dark:border-amber-800/50">
                            <strong>Note:</strong> {d.exceptions_or_notes}
                        </div>
                    )}
                </div>
                <div className="space-y-4">
                     <h3 className="font-bold text-slate-400 dark:text-slate-500 text-xs uppercase tracking-wider mb-2 flex items-center gap-2">
                        <SparklesIcon className="w-4 h-4" /> Examples
                    </h3>
                    {d.examples.map((ex, i) => (
                        <div key={i} className="pl-4 border-l-2 border-french-blue dark:border-blue-500">
                            <p className="text-slate-800 dark:text-slate-200 font-medium italic">"{ex.french}"</p>
                            <p className="text-slate-500 dark:text-slate-400 text-sm">{ex.english}</p>
                        </div>
                    ))}
                </div>
            </div>

            {/* Verb Conjugations */}
            {isVerb && d.tenses && (
                <div>
                    <h3 className="text-2xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6 border-b border-slate-100 dark:border-slate-800 pb-2">Conjugations</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {d.tenses.map((tense) => (
                            <div key={tense.name} className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl overflow-hidden shadow-sm">
                                <div className="bg-slate-50 dark:bg-slate-800 p-3 border-b border-slate-200 dark:border-slate-700 font-bold text-center text-slate-700 dark:text-slate-300">
                                    {tense.name}
                                </div>
                                <div className="p-4">
                                    <table className="w-full text-sm">
                                        <tbody>
                                            {tense.conjugations.map((c, idx) => (
                                                <tr key={idx} className="border-b border-slate-50 dark:border-slate-800 last:border-0">
                                                    <td className="py-2 text-slate-400 dark:text-slate-500 w-1/3 text-right pr-4 font-medium">{c.pronoun}</td>
                                                    <td className="py-2 text-slate-800 dark:text-blue-300 font-bold">{c.form}</td>
                                                </tr>
                                            ))}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Noun/Adjective Forms */}
            {!isVerb && d.forms && (
                <div>
                    <h3 className="text-2xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6 border-b border-slate-100 dark:border-slate-800 pb-2">Variations</h3>
                    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl overflow-hidden shadow-sm max-w-lg">
                        <table className="w-full">
                            <thead>
                                <tr className="bg-slate-50 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-xs uppercase tracking-wider text-left">
                                    <th className="p-4 font-medium">Form</th>
                                    <th className="p-4 font-medium">Spelling</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                                {d.forms.masculine_singular && (
                                    <tr>
                                        <td className="p-4 text-slate-500 dark:text-slate-400">Masculine Singular</td>
                                        <td className="p-4 font-bold text-slate-800 dark:text-blue-300">{d.forms.masculine_singular}</td>
                                    </tr>
                                )}
                                {d.forms.feminine_singular && (
                                    <tr>
                                        <td className="p-4 text-slate-500 dark:text-slate-400">Feminine Singular</td>
                                        <td className="p-4 font-bold text-slate-800 dark:text-blue-300">{d.forms.feminine_singular}</td>
                                    </tr>
                                )}
                                {d.forms.masculine_plural && (
                                    <tr>
                                        <td className="p-4 text-slate-500 dark:text-slate-400">Masculine Plural</td>
                                        <td className="p-4 font-bold text-slate-800 dark:text-blue-300">{d.forms.masculine_plural}</td>
                                    </tr>
                                )}
                                {d.forms.feminine_plural && (
                                    <tr>
                                        <td className="p-4 text-slate-500 dark:text-slate-400">Feminine Plural</td>
                                        <td className="p-4 font-bold text-slate-800 dark:text-blue-300">{d.forms.feminine_plural}</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { generateQuiz, generateStory, checkApiKeyConfigured } from './services/geminiService';
import { 
    saveQuizToHistory, getSavedQuizzes, deleteSavedQuiz, 
    saveStoryToHistory, getSavedStories, deleteSavedStory,
    checkSupabaseConnection 
} from './services/storageService';
import { QuizSettings, QuizData, StoryData, SavedQuiz, SavedStory } from './types';
import { QuizForm } from './components/QuizForm';
import { QuizInterface } from './components/QuizInterface';
import { StoryInterface } from './components/StoryInterface';
import { VocabularyExplorer } from './components/VocabularyExplorer';
import { QuizHistory } from './components/QuizHistory';
import { StoryHistory } from './components/StoryHistory';
import { BookOpenIcon, AcademicCapIcon, RectangleStackIcon, SunIcon, MoonIcon, ListBulletIcon } from '@heroicons/react/24/outline';

type Tab = 'quiz' | 'stories' | 'vocabulary';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('quiz');
  const [cloudStatus, setCloudStatus] = useState<'connected' | 'offline'>('offline');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // --- THEME STATE ---
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('theme') === 'dark' ||
        (!('theme' in localStorage) && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  // --- QUIZ STATE ---
  const [quizData, setQuizData] = useState<QuizData | null>(null);
  const [savedQuizzes, setSavedQuizzes] = useState<SavedQuiz[]>([]);
  const [showQuizHistory, setShowQuizHistory] = useState(false);

  // --- STORY STATE ---
  const [storyData, setStoryData] = useState<StoryData | null>(null);
  const [savedStories, setSavedStories] = useState<SavedStory[]>([]);
  const [showStoryHistory, setShowStoryHistory] = useState(false);

  // Initialize App
  useEffect(() => {
    const initApp = async () => {
        const hasKey = checkApiKeyConfigured();
        const isConnected = await checkSupabaseConnection();
        console.log(`Diagnostic: API Key ${hasKey}, DB ${isConnected}`);
        setCloudStatus(isConnected ? 'connected' : 'offline');

        try {
            const [qHistory, sHistory] = await Promise.all([
                getSavedQuizzes(),
                getSavedStories()
            ]);
            setSavedQuizzes(qHistory);
            setSavedStories(sHistory);
        } catch (e) {
            console.error("Failed to load history", e);
        }
    };
    initApp();
  }, []);

  // --- QUIZ HANDLERS ---
  const handleCreateQuiz = async (settings: QuizSettings) => {
    setLoading(true);
    setError(null);
    try {
      const response = await generateQuiz(settings);
      if (response && response.quiz) {
          setQuizData(response.quiz);
          setShowQuizHistory(false);
          try {
             const saved = await saveQuizToHistory(response.quiz);
             setSavedQuizzes(prev => [saved, ...prev]);
          } catch (e) { console.error("DB Save failed", e); }
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectQuiz = (quiz: QuizData) => {
    setQuizData(quiz);
    setShowQuizHistory(false);
  };

  const handleDeleteQuiz = async (id: string) => {
    const prev = savedQuizzes;
    setSavedQuizzes(p => p.filter(q => q.id !== id));
    try { await deleteSavedQuiz(id); } 
    catch { setSavedQuizzes(prev); }
  };

  const closeQuiz = () => {
      setQuizData(null);
  };

  // --- STORY HANDLERS ---
  const handleCreateStory = async (settings: QuizSettings) => {
    setLoading(true);
    setError(null);
    try {
      const response = await generateStory(settings);
      if (response && response.story) {
          setStoryData(response.story);
          setShowStoryHistory(false);
          try {
             const saved = await saveStoryToHistory(response.story);
             setSavedStories(prev => [saved, ...prev]);
          } catch (e) { console.error("DB Save failed", e); }
      }
    } catch (err: any) {
        setError(err.message);
    } finally {
        setLoading(false);
    }
  };

  const handleSelectStory = (story: StoryData) => {
      setStoryData(story);
      setShowStoryHistory(false);
  };

  const handleDeleteStory = async (id: string) => {
      const prev = savedStories;
      setSavedStories(p => p.filter(s => s.id !== id));
      try { await deleteSavedStory(id); }
      catch { setSavedStories(prev); }
  };

  const closeStory = () => {
      setStoryData(null);
  };

  // --- RENDER HELPERS ---

  const renderQuizTab = () => {
      if (quizData) {
          return <div className="animate-fade-in-up w-full"><QuizInterface quiz={quizData} onRestart={closeQuiz} /></div>;
      }
      if (showQuizHistory) {
          return (
            <QuizHistory 
                quizzes={savedQuizzes} 
                onSelect={handleSelectQuiz} 
                onDelete={handleDeleteQuiz}
                onBack={() => setShowQuizHistory(false)}
            />
          );
      }
      return (
          <div className="w-full flex flex-col items-center">
              <div className="text-center mb-10 max-w-2xl animate-fade-in">
                  <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6">Test Your Skills</h1>
                  <p className="text-lg text-slate-500 dark:text-slate-400 mb-6">
                      Generate adaptive quizzes tailored to your proficiency level.
                  </p>
                  {savedQuizzes.length > 0 && (
                      <button 
                        onClick={() => setShowQuizHistory(true)}
                        className="inline-flex items-center gap-2 px-5 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full text-slate-600 dark:text-slate-300 text-sm font-medium hover:text-french-blue dark:hover:text-blue-400 hover:border-french-blue dark:hover:border-blue-400 transition-colors shadow-sm"
                      >
                          <RectangleStackIcon className="w-4 h-4" />
                          View Saved Quizzes ({savedQuizzes.length})
                      </button>
                  )}
              </div>
              <div className="animate-fade-in-up w-full flex justify-center">
                  <QuizForm onSubmit={handleCreateQuiz} isLoading={loading} mode="quiz" />
              </div>
          </div>
      );
  };

  const renderStoryTab = () => {
      if (storyData) {
          return <div className="animate-fade-in-up w-full"><StoryInterface story={storyData} onBack={closeStory} /></div>;
      }
      if (showStoryHistory) {
          return (
            <StoryHistory 
                stories={savedStories}
                onSelect={handleSelectStory}
                onDelete={handleDeleteStory}
                onBack={() => setShowStoryHistory(false)}
            />
          );
      }
      return (
          <div className="w-full flex flex-col items-center">
              <div className="text-center mb-10 max-w-2xl animate-fade-in">
                  <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6">Learn through Stories</h1>
                  <p className="text-lg text-slate-500 dark:text-slate-400 mb-6">
                      Generate immersive short stories with instant hover-translation.
                  </p>
                  {savedStories.length > 0 && (
                      <button 
                        onClick={() => setShowStoryHistory(true)}
                        className="inline-flex items-center gap-2 px-5 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full text-slate-600 dark:text-slate-300 text-sm font-medium hover:text-french-blue dark:hover:text-blue-400 hover:border-french-blue dark:hover:border-blue-400 transition-colors shadow-sm"
                      >
                          <RectangleStackIcon className="w-4 h-4" />
                          View Saved Stories ({savedStories.length})
                      </button>
                  )}
              </div>
              <div className="animate-fade-in-up w-full flex justify-center">
                  <QuizForm onSubmit={handleCreateStory} isLoading={loading} mode="story" />
              </div>
          </div>
      );
  };

  return (
    <div className="min-h-screen flex flex-col font-sans bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 selection:bg-french-blue selection:text-white transition-colors duration-300">
      {/* Navbar */}
      <header className="bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 sticky top-0 z-50 transition-colors duration-300">
        <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => { setQuizData(null); setStoryData(null); setActiveTab('quiz'); }}>
             <div className="flex h-6 w-8 shadow-sm border border-slate-100 dark:border-slate-700 rounded-sm overflow-hidden">
                <div className="w-1/3 bg-french-blue h-full"></div>
                <div className="w-1/3 bg-french-white h-full"></div>
                <div className="w-1/3 bg-french-red h-full"></div>
             </div>
             <h1 className="font-serif font-bold text-xl tracking-tight text-slate-800 dark:text-white">Lumière</h1>
          </div>

          <div className="flex items-center gap-4">
            <nav className="flex gap-2 bg-slate-100 dark:bg-slate-800 p-1 rounded-full transition-colors">
                <button 
                  onClick={() => setActiveTab('quiz')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${activeTab === 'quiz' ? 'bg-white dark:bg-slate-700 shadow-sm text-french-blue dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                >
                    <AcademicCapIcon className="w-4 h-4" />
                    <span className="hidden sm:inline">Quiz</span>
                </button>
                <button 
                  onClick={() => setActiveTab('stories')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${activeTab === 'stories' ? 'bg-white dark:bg-slate-700 shadow-sm text-french-blue dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                >
                    <BookOpenIcon className="w-4 h-4" />
                    <span className="hidden sm:inline">Stories</span>
                </button>
                <button 
                  onClick={() => setActiveTab('vocabulary')}
                  className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm font-medium transition-all ${activeTab === 'vocabulary' ? 'bg-white dark:bg-slate-700 shadow-sm text-french-blue dark:text-blue-400' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
                >
                    <ListBulletIcon className="w-4 h-4" />
                    <span className="hidden sm:inline">Vocabulary</span>
                </button>
            </nav>

            {/* Theme Toggle */}
            <button 
              onClick={() => setDarkMode(!darkMode)}
              className="p-2 rounded-full text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
              title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
              {darkMode ? <SunIcon className="w-5 h-5" /> : <MoonIcon className="w-5 h-5" />}
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow container mx-auto px-4 py-12 flex flex-col items-center justify-center">

        {error && (
            <div className="mb-8 w-full max-w-lg bg-red-50 dark:bg-red-900/20 border-l-4 border-red-500 p-4 rounded shadow-sm animate-fade-in">
                <p className="text-sm text-red-700 dark:text-red-300">{error}</p>
            </div>
        )}

        {activeTab === 'quiz' && renderQuizTab()}
        {activeTab === 'stories' && renderStoryTab()}
        {activeTab === 'vocabulary' && (
            <div className="animate-fade-in-up w-full">
                <VocabularyExplorer />
            </div>
        )}

      </main>

      {/* Footer */}
      <footer className="py-8 text-center text-slate-400 dark:text-slate-500 text-sm flex flex-col items-center gap-2 transition-colors">
        <p>&copy; {new Date().getFullYear()} Lumière French Engine. Powered by Google Gemini.</p>
        <div className="flex items-center gap-2 text-xs font-medium" title={cloudStatus === 'offline' ? "Check console for .env diagnostic" : "Connected"}>
             {cloudStatus === 'connected' ? (
                 <span className="flex items-center gap-1.5 text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/30 px-2 py-1 rounded-full border border-green-100 dark:border-green-800/50">
                     <span className="relative flex h-2 w-2"><span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span><span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span></span>
                     Database Connected
                 </span>
             ) : (
                 <span className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded-full border border-slate-200 dark:border-slate-700">
                     <span className="inline-flex rounded-full h-2 w-2 bg-slate-400"></span>
                     Local Mode
                 </span>
             )}
        </div>
      </footer>

      <style>{`
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in {
            animation: fadeIn 0.4s ease-out forwards;
        }
        .animate-fade-in-up {
            animation: fadeIn 0.6s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default App;

export type CefrLevel = 'A1' | 'A2' | 'B1' | 'B2';
export type Difficulty = 'Easy' | 'Medium' | 'Hard';
export type QuestionType = 'mcq' | 'fill_blank' | 'matching';

export interface MatchingPair {
  left: string;
  right: string;
}

export interface QuestionContent {
  // MCQ
  options?: string[];

  // Fill Blank
  sentence_with_blank?: string;

  // Matching
  pairs?: MatchingPair[];

  // Common
  correct_answer?: string; 
}

