// --- AUDIO GENERATION ---

// Helper for Base64 decoding
function decodeAudioData(base64String: string): ArrayBuffer {
  const binaryString = atob(base64String);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

export const generateSpeech = async (text: string): Promise<string> => {
  if (!process.env.API_KEY) throw new Error("API Key is missing.");
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: {
        parts: [{ text: text }],
      },
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' }, // 'Kore' is usually a good standard voice
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

    if (!base64Audio) {
      throw new Error("No audio data returned");
    }

    const audioBuffer = decodeAudioData(base64Audio);
    const blob = new Blob([audioBuffer], { type: 'audio/wav' }); // Gemini TTS output is PCM, typically wrapped or we treat as raw, but Blob URL works for playback in most modern browsers if context is right. 
    // Actually, simple Base64 to Data URI is easier for HTML5 Audio:
    return `data:audio/wav;base64,${base64Audio}`;

  } catch (error) {
    console.error("Gemini TTS Error:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { StoryData } from '../types';
import { InteractiveText } from './InteractiveText';
import { ArrowLeftIcon, PlayCircleIcon, PauseCircleIcon, SpeakerWaveIcon } from '@heroicons/react/24/solid';
import { generateSpeech } from '../services/geminiService';

interface StoryInterfaceProps {
  story: StoryData;
  onBack: () => void;
}

export const StoryInterface: React.FC<StoryInterfaceProps> = ({ story, onBack }) => {
  const paragraphs = story.content.split('\n').filter(p => p.trim() !== '');

  // Audio State
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Cleanup audio object on unmount
  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current = null;
      }
    };
  }, []);

  const toggleAudio = async () => {
    // Case 1: Audio is playing, pause it
    if (isPlaying && audioRef.current) {
      audioRef.current.pause();
      setIsPlaying(false);
      return;
    }

    // Case 2: Audio is paused but loaded, play it
    if (!isPlaying && audioRef.current && audioUrl) {
      audioRef.current.play();
      setIsPlaying(true);
      return;
    }

    // Case 3: Audio not loaded, fetch it
    setIsLoadingAudio(true);
    try {
      const url = await generateSpeech(story.content);
      setAudioUrl(url);

      const audio = new Audio(url);
      audio.onended = () => setIsPlaying(false);
      audio.onpause = () => setIsPlaying(false);
      audio.onplay = () => setIsPlaying(true);

      audioRef.current = audio;
      await audio.play();
      setIsPlaying(true);
    } catch (error) {
      console.error("Failed to generate audio", error);
      alert("Could not generate audio for this story.");
    } finally {
      setIsLoadingAudio(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-visible animate-fade-in relative z-10 transition-colors">
       {/* Header */}
       <div className="bg-french-blue dark:bg-slate-800 text-white p-8 relative rounded-t-2xl transition-colors">
           <div className="flex justify-between items-start">
               <button 
                 onClick={onBack}
                 className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-colors"
               >
                  <ArrowLeftIcon className="w-5 h-5 text-white" />
               </button>

               <button
                  onClick={toggleAudio}
                  disabled={isLoadingAudio}
                  className={`flex items-center gap-2 px-4 py-2 rounded-full font-bold transition-all shadow-lg ${
                      isLoadingAudio 
                        ? 'bg-white/20 cursor-wait opacity-80' 
                        : 'bg-white text-french-blue hover:bg-blue-50'
                  }`}
               >
                  {isLoadingAudio ? (
                    <>
                       <div className="w-5 h-5 border-2 border-french-blue border-t-transparent rounded-full animate-spin"></div>
                       <span>Loading Audio...</span>
                    </>
                  ) : isPlaying ? (
                    <>
                       <PauseCircleIcon className="w-6 h-6" />
                       <span>Pause Story</span>
                    </>
                  ) : (
                    <>
                       <PlayCircleIcon className="w-6 h-6" />
                       <span>Listen to Story</span>
                    </>
                  )}
               </button>
           </div>

           <div className="text-center mt-4">
               <span className="inline-block px-3 py-1 bg-white/20 rounded-full text-xs font-bold tracking-wider mb-3 uppercase">
                  {story.cefr_level} • {story.sub_difficulty}
               </span>
               <h1 className="text-3xl md:text-4xl font-serif font-bold mb-2">{story.title}</h1>
               <p className="opacity-80 text-lg font-medium">{story.topic}</p>
           </div>
       </div>

       {/* Content */}
       <div className="p-8 md:p-12 space-y-8">
           <div className="flex items-center justify-center gap-2 text-sm text-slate-400 dark:text-slate-500 italic border-b border-slate-100 dark:border-slate-800 pb-4">
               <SpeakerWaveIcon className="w-4 h-4" />
               <span>Click a word to hear pronunciation. Hover for meaning.</span>
           </div>

           {paragraphs.map((para, idx) => (
               <p key={idx} className="text-xl md:text-2xl leading-loose text-slate-800 dark:text-slate-200 font-serif text-justify">
                   <InteractiveText text={para} glossary={story.glossary} className="inline" />
               </p>
           ))}
       </div>
    </div>
  )
}

import React, { useState } from 'react';
import { GlossaryEntry } from '../types';
import { SpeakerWaveIcon } from '@heroicons/react/24/solid';

interface InteractiveTextProps {
  text: string;
  glossary: GlossaryEntry[];
  className?: string;
}

export const InteractiveText: React.FC<InteractiveTextProps> = ({ text, glossary, className = "" }) => {
  const glossaryMap = React.useMemo(() => {
    const map = new Map<string, GlossaryEntry>();
    glossary.forEach(entry => {
      map.set(entry.word.toLowerCase(), entry);
    });
    return map;
  }, [glossary]);

  const tokens = text.split(/([ \t\n.,!?;:()'"«»-]+)/);

  return (
    <div className={`inline-block ${className}`}>
      {tokens.map((token, index) => {
        const cleanToken = token.toLowerCase().trim();
        const entry = glossaryMap.get(cleanToken);

        if (!entry || !cleanToken.match(/[a-zA-Zà-üÀ-Ü]/)) {
          // Allow clicking regular words for pronunciation too, not just glossary words
          if (cleanToken.match(/[a-zA-Zà-üÀ-Ü]{2,}/)) {
             return <ClickableWord key={index} word={token} />;
          }
          return <span key={index}>{token}</span>;
        }

        return (
          <WordTooltip key={index} word={token} entry={entry} />
        );
      })}
    </div>
  );
};

