export const getVocabularyByLevel = async (level: CefrLevel): Promise<VocabularyEntry[]> => {
  if (isSupabaseConfigured()) {
    try {
      // Check if DB has words for this level
      const { data, error } = await supabase
        .from('vocabulary')
        .select('*')
        .eq('level', level);

      if (error) throw error;

      if (data && data.length > 0) {
        return data as VocabularyEntry[];
      }
    } catch (e: any) {
      console.warn(`Vocab fetch failed in Supabase (falling back to local): ${e.message}`);
    }
  }

  return getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${level}`);
};

export const saveVocabularyList = async (level: CefrLevel, words: VocabularyEntry[]): Promise<void> => {
  // Ensure level is set on all words
  const cleanWords = words.map(w => ({ ...w, level, details: null }));

  if (isSupabaseConfigured()) {
    try {
      // Batch insert
      const { error } = await supabase.from('vocabulary').insert(cleanWords);
      if (error) throw error;
      return;
    } catch (e: any) {
      console.warn(`Supabase vocab insert failed (falling back to local): ${e.message}`);
    }
  }

  // Local Fallback
  // Overwrite local list for simplicity or append unique? Overwrite usually fine for this use case.
  saveLocalItems(`${LOCAL_VOCAB_PREFIX}${level}`, cleanWords);
};

export const saveVocabularyEntry = async (entry: VocabularyEntry): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      // Check if exists first to avoid duplicate errors if constraints are loose, or use upsert
      const { error } = await supabase.from('vocabulary').upsert(entry, { onConflict: 'word' });
      if (error) throw error;
      return;
    } catch (e: any) {
      console.warn(`Supabase vocab entry save failed: ${e.message}`);
    }
  }

  // Local Fallback
  const key = `${LOCAL_VOCAB_PREFIX}${entry.level}`;
  const list = getLocalItems<VocabularyEntry>(key);
  // Check if exists
  const idx = list.findIndex(w => w.word.toLowerCase() === entry.word.toLowerCase());
  if (idx !== -1) {
    list[idx] = entry; // Update
  } else {
    list.push(entry); // Add
  }
  saveLocalItems(key, list);
};

export const getWordDetailsFromDB = async (word: string): Promise<WordDetail | null> => {
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase
        .from('vocabulary')
        .select('details')
        .ilike('word', word) // Case insensitive
        .limit(1)
        .single();

      if (!error && data?.details) {
        return data.details as WordDetail;
      }
    } catch (e) {}
  }

  // Local Fallback: Scan all levels to find the word
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) {
    const list = getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${lvl}`);
    const found = list.find(w => w.word.toLowerCase() === word.toLowerCase());
    if (found && found.details) {
      return found.details;
    }
  }
  return null;
};

export const updateWordDetailsInDB = async (word: string, details: WordDetail): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      const { error } = await supabase
        .from('vocabulary')
        .update({ details: details })
        .eq('word', word);

      if (!error) return;
    } catch (e) {}
  }

  // Local Fallback
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) {
    const key = `${LOCAL_VOCAB_PREFIX}${lvl}`;
    const list = getLocalItems<VocabularyEntry>(key);
    const idx = list.findIndex(w => w.word === word);
    if (idx !== -1) {
      list[idx].details = details;
      saveLocalItems(key, list);
      return; // Stop after first match
    }
  }
};

import React, { useState } from 'react';
import { GlossaryEntry, CefrLevel, VocabularyEntry } from '../types';
import { SpeakerWaveIcon, ArrowPathIcon } from '@heroicons/react/24/solid';
import { generateWordDetails } from '../services/geminiService';
import { getWordDetailsFromDB, saveVocabularyEntry } from '../services/storageService';

interface InteractiveTextProps {
  text: string;
  glossary: GlossaryEntry[];
  level?: string; // Add level to support saving to DB
  className?: string;
}

export const InteractiveText: React.FC<InteractiveTextProps> = ({ text, glossary, level, className = "" }) => {
  // Create a map for fast lookups of pre-loaded glossary items
  const glossaryMap = React.useMemo(() => {
    const map = new Map<string, GlossaryEntry>();
    glossary.forEach(entry => {
      map.set(entry.word.toLowerCase(), entry);
    });
    return map;
  }, [glossary]);

  // Split text into tokens (keeping punctuation)
  const tokens = text.split(/([ \t\n.,!?;:()'"«»-]+)/);

  return (
    <div className={`inline-block ${className}`}>
      {tokens.map((token, index) => {
        const cleanToken = token.toLowerCase().trim();

        // Skip whitespace/punctuation for interaction
        if (!cleanToken.match(/[a-zA-Zà-üÀ-Ü]/)) {
           return <span key={index}>{token}</span>;
        }

        // Check if we have it in the initial glossary
        const initialEntry = glossaryMap.get(cleanToken);

        return (
          <WordToken 
            key={index} 
            word={token} 
            initialEntry={initialEntry} 
            level={level as CefrLevel || 'A1'} 
          />
        );
      })}
    </div>
  );
};

interface WordTokenProps {
  word: string;
  initialEntry?: GlossaryEntry;
  level: CefrLevel;
}

const WordToken: React.FC<WordTokenProps> = ({ word, initialEntry, level }) => {
  const [showTooltip, setShowTooltip] = useState(false);
  const [entry, setEntry] = useState<GlossaryEntry | undefined>(initialEntry);
  const [isLoading, setIsLoading] = useState(false);

  const handleClick = async (e: React.MouseEvent) => {
    e.stopPropagation();

    // 1. Audio Pronunciation (Immediate)
    const u = new SpeechSynthesisUtterance(word);
    u.lang = 'fr-FR';
    window.speechSynthesis.speak(u);

    // 2. Fetch logic if not present
    if (!entry) {
      setIsLoading(true);
      setShowTooltip(true);

      try {
        // A. Check Database First
        const dbDetail = await getWordDetailsFromDB(word);

        if (dbDetail) {
           // Map DB WordDetail to GlossaryEntry
           setEntry({
             word: dbDetail.word,
             definition: dbDetail.definition,
             phonetics: dbDetail.phonetics || "",
             example: `${dbDetail.examples[0].french} (${dbDetail.examples[0].english})`
           });
        } else {
           // B. Fallback to AI (Generate, Save, Show)
           const response = await generateWordDetails(word);
           const details = response.word_data;

           // Construct DB Entry
           const newVocabEntry: VocabularyEntry = {
              word: details.word,
              type: details.type,
              translation: details.translation,
              level: level,
              details: details
           };

           // Fire and forget save
           saveVocabularyEntry(newVocabEntry).catch(err => console.error("Auto-save failed", err));

           setEntry({
             word: details.word,
             definition: details.definition,
             phonetics: details.phonetics || "",
             example: `${details.examples[0].french} (${details.examples[0].english})`
           });
        }
      } catch (err) {
        console.error("Definition load failed", err);
      } finally {
        setIsLoading(false);
      }
    } else {
      setShowTooltip(!showTooltip);
    }
  };

  const isGlossaryWord = !!initialEntry;

  return (
    <span 
      className="relative inline-block group cursor-pointer z-20"
      onMouseEnter={() => isGlossaryWord && setShowTooltip(true)} // Hover only works for pre-loaded words for UX smoothness
      onMouseLeave={() => setShowTooltip(false)}
      onClick={handleClick}
    >
      <span className={`
        transition-colors duration-200 rounded px-0.5
        ${isGlossaryWord 
           ? 'border-b-2 border-french-blue/30 dark:border-blue-400/30 group-hover:bg-french-blue/10 dark:group-hover:bg-blue-400/10' 
           : 'hover:text-french-blue dark:hover:text-blue-400 hover:bg-slate-100 dark:hover:bg-slate-800'
        }
      `}>
        {word}
      </span>

      {/* Tooltip */}
      <div 
        className={`
          absolute z-50 bottom-full left-1/2 transform -translate-x-1/2 mb-2 w-64 
          bg-slate-800 dark:bg-slate-700 text-white text-sm rounded-lg shadow-xl p-4 
          transition-all duration-200 border dark:border-slate-600
          ${showTooltip ? 'opacity-100 translate-y-0 visible' : 'opacity-0 translate-y-2 invisible'}
        `}
        onClick={(e) => e.stopPropagation()} 
      >
        {isLoading ? (
           <div className="flex items-center justify-center gap-2 py-2">
              <ArrowPathIcon className="w-4 h-4 animate-spin text-french-blue" />
              <span className="text-xs text-slate-300">Searching Dictionary...</span>
           </div>
        ) : entry ? (
          <>
            <div className="flex justify-between items-center mb-2 border-b border-slate-600 dark:border-slate-500 pb-2">
              <div className="flex flex-col">
                  <span className="font-bold font-serif text-lg text-french-white capitalize">{entry.word}</span>
                  <span className="text-slate-400 dark:text-slate-300 font-mono text-xs">{entry.phonetics}</span>
              </div>
              <SpeakerWaveIcon className="w-4 h-4 text-slate-400" />
            </div>
            <div className="mb-2">
              <span className="text-blue-300 font-medium">Def: </span>
              {entry.definition}
            </div>
            <div className="text-xs italic text-slate-400 dark:text-slate-300 bg-slate-900/50 p-2 rounded border-l-2 border-french-blue dark:border-blue-400">
              "{entry.example}"
            </div>
          </>
        ) : (
           <div className="text-xs text-red-300">Could not load definition.</div>
        )}

        {/* Arrow */}
        <div className="absolute top-full left-1/2 -translate-x-1/2 -mt-2 border-8 border-transparent border-t-slate-800 dark:border-t-slate-700"></div>
      </div>
    </span>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { StoryData } from '../types';
import { InteractiveText } from './InteractiveText';
import { ArrowLeftIcon, PlayCircleIcon, PauseCircleIcon, SpeakerWaveIcon } from '@heroicons/react/24/solid';
import { generateSpeech, pcmToAudioBuffer } from '../services/geminiService';

interface StoryInterfaceProps {
  story: StoryData;
  onBack: () => void;
}

export const StoryInterface: React.FC<StoryInterfaceProps> = ({ story, onBack }) => {
  const paragraphs = story.content.split('\n').filter(p => p.trim() !== '');

  // Audio State
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoadingAudio, setIsLoadingAudio] = useState(false);

  // Refs for AudioContext management
  const audioContextRef = useRef<AudioContext | null>(null);
  const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
  const bufferRef = useRef<AudioBuffer | null>(null);

  // Cleanup audio object on unmount
  useEffect(() => {
    return () => {
      if (audioContextRef.current) {
        audioContextRef.current.close();
      }
    };
  }, []);

  const toggleAudio = async () => {
    // 1. PAUSE: If running, suspend context
    if (isPlaying && audioContextRef.current?.state === 'running') {
      await audioContextRef.current.suspend();
      setIsPlaying(false);
      return;
    }

    // 2. RESUME: If suspended, resume context
    if (!isPlaying && audioContextRef.current?.state === 'suspended') {
      await audioContextRef.current.resume();
      setIsPlaying(true);
      return;
    }

    // 3. START/RESTART: If no context or ended, fetch/create and play
    setIsLoadingAudio(true);
    try {
      let buffer = bufferRef.current;

      // If we haven't fetched audio yet, do it now
      if (!buffer) {
        const base64 = await generateSpeech(story.content);

        // Initialize AudioContext (24kHz is Gemini's native rate)
        if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
             audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        buffer = pcmToAudioBuffer(base64, audioContextRef.current);
        bufferRef.current = buffer;
      }

      // Re-check context (it might be closed if we re-play after finish)
      if (!audioContextRef.current || audioContextRef.current.state === 'closed') {
         audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);

      source.onended = () => {
        setIsPlaying(false);
        // We let the context stay open or we could close it. 
        // Keeping it open allows for simpler "replay" logic if we implemented a seek bar.
      };

      source.start();
      audioSourceRef.current = source;
      setIsPlaying(true);

    } catch (error) {
      console.error("Failed to generate/play audio", error);
      alert("Could not play audio. Please try again.");
    } finally {
      setIsLoadingAudio(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-visible animate-fade-in relative z-10 transition-colors">
       {/* Header */}
       <div className="bg-french-blue dark:bg-slate-800 text-white p-8 relative rounded-t-2xl transition-colors">
           <div className="flex justify-between items-start">
               <button 
                 onClick={onBack}
                 className="p-2 bg-white/10 hover:bg-white/20 rounded-full transition-colors"
               >
                  <ArrowLeftIcon className="w-5 h-5 text-white" />
               </button>

               <button
                  onClick={toggleAudio}
                  disabled={isLoadingAudio}
                  className={`flex items-center gap-2 px-4 py-2 rounded-full font-bold transition-all shadow-lg ${
                      isLoadingAudio 
                        ? 'bg-white/20 cursor-wait opacity-80' 
                        : 'bg-white text-french-blue hover:bg-blue-50'
                  }`}
               >
                  {isLoadingAudio ? (
                    <>
                       <div className="w-5 h-5 border-2 border-french-blue border-t-transparent rounded-full animate-spin"></div>
                       <span>Loading Audio...</span>
                    </>
                  ) : isPlaying ? (
                    <>
                       <PauseCircleIcon className="w-6 h-6" />
                       <span>Pause Story</span>
                    </>
                  ) : (
                    <>
                       <PlayCircleIcon className="w-6 h-6" />
                       <span>Listen to Story</span>
                    </>
                  )}
               </button>
           </div>

           <div className="text-center mt-4">
               <span className="inline-block px-3 py-1 bg-white/20 rounded-full text-xs font-bold tracking-wider mb-3 uppercase">
                  {story.cefr_level} • {story.sub_difficulty}
               </span>
               <h1 className="text-3xl md:text-4xl font-serif font-bold mb-2">{story.title}</h1>
               <p className="opacity-80 text-lg font-medium">{story.topic}</p>
           </div>
       </div>

       {/* Content */}
       <div className="p-8 md:p-12 space-y-8">
           <div className="flex items-center justify-center gap-2 text-sm text-slate-400 dark:text-slate-500 italic border-b border-slate-100 dark:border-slate-800 pb-4">
               <SpeakerWaveIcon className="w-4 h-4" />
               <span>Click a word to hear pronunciation. Hover for meaning.</span>
           </div>

           {paragraphs.map((para, idx) => (
               <p key={idx} className="text-xl md:text-2xl leading-loose text-slate-800 dark:text-slate-200 font-serif text-justify">
                   <InteractiveText text={para} glossary={story.glossary} level={story.cefr_level} className="inline" />
               </p>
           ))}
       </div>
    </div>
  )
}

import React, { useState, useEffect } from 'react';
import { Question, GlossaryEntry } from '../types';
import { InteractiveText } from './InteractiveText';
import { PencilSquareIcon } from '@heroicons/react/24/solid';

interface BaseQuestionProps {
  question: Question;
  glossary: GlossaryEntry[];
  currentAnswer: any;
  onAnswer: (answer: any) => void;
  isSubmitted: boolean;
  level?: string; // Add level prop
}

// --- MCQ Component ---
export const McqQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted, level }) => {
  const options = question.content.options || [];

  return (
    <div className="space-y-3">
      {options.map((option, idx) => {
        const isSelected = currentAnswer === option;
        const isCorrect = isSubmitted && option === question.content.correct_answer;
        const isWrong = isSubmitted && isSelected && option !== question.content.correct_answer;

        let baseClasses = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center group relative";

        if (isSubmitted) {
            if (isCorrect) baseClasses += " bg-green-50 dark:bg-green-900/20 border-green-500 dark:border-green-500 text-green-900 dark:text-green-100";
            else if (isWrong) baseClasses += " bg-red-50 dark:bg-red-900/20 border-red-500 dark:border-red-500 text-red-900 dark:text-red-100";
            else baseClasses += " border-gray-200 dark:border-slate-700 opacity-60 dark:text-slate-400";
        } else {
            if (isSelected) baseClasses += " border-french-blue dark:border-blue-500 bg-blue-50 dark:bg-blue-900/20 text-french-blue dark:text-blue-300 ring-1 ring-french-blue dark:ring-blue-500";
            else baseClasses += " border-gray-200 dark:border-slate-700 hover:bg-gray-50 dark:hover:bg-slate-800 hover:border-gray-300 dark:hover:border-slate-600 text-slate-900 dark:text-slate-200";
        }

        return (
          <button
            key={idx}
            onClick={() => !isSubmitted && onAnswer(option)}
            disabled={isSubmitted}
            className={baseClasses}
          >
            <div className={`w-5 h-5 rounded-full border mr-3 flex-shrink-0 flex items-center justify-center ${isSelected ? 'border-french-blue dark:border-blue-500' : 'border-gray-400 dark:border-slate-500'}`}>
                {isSelected && <div className="w-2.5 h-2.5 rounded-full bg-french-blue dark:bg-blue-500" />}
            </div>
            <span className="font-medium text-lg flex-grow">
                <InteractiveText text={option} glossary={glossary} level={level} />
            </span>
          </button>
        );
      })}
    </div>
  );
};

// --- Fill In Blank Component ---
export const FillBlankQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted, level }) => {
  const rawParts = (question.content.sentence_with_blank || "").split("_____");
  const parts = rawParts.length >= 2 ? rawParts : ["", ""];

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onAnswer(e.target.value);
  };

  const isCorrect = isSubmitted && 
    (currentAnswer || "").toLowerCase().trim() === (question.content.correct_answer || "").toLowerCase().trim();

  return (
    <div className="py-8 px-4 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-200 dark:border-slate-700 flex flex-col items-center transition-colors">
      <div className="text-xl md:text-2xl leading-[2.5] text-slate-800 dark:text-slate-100 font-serif text-center w-full max-w-2xl">
        <InteractiveText text={parts[0]} glossary={glossary} level={level} className="mr-1" />

        <span className="inline-block relative align-baseline mx-1 group">
            <input
                type="text"
                value={currentAnswer || ''}
                onChange={handleChange}
                disabled={isSubmitted}
                placeholder="type answer"
                autoComplete="off"
                className={`
                    min-w-[140px] px-2 py-0.5 border-b-2 text-center bg-transparent 
                    focus:outline-none transition-all font-bold placeholder:text-slate-300 dark:placeholder:text-slate-600 placeholder:font-sans placeholder:text-base
                    ${isSubmitted 
                        ? (isCorrect ? 'border-green-500 text-green-700 dark:text-green-400 bg-green-50/50 dark:bg-green-900/30' : 'border-red-500 text-red-700 dark:text-red-400 bg-red-50/50 dark:bg-red-900/30') 
                        : 'border-slate-300 dark:border-slate-600 focus:border-french-blue dark:focus:border-blue-500 text-french-blue dark:text-blue-300 focus:bg-white/50 dark:focus:bg-slate-700/50'
                    }
                `}
            />
            {!isSubmitted && !currentAnswer && (
                 <PencilSquareIcon className="w-4 h-4 text-slate-300 dark:text-slate-500 absolute -top-4 right-0 opacity-0 group-hover:opacity-100 transition-opacity" />
            )}
        </span>

        <InteractiveText text={parts[1] || ""} glossary={glossary} level={level} className="ml-1" />
      </div>

      {/* Answer Feedback */}
      {isSubmitted && !isCorrect && (
          <div className="mt-6 flex flex-col items-center animate-fade-in">
              <span className="text-xs uppercase tracking-wider font-bold text-slate-400 dark:text-slate-500 mb-1">Correct Answer</span>
              <div className="px-4 py-2 bg-green-100 dark:bg-green-900/40 text-green-800 dark:text-green-200 rounded-lg font-bold shadow-sm border border-green-200 dark:border-green-800">
                 {question.content.correct_answer || <span className="text-red-500 italic text-sm">Error: Answer key missing</span>}
              </div>
          </div>
      )}
    </div>
  );
};

// --- Matching Component ---
export const MatchingQuestion: React.FC<BaseQuestionProps> = ({ question, glossary, currentAnswer, onAnswer, isSubmitted, level }) => {
  const answerMap = (currentAnswer as Record<string, string>) || {};

  const [shuffledRight, setShuffledRight] = useState<string[]>([]);
  const [selectedLeft, setSelectedLeft] = useState<string | null>(null);

  useEffect(() => {
    if (question.content.pairs) {
      const rights = question.content.pairs.map(p => p.right);
      setShuffledRight([...rights].sort(() => Math.random() - 0.5));
    }
  }, [question.id]);

  const pairs = question.content.pairs || [];

  const handleLeftClick = (left: string) => {
    if (isSubmitted) return;
    if (selectedLeft === left) {
        setSelectedLeft(null);
        return;
    }
    setSelectedLeft(left);
  };

  const handleRightClick = (right: string) => {
    if (isSubmitted || !selectedLeft) return;
    const newAnswers = { ...answerMap, [selectedLeft]: right };
    onAnswer(newAnswers);
    setSelectedLeft(null);
  };

  const isPairCorrect = (left: string, right: string) => {
      const correctRight = pairs.find(p => p.left === left)?.right;
      return correctRight === right;
  };

  return (
    <div className="grid grid-cols-2 gap-8 relative">
      {/* Left Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-2">Term</h4>
        {pairs.map((pair, idx) => {
          const isSelected = selectedLeft === pair.left;
          const matchedRight = answerMap[pair.left];
          const isCompleted = !!matchedRight;

          let borderColor = "border-slate-200 dark:border-slate-700";
          let bgColor = "bg-white dark:bg-slate-800";
          let textColor = "text-slate-900 dark:text-slate-200";

          if (isSubmitted) {
             if (isCompleted && isPairCorrect(pair.left, matchedRight)) {
                 borderColor = "border-green-400 dark:border-green-600";
                 bgColor = "bg-green-50 dark:bg-green-900/20";
                 textColor = "text-green-900 dark:text-green-200";
             } else if (isCompleted) {
                 borderColor = "border-red-400 dark:border-red-600";
                 bgColor = "bg-red-50 dark:bg-red-900/20";
                 textColor = "text-red-900 dark:text-red-200";
             }
          } else {
             if (isSelected) {
                 borderColor = "border-french-blue dark:border-blue-500";
                 bgColor = "bg-blue-50 dark:bg-blue-900/20";
                 textColor = "text-french-blue dark:text-blue-300";
             } else if (isCompleted) {
                 borderColor = "border-slate-300 dark:border-slate-600";
                 bgColor = "bg-slate-50 dark:bg-slate-700/50";
                 textColor = "text-slate-500 dark:text-slate-400";
             }
          }

          return (
            <button
              key={`left-${idx}`}
              onClick={() => handleLeftClick(pair.left)}
              disabled={isSubmitted}
              className={`w-full p-3 text-left border rounded-md text-sm font-medium transition-all ${borderColor} ${bgColor} ${textColor} relative`}
            >
              <InteractiveText text={pair.left} glossary={glossary} level={level} />
              {matchedRight && (
                  <span className="absolute right-2 top-1/2 -translate-y-1/2 w-2 h-2 rounded-full bg-slate-300 dark:bg-slate-500"></span>
              )}
            </button>
          );
        })}
      </div>

      {/* Right Column */}
      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider mb-2">Match</h4>
        {shuffledRight.map((rightItem, idx) => {
           const isUsed = Object.values(answerMap).includes(rightItem);

           let borderColor = "border-slate-200 dark:border-slate-700";
           let textColor = "text-slate-900 dark:text-slate-200";
           let bgColor = "bg-white dark:bg-slate-800";

           if (isSubmitted) {
                const leftKey = Object.keys(answerMap).find(key => answerMap[key] === rightItem);
                if (leftKey) {
                    if (isPairCorrect(leftKey, rightItem)) {
                        borderColor = "border-green-400 bg-green-50 dark:bg-green-900/20 dark:border-green-600";
                        textColor = "text-green-900 dark:text-green-200";
                    } else {
                        borderColor = "border-red-400 bg-red-50 dark:bg-red-900/20 dark:border-red-600";
                        textColor = "text-red-900 dark:text-red-200";
                    }
                }
           } else {
               if (isUsed) {
                   borderColor = "border-slate-300 dark:border-slate-600 bg-slate-100 dark:bg-slate-700/50";
                   textColor = "text-slate-400 dark:text-slate-500";
               } else {
                   // Default hover only when not used/submitted
                   borderColor += " hover:border-slate-300 dark:hover:border-slate-500";
               }
           }

          return (
            <button
              key={`right-${idx}`}
              onClick={() => handleRightClick(rightItem)}
              disabled={isSubmitted || (isUsed && !isSubmitted)}
              className={`w-full p-3 text-left border rounded-md text-sm transition-all ${borderColor} ${bgColor} ${textColor}`}
            >
              <InteractiveText text={rightItem} glossary={glossary} level={level} />
            </button>
          );
        })}
      </div>

      {!isSubmitted && (
          <div className="col-span-2 text-center text-xs text-slate-400 dark:text-slate-500 mt-2">
            Select an item on the left, then click the matching item on the right.
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { QuizData, UserAnswerValue, Question } from '../types';
import { McqQuestion, FillBlankQuestion, MatchingQuestion } from './QuestionRenderers';
import { InteractiveText } from './InteractiveText';
import { CheckCircleIcon, XCircleIcon, ArrowRightIcon, ArrowPathIcon, CheckIcon, XMarkIcon } from '@heroicons/react/24/solid';

interface QuizInterfaceProps {
  quiz: QuizData;
  onRestart: () => void;
}

export const QuizInterface: React.FC<QuizInterfaceProps> = ({ quiz, onRestart }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<number, UserAnswerValue>>({});
  const [checkedState, setCheckedState] = useState<Record<number, boolean>>({});
  const [isFinished, setIsFinished] = useState(false);
  const [score, setScore] = useState(0);

  const currentQuestion = quiz.questions[currentIndex];
  const glossary = quiz.glossary || [];
  const isChecked = !!checkedState[currentQuestion.id];

  const handleAnswer = (val: UserAnswerValue) => {
    if (isChecked) return; // Prevent changing answer after checking
    setAnswers(prev => ({ ...prev, [currentQuestion.id]: val }));
  };

  const checkCorrectness = (q: Question, ans: UserAnswerValue) => {
      if (!ans) return false;
      if (q.type === 'mcq') {
        return ans === q.content.correct_answer;
      } else if (q.type === 'fill_blank') {
        return typeof ans === 'string' && ans.toLowerCase().trim() === (q.content.correct_answer || '').toLowerCase().trim();
      } else if (q.type === 'matching') {
        const userPairs = ans as Record<string, string>;
        const correctPairs = q.content.pairs || [];
        // Must match all pairs
        if (Object.keys(userPairs).length !== correctPairs.length) return false;
        return correctPairs.every(p => userPairs[p.left] === p.right);
      }
      return false;
  };

  const handleCheck = () => {
    const ans = answers[currentQuestion.id];
    const isCorrect = checkCorrectness(currentQuestion, ans);

    if (isCorrect) {
        setScore(prev => prev + 1);
    }
    setCheckedState(prev => ({ ...prev, [currentQuestion.id]: true }));
  };

  const handleNext = () => {
    if (currentIndex < quiz.questions.length - 1) {
        setCurrentIndex(prev => prev + 1);
    } else {
        setIsFinished(true);
    }
  };

  const isCurrentCorrect = isChecked && checkCorrectness(currentQuestion, answers[currentQuestion.id]);

  const canCheck = () => {
      const ans = answers[currentQuestion.id];
      if (!ans) return false;
      if (currentQuestion.type === 'matching') {
           const pairs = currentQuestion.content.pairs || [];
           const userPairs = ans as Record<string, string>;
           return Object.keys(userPairs).length === pairs.length;
      }
      if (typeof ans === 'string' && ans.trim() === '') return false;
      return true;
  };

  const isLastQuestion = currentIndex === quiz.questions.length - 1;
  const progress = ((currentIndex + (isChecked ? 1 : 0)) / quiz.questions.length) * 100;

  // -- Results View (Final Summary) --
  if (isFinished) {
    const percentage = Math.round((score / quiz.questions.length) * 100);
    let feedback = "Bon effort!";
    if (percentage === 100) feedback = "Excellent! Parfait!";
    else if (percentage >= 80) feedback = "Très bien!";
    else if (percentage >= 60) feedback = "Bien joué.";

    return (
      <div className="max-w-2xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-hidden animate-fade-in transition-colors">
        <div className="bg-french-blue dark:bg-slate-800 text-white p-8 text-center">
            <h2 className="text-3xl font-serif font-bold mb-2">{feedback}</h2>
            <p className="opacity-90">You scored {score} out of {quiz.questions.length}</p>
        </div>

        <div className="p-8 space-y-4">
            <h3 className="font-bold text-slate-800 dark:text-slate-100 text-lg mb-4">Summary</h3>
            {quiz.questions.map((q, idx) => {
                const ans = answers[q.id];
                const correct = checkCorrectness(q, ans);

                return (
                    <div key={q.id} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-lg border border-slate-100 dark:border-slate-700">
                        <div className="flex items-center gap-3">
                             {correct ? (
                                 <CheckCircleIcon className="w-5 h-5 text-green-500" />
                             ) : (
                                 <XCircleIcon className="w-5 h-5 text-red-500" />
                             )}
                             <span className="text-sm font-medium text-slate-700 dark:text-slate-300">Question {idx+1}</span>
                        </div>
                        <div className="text-sm text-slate-500 dark:text-slate-400">
                            {correct ? "Correct" : "Incorrect"}
                        </div>
                    </div>
                );
            })}
        </div>

        <div className="p-6 bg-slate-50 dark:bg-slate-950 border-t border-slate-100 dark:border-slate-800 flex justify-center">
            <button 
                onClick={onRestart}
                className="flex items-center gap-2 px-8 py-3 bg-french-dark dark:bg-slate-700 text-white rounded-full font-medium hover:bg-black dark:hover:bg-slate-600 transition-colors shadow-lg hover:shadow-xl"
            >
                <ArrowPathIcon className="w-5 h-5" />
                Generate New Quiz
            </button>
        </div>
      </div>
    );
  }

  // -- Active Quiz View --
  return (
    <div className="max-w-2xl mx-auto">
      {/* Header Info */}
      <div className="mb-8 flex items-start justify-between">
        <div>
             <h1 className="font-serif italic text-french-blue dark:text-blue-400 font-bold text-xl">{quiz.topic}</h1>
             <div className="mt-1">
                <span className="inline-block bg-slate-100 dark:bg-slate-800 text-xs font-bold px-2 py-0.5 rounded text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-slate-700">
                    {quiz.cefr_level} • {quiz.sub_difficulty}
                </span>
             </div>
        </div>

        <button 
            onClick={onRestart}
            className="group flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-slate-400 hover:text-red-600 dark:text-slate-500 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/10 transition-all text-sm font-medium"
            title="End Quiz and Return to Menu"
        >
            <span>End</span>
            <XMarkIcon className="w-4 h-4" />
        </button>
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-gray-200 dark:bg-slate-700 rounded-full h-2 mb-8">
        <div 
            className="bg-french-blue dark:bg-blue-500 h-2 rounded-full transition-all duration-500 ease-out" 
            style={{ width: `${progress}%` }}
        ></div>
      </div>

      {/* Card */}
      <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-xl p-8 min-h-[400px] flex flex-col relative overflow-visible z-10 transition-all">

        {/* Question Header */}
        <div className="mb-6">
            <div className="flex justify-between items-start">
                <span className="text-xs font-bold tracking-widest text-slate-400 dark:text-slate-500 uppercase">Question {currentIndex + 1} of {quiz.questions.length}</span>
                {isChecked && (
                    <span className={`flex items-center gap-1 text-sm font-bold ${isCurrentCorrect ? 'text-green-600 dark:text-green-400' : 'text-red-500 dark:text-red-400'}`}>
                        {isCurrentCorrect ? (
                            <>
                                <CheckCircleIcon className="w-5 h-5" /> Correct
                            </>
                        ) : (
                            <>
                                <XCircleIcon className="w-5 h-5" /> Incorrect
                            </>
                        )}
                    </span>
                )}
            </div>
            <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mt-2 font-serif leading-tight">
                <InteractiveText text={currentQuestion.question_text} glossary={glossary} level={quiz.cefr_level} />
            </h2>
        </div>

        {/* Question Content */}
        <div className="flex-grow">
            {currentQuestion.type === 'mcq' && (
                <McqQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={isChecked}
                    level={quiz.cefr_level}
                />
            )}
            {currentQuestion.type === 'fill_blank' && (
                <FillBlankQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={isChecked}
                    level={quiz.cefr_level} 
                />
            )}
            {currentQuestion.type === 'matching' && (
                <MatchingQuestion 
                    question={currentQuestion} 
                    glossary={glossary}
                    currentAnswer={answers[currentQuestion.id]} 
                    onAnswer={handleAnswer} 
                    isSubmitted={isChecked}
                    level={quiz.cefr_level} 
                />
            )}
        </div>

        {/* Explanation Block (Immediate Feedback) */}
        {isChecked && (
             <div className={`mt-8 p-5 rounded-xl border animate-fade-in ${isCurrentCorrect ? 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800/50' : 'bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800/50'}`}>
                 <h4 className={`text-sm font-bold uppercase tracking-wide mb-2 ${isCurrentCorrect ? 'text-green-800 dark:text-green-300' : 'text-red-800 dark:text-red-300'}`}>
                    Explanation
                 </h4>
                 <p className="text-slate-700 dark:text-slate-300 leading-relaxed">
                    {currentQuestion.explanation}
                 </p>
             </div>
        )}

        {/* Navigation */}
        <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-800 flex justify-between items-center">
             <button 
                onClick={() => setCurrentIndex(prev => Math.max(0, prev - 1))}
                disabled={currentIndex === 0}
                className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 font-medium disabled:opacity-30 px-4 py-2"
             >
                 Back
             </button>

             {!isChecked ? (
                 <button
                    onClick={handleCheck}
                    disabled={!canCheck()}
                    className="flex items-center gap-2 bg-french-dark dark:bg-slate-700 text-white px-8 py-3 rounded-full font-bold shadow-lg hover:bg-black dark:hover:bg-slate-600 transition-all disabled:opacity-50 disabled:shadow-none"
                 >
                     Check Answer
                     <CheckIcon className="w-4 h-4" />
                 </button>
             ) : (
                 <button
                    onClick={handleNext}
                    className="flex items-center gap-2 bg-french-blue dark:bg-blue-600 text-white px-8 py-3 rounded-full font-bold shadow-lg hover:bg-blue-700 dark:hover:bg-blue-500 hover:shadow-xl transition-all"
                 >
                     {isLastQuestion ? "Finish Quiz" : "Next Question"}
                     <ArrowRightIcon className="w-4 h-4" />
                 </button>
             )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { generateVocabularyList, generateWordDetails } from '../services/geminiService';
import { getVocabularyByLevel, saveVocabularyList, getWordDetailsFromDB, updateWordDetailsInDB } from '../services/storageService';
import { VocabularyEntry, WordDetail, CefrLevel } from '../types';
import { ArrowLeftIcon, BookOpenIcon, SparklesIcon, CircleStackIcon, SpeakerWaveIcon } from '@heroicons/react/24/solid';
import { InteractiveText } from './InteractiveText';

const LEVELS: { id: CefrLevel; label: string; desc: string }[] = [
  { id: 'A1', label: 'A1 Beginner', desc: 'Basic survival vocabulary' },
  { id: 'A2', label: 'A2 Elementary', desc: 'Routine & daily tasks' },
  { id: 'B1', label: 'B1 Intermediate', desc: 'Work, school, leisure' },
  { id: 'B2', label: 'B2 Upper Inter.', desc: 'Technical & abstract' },
];

export const VocabularyExplorer: React.FC = () => {
  const [view, setView] = useState<'levels' | 'list' | 'detail'>('levels');
  const [selectedLevel, setSelectedLevel] = useState<CefrLevel | null>(null);
  const [wordList, setWordList] = useState<VocabularyEntry[]>([]);
  const [selectedWord, setSelectedWord] = useState<WordDetail | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingText, setLoadingText] = useState('');

  const playAudio = (text: string) => {
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'fr-FR';
    window.speechSynthesis.speak(u);
  };

  const handleLevelSelect = async (lvl: CefrLevel) => {
    setSelectedLevel(lvl);
    setLoading(true);
    setLoadingText('Checking database...');

    try {
      // 1. Try to fetch from DB
      let words = await getVocabularyByLevel(lvl);

      // 2. If empty, Seed DB using AI
      if (words.length === 0) {
        setLoadingText(`Seeding database for ${lvl}...`);
        const response = await generateVocabularyList(lvl);

        // Convert response to proper DB entries
        const vocabEntries: VocabularyEntry[] = response.words.map(w => ({
            ...w,
            level: lvl,
            details: null
        }));

        await saveVocabularyList(lvl, vocabEntries);
        words = vocabEntries;
      }

      setWordList(words);
      setView('list');
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleWordSelect = async (wordEntry: VocabularyEntry) => {
    setLoading(true);
    setLoadingText('Loading word details...');
    try {
      // 1. Check if we already have the details in memory/list
      if (wordEntry.details) {
          setSelectedWord(wordEntry.details);
          setView('detail');
          setLoading(false);
          return;
      }

      // 2. Check DB explicitly (in case list was stale or minimal fetch)
      const dbDetails = await getWordDetailsFromDB(wordEntry.word);
      if (dbDetails) {
          setSelectedWord(dbDetails);
          setView('detail');
          setLoading(false);
          return;
      }

      // 3. Generate via AI and Save to DB
      setLoadingText('Analyzing grammar...');
      const response = await generateWordDetails(wordEntry.word);
      const newDetails = response.word_data;

      await updateWordDetailsInDB(wordEntry.word, newDetails);

      // Update local state list to prevent re-fetch
      setWordList(prev => prev.map(w => w.word === wordEntry.word ? { ...w, details: newDetails } : w));

      setSelectedWord(newDetails);
      setView('detail');

    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const goBack = () => {
    if (view === 'detail') setView('list');
    else if (view === 'list') setView('levels');
  };

  if (loading) {
    return (
      <div className="w-full max-w-4xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl p-12 flex flex-col items-center justify-center min-h-[500px] transition-colors">
         <div className="relative mb-8">
            <div className="w-20 h-20 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
            <div className="w-20 h-20 border-4 border-french-blue dark:border-blue-500 rounded-full border-t-transparent animate-spin absolute top-0 left-0"></div>
         </div>
         <h3 className="text-2xl font-serif font-bold text-slate-800 dark:text-slate-100 animate-pulse">
           {loadingText}
         </h3>
         <p className="text-slate-500 dark:text-slate-400 mt-2">
           Consulting the French language engine
         </p>
      </div>
    );
  }

  // --- VIEW 1: LEVELS ---
  if (view === 'levels') {
    return (
      <div className="w-full max-w-4xl mx-auto">
        <div className="text-center mb-10 animate-fade-in">
            <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6">Vocabulary Explorer</h1>
            <p className="text-lg text-slate-500 dark:text-slate-400">
                Explore words by proficiency level. Data is seeded once and cached.
            </p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fade-in-up">
            {LEVELS.map((lvl) => (
                <button
                    key={lvl.id}
                    onClick={() => handleLevelSelect(lvl.id)}
                    className="group relative p-8 border-2 border-slate-100 dark:border-slate-800 rounded-2xl hover:bg-white dark:hover:bg-slate-800 hover:border-french-blue dark:hover:border-blue-500 transition-all text-left flex flex-col justify-center bg-white dark:bg-slate-900 shadow-sm hover:shadow-xl"
                >
                    <span className="text-5xl font-black text-slate-100 dark:text-slate-700 group-hover:text-blue-50 dark:group-hover:text-slate-600 absolute right-6 top-6 transition-colors">{lvl.id}</span>
                    <h3 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mb-2 group-hover:text-french-blue dark:group-hover:text-blue-400 transition-colors relative z-10">{lvl.label}</h3>
                    <p className="text-slate-500 dark:text-slate-400 leading-relaxed group-hover:text-slate-600 dark:group-hover:text-slate-300 relative z-10">{lvl.desc}</p>
                </button>
            ))}
        </div>
      </div>
    );
  }

  // --- VIEW 2: WORD LIST ---
  if (view === 'list') {
    return (
      <div className="w-full max-w-4xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl min-h-[600px] flex flex-col animate-fade-in transition-colors">
         <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-french-blue dark:bg-slate-800 rounded-t-2xl text-white">
            <div className="flex items-center gap-4">
                <button onClick={goBack} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                    <ArrowLeftIcon className="w-5 h-5" />
                </button>
                <div>
                    <span className="text-xs font-bold uppercase tracking-wider opacity-80">Level {selectedLevel}</span>
                    <h2 className="text-2xl font-serif font-bold">Word Bank</h2>
                </div>
            </div>
            <div className="flex items-center gap-2 text-xs bg-black/20 px-3 py-1 rounded-full">
                <CircleStackIcon className="w-4 h-4" />
                <span>{wordList.length} words loaded</span>
            </div>
         </div>

         <div className="p-8 grid grid-cols-2 md:grid-cols-4 gap-4 overflow-y-auto">
            {wordList.map((item, idx) => (
                <button 
                  key={idx}
                  onClick={() => handleWordSelect(item)}
                  className="relative p-4 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 hover:border-french-blue dark:hover:border-blue-500 hover:bg-blue-50 dark:hover:bg-blue-900/20 text-left transition-all group"
                >
                     <button 
                        onClick={(e) => { e.stopPropagation(); playAudio(item.word); }}
                        className="absolute top-2 right-2 p-1.5 text-slate-300 dark:text-slate-600 hover:text-french-blue dark:hover:text-blue-400 hover:bg-white dark:hover:bg-slate-700 rounded-full transition-colors z-10"
                        title="Pronounce"
                    >
                        <SpeakerWaveIcon className="w-4 h-4" />
                    </button>

                    <div className="text-xs font-bold text-slate-400 dark:text-slate-500 uppercase mb-1 flex justify-between">
                        {item.type}
                        {item.details && <SparklesIcon className="w-3 h-3 text-yellow-500 mr-6" title="Detailed view cached" />}
                    </div>
                    <div className="font-bold text-slate-800 dark:text-slate-100 text-lg mb-1 capitalize truncate pr-4" title={item.word}>{item.word}</div>
                    <div className="text-sm text-slate-500 dark:text-slate-400 italic truncate" title={item.translation}>{item.translation}</div>
                </button>
            ))}
         </div>
      </div>
    );
  }

  // --- VIEW 3: DETAIL ---
  const d = selectedWord!;
  const isVerb = d.type === 'verb';

  return (
    <div className="w-full max-w-4xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-hidden animate-fade-in transition-colors">
        {/* Header */}
        <div className="bg-french-dark dark:bg-slate-950 text-white p-8 relative">
            <button onClick={goBack} className="absolute top-8 left-8 p-2 text-slate-400 hover:text-white transition-colors">
                <ArrowLeftIcon className="w-6 h-6" />
            </button>
            <div className="text-center mt-4 flex flex-col items-center">
                <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold tracking-wider mb-3 uppercase 
                    ${isVerb ? 'bg-red-500/20 text-red-300 border border-red-500/30' : 'bg-blue-500/20 text-blue-300 border border-blue-500/30'}`}>
                    {d.type}
                </span>
                <div className="flex items-center gap-4 mb-2">
                    <h1 className="text-5xl font-serif font-bold capitalize">{d.word}</h1>
                    <button 
                        onClick={() => playAudio(d.word)}
                        className="p-3 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors"
                        title="Pronounce"
                    >
                        <SpeakerWaveIcon className="w-8 h-8" />
                    </button>
                </div>
                <p className="text-xl opacity-90 font-light">{d.translation}</p>
            </div>
            {isVerb && (
                <div className="flex justify-center gap-4 mt-6 text-sm text-slate-400">
                    {d.verb_group && <span>Group: <span className="text-white">{d.verb_group}</span></span>}
                    {d.auxiliary_verb && <span>Aux: <span className="text-white">{d.auxiliary_verb}</span></span>}
                </div>
            )}
        </div>

        <div className="p-8">
            {/* Definition & Examples */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-xl border border-slate-100 dark:border-slate-800">
                    <h3 className="font-bold text-slate-400 dark:text-slate-500 text-xs uppercase tracking-wider mb-4 flex items-center gap-2">
                        <BookOpenIcon className="w-4 h-4" /> Definition
                    </h3>
                    <p className="text-lg text-slate-800 dark:text-slate-200 leading-relaxed mb-4">{d.definition}</p>
                    {d.exceptions_or_notes && (
                        <div className="text-sm text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 p-3 rounded-lg border border-amber-100 dark:border-amber-800/50">
                            <strong>Note:</strong> {d.exceptions_or_notes}
                        </div>
