import { supabase, isSupabaseConfigured } from './supabaseClient';
import { QuizData, StoryData, SavedQuiz, SavedStory, VocabularyEntry, CefrLevel, WordDetail, UserProgress } from '../types';

const LOCAL_QUIZ_KEY = 'lumiere_local_quizzes';
const LOCAL_STORY_KEY = 'lumiere_local_stories';
const LOCAL_VOCAB_PREFIX = 'lumiere_vocab_'; 
const LOCAL_PROGRESS_KEY = 'lumiere_progress';

const getUserId = () => {
  const KEY = 'lumiere_device_id';
  let id = localStorage.getItem(KEY);
  if (!id) {
    id = crypto.randomUUID();
    localStorage.setItem(KEY, id);
  }
  return id;
};

const getLocalItems = <T>(key: string): T[] => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : [];
    } catch {
        return [];
    }
};

const saveLocalItems = <T>(key: string, items: T[]) => {
    localStorage.setItem(key, JSON.stringify(items));
};

export const checkSupabaseConnection = async (): Promise<boolean> => {
  if (!isSupabaseConfigured()) return false;
  try {
    const { error } = await supabase.from('quizzes').select('id', { count: 'exact', head: true });
    return !error;
  } catch (e) {
    return false;
  }
};

// --- QUIZZES ---
export const saveQuizToHistory = async (quiz: QuizData): Promise<SavedQuiz> => {
  const userId = getUserId();
  const timestamp = Date.now();
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('quizzes').insert([{ user_id: userId, data: quiz }]).select().single();
        if (!error) return { id: data.id, created_at: new Date(data.created_at).getTime(), data: data.data };
    } catch (err) {}
  }
  const newSavedQuiz: SavedQuiz = { id: crypto.randomUUID(), created_at: timestamp, data: quiz };
  const current = getLocalItems<SavedQuiz>(LOCAL_QUIZ_KEY);
  saveLocalItems(LOCAL_QUIZ_KEY, [newSavedQuiz, ...current]);
  return newSavedQuiz;
};

export const getSavedQuizzes = async (): Promise<SavedQuiz[]> => {
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('quizzes').select('*').order('created_at', { ascending: false });
        if (!error) return data.map((row: any) => ({ id: row.id, created_at: new Date(row.created_at).getTime(), data: row.data }));
    } catch (err) {}
  }
  return getLocalItems<SavedQuiz>(LOCAL_QUIZ_KEY);
};

export const deleteSavedQuiz = async (id: string): Promise<void> => {
  if (isSupabaseConfigured()) {
    try { await supabase.from('quizzes').delete().eq('id', id); } catch (err) {}
  }
  const current = getLocalItems<SavedQuiz>(LOCAL_QUIZ_KEY);
  saveLocalItems(LOCAL_QUIZ_KEY, current.filter(q => q.id !== id));
};

// --- STORIES ---
export const saveStoryToHistory = async (story: StoryData): Promise<SavedStory> => {
  const userId = getUserId();
  const timestamp = Date.now();
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('stories').insert([{ user_id: userId, data: story }]).select().single();
        if (!error) return { id: data.id, created_at: new Date(data.created_at).getTime(), data: data.data };
    } catch (err) {}
  }
  const newSavedStory: SavedStory = { id: crypto.randomUUID(), created_at: timestamp, data: story };
  const current = getLocalItems<SavedStory>(LOCAL_STORY_KEY);
  saveLocalItems(LOCAL_STORY_KEY, [newSavedStory, ...current]);
  return newSavedStory;
};

export const getSavedStories = async (): Promise<SavedStory[]> => {
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('stories').select('*').order('created_at', { ascending: false });
        if (!error) return data.map((row: any) => ({ id: row.id, created_at: new Date(row.created_at).getTime(), data: row.data }));
    } catch (err) {}
  }
  return getLocalItems<SavedStory>(LOCAL_STORY_KEY);
};

export const deleteSavedStory = async (id: string): Promise<void> => {
  if (isSupabaseConfigured()) {
    try { await supabase.from('stories').delete().eq('id', id); } catch (err) {}
  }
  const current = getLocalItems<SavedStory>(LOCAL_STORY_KEY);
  saveLocalItems(LOCAL_STORY_KEY, current.filter(s => s.id !== id));
};

// --- VOCABULARY ---

export const clearVocabularyByLevel = async (level: CefrLevel): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').delete().eq('level', level);
    } catch (e) {}
  }
  localStorage.removeItem(`${LOCAL_VOCAB_PREFIX}${level}`);
};

export const getVocabularyByLevel = async (level: CefrLevel): Promise<VocabularyEntry[]> => {
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.from('vocabulary').select('*').eq('level', level);
      if (!error && data && data.length > 0) return data as VocabularyEntry[];
    } catch (e: any) {}
  }
  return getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${level}`);
};

export const saveVocabularyList = async (level: CefrLevel, words: VocabularyEntry[]): Promise<void> => {
  const cleanWords = words.map(w => ({ ...w, level, details: null }));
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').insert(cleanWords);
      return;
    } catch (e: any) {}
  }
  saveLocalItems(`${LOCAL_VOCAB_PREFIX}${level}`, cleanWords);
};

export const saveVocabularyEntry = async (entry: VocabularyEntry): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').upsert(entry, { onConflict: 'word' });
      return;
    } catch (e: any) {}
  }
  const key = `${LOCAL_VOCAB_PREFIX}${entry.level}`;
  const list = getLocalItems<VocabularyEntry>(key);
  const idx = list.findIndex(w => w.word.toLowerCase() === entry.word.toLowerCase());
  if (idx !== -1) list[idx] = entry; else list.push(entry);
  saveLocalItems(key, list);
};

export const getWordDetailsFromDB = async (word: string): Promise<WordDetail | null> => {
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.from('vocabulary').select('details').ilike('word', word).limit(1).single();
      if (!error && data?.details) return data.details as WordDetail;
    } catch (e) {}
  }
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) {
    const list = getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${lvl}`);
    const found = list.find(w => w.word.toLowerCase() === word.toLowerCase());
    if (found && found.details) return found.details;
  }
  return null;
};

export const updateWordDetailsInDB = async (word: string, details: WordDetail): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').update({ details: details }).eq('word', word);
      return;
    } catch (e) {}
  }
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) {
    const key = `${LOCAL_VOCAB_PREFIX}${lvl}`;
    const list = getLocalItems<VocabularyEntry>(key);
    const idx = list.findIndex(w => w.word === word);
    if (idx !== -1) {
      list[idx].details = details;
      saveLocalItems(key, list);
      return;
    }
  }
};

export const searchVocabulary = async (query: string): Promise<VocabularyEntry[]> => {
  if (!query || query.length < 2) return [];
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.from('vocabulary').select('*').ilike('word', `${query}%`).limit(8);
      if (!error && data) return data as VocabularyEntry[];
    } catch (e) {}
  }
  const allWords: VocabularyEntry[] = [];
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) allWords.push(...getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${lvl}`));
  return allWords.filter(w => w.word.toLowerCase().startsWith(query.toLowerCase())).slice(0, 8);
};

// --- PATH / PROGRESS ---

export const getPathProgress = async (level: string): Promise<UserProgress[]> => {
  const userId = getUserId();
  if (isSupabaseConfigured()) {
    try {
       const { data, error } = await supabase.from('user_progress').select('*').eq('user_id', userId).eq('level_id', level);
       if (!error && data) return data as UserProgress[];
    } catch(e) {}
  }
  // Local fallback
  const allProgress = getLocalItems<UserProgress>(LOCAL_PROGRESS_KEY);
  return allProgress.filter(p => p.level_id === level);
};

export const markCheckpointComplete = async (level: string, title: string, score: number): Promise<void> => {
  const userId = getUserId();
  const entry: UserProgress = {
      level_id: level,
      checkpoint_title: title,
      completed: true,
      score: score
  };

  if (isSupabaseConfigured()) {
    try {
       await supabase.from('user_progress').upsert({
         user_id: userId,
         ...entry
       }, { onConflict: 'user_id, level_id, checkpoint_title' });
       return;
    } catch(e) {}
  }

  // Local Fallback
  const allProgress = getLocalItems<UserProgress>(LOCAL_PROGRESS_KEY);
  const idx = allProgress.findIndex(p => p.level_id === level && p.checkpoint_title === title);
  if (idx > -1) {
      // Keep highest score
      if (score > allProgress[idx].score) allProgress[idx].score = score;
      allProgress[idx].completed = true;
  } else {
      allProgress.push(entry);
  }
  saveLocalItems(LOCAL_PROGRESS_KEY, allProgress);
};

import React, { useState, useEffect } from 'react';
import { CefrLevel, PathCheckpoint, UserProgress } from '../types';
import { A2_SYLLABUS } from '../data/syllabus';
import { getPathProgress, markCheckpointComplete } from '../services/storageService';
import { CheckCircleIcon, PlayCircleIcon, LockClosedIcon } from '@heroicons/react/24/solid';
import { InteractiveText } from './InteractiveText';

interface PathExplorerProps {
  onStartQuiz: (topic: string, level: CefrLevel) => void;
}

const LEVELS: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];

export const PathExplorer: React.FC<PathExplorerProps> = ({ onStartQuiz }) => {
  const [activeLevel, setActiveLevel] = useState<CefrLevel>('A2');
  const [progress, setProgress] = useState<UserProgress[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadProgress();
  }, [activeLevel]);

  const loadProgress = async () => {
    setLoading(true);
    try {
      const data = await getPathProgress(activeLevel);
      setProgress(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const getCheckpointStatus = (title: string, index: number) => {
    const entry = progress.find(p => p.checkpoint_title === title);
    if (entry?.completed) return { status: 'completed', score: entry.score };

    // Check if previous is completed to unlock current
    if (index === 0) return { status: 'unlocked', score: 0 };

    // Logic: Unlocked if previous checkpoint is completed
    const prevTitle = A2_SYLLABUS[index - 1].title;
    const prevEntry = progress.find(p => p.checkpoint_title === prevTitle);

    if (prevEntry?.completed) return { status: 'unlocked', score: 0 };
    return { status: 'locked', score: 0 };
  };

  const renderSyllabus = () => {
    // Currently only A2 is implemented as per spec
    if (activeLevel !== 'A2') {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center animate-fade-in">
                <LockClosedIcon className="w-16 h-16 text-slate-200 dark:text-slate-800 mb-4" />
                <h3 className="text-xl font-bold text-slate-400 dark:text-slate-600">Coming Soon</h3>
                <p className="text-slate-400 dark:text-slate-500 mt-2 max-w-sm">
                    The {activeLevel} path is currently under construction. Please try A2.
                </p>
            </div>
        );
    }

    return (
        <div className="max-w-3xl mx-auto py-8 relative">
            {/* Vertical Line */}
            <div className="absolute left-6 md:left-8 top-12 bottom-12 w-0.5 bg-slate-200 dark:bg-slate-800 z-0"></div>

            {A2_SYLLABUS.map((checkpoint, index) => {
                const { status, score } = getCheckpointStatus(checkpoint.title, index);
                const isLocked = status === 'locked';
                const isCompleted = status === 'completed';

                return (
                    <div key={index} className={`relative z-10 pl-20 md:pl-24 mb-12 last:mb-0 group ${isLocked ? 'opacity-50 grayscale' : 'opacity-100'}`}>
                        {/* Connector Dot */}
                        <div className={`
                            absolute left-3 md:left-5 top-6 -translate-x-1/2 w-6 h-6 md:w-8 md:h-8 rounded-full border-4 flex items-center justify-center transition-colors shadow-sm bg-white dark:bg-slate-900
                            ${isCompleted 
                                ? 'border-green-500 text-green-500' 
                                : isLocked 
                                    ? 'border-slate-300 dark:border-slate-700 text-slate-300' 
                                    : 'border-french-blue dark:border-blue-500 text-french-blue dark:text-blue-500'
                            }
                        `}>
                            {isCompleted && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-green-500" />}
                            {!isCompleted && !isLocked && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-french-blue dark:bg-blue-500 animate-pulse" />}
                        </div>

                        {/* Content Card */}
                        <div className={`
                            bg-white dark:bg-slate-900 rounded-2xl p-6 border transition-all duration-300
                            ${isLocked 
                                ? 'border-slate-100 dark:border-slate-800' 
                                : isCompleted
                                    ? 'border-green-200 dark:border-green-900/50 shadow-sm'
                                    : 'border-french-blue dark:border-blue-600 shadow-md ring-1 ring-french-blue/10'
                            }
                        `}>
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-3">
                                <div>
                                    <h3 className="text-xl font-bold font-serif text-slate-800 dark:text-slate-100">
                                        {checkpoint.title}
                                    </h3>
                                    {isCompleted && (
                                        <span className="inline-flex items-center gap-1 text-xs font-bold text-green-600 dark:text-green-400 mt-1">
                                            <CheckCircleIcon className="w-3 h-3" />
                                            Completed (Best: {score}/10)
                                        </span>
                                    )}
                                </div>
                                {!isLocked && (
                                    <button 
                                        onClick={() => onStartQuiz(checkpoint.title, 'A2')}
                                        className="flex items-center gap-2 px-5 py-2 bg-french-dark dark:bg-slate-700 hover:bg-black dark:hover:bg-slate-600 text-white text-sm font-bold rounded-full transition-all shadow-md active:scale-95 flex-shrink-0 w-fit"
                                    >
                                        <PlayCircleIcon className="w-5 h-5" />
                                        {isCompleted ? 'Practice Again' : 'Start Quiz'}
                                    </button>
                                )}
                            </div>

                            <p className="text-slate-600 dark:text-slate-400 mb-4 leading-relaxed">
                                {checkpoint.description}
                            </p>

                            <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-4 border border-slate-100 dark:border-slate-800">
                                <span className="text-xs font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block tracking-wider">Examples</span>
                                <ul className="space-y-2">
                                    {checkpoint.examples.map((ex, i) => (
                                        <li key={i} className="text-sm text-slate-700 dark:text-slate-300 italic">
                                            • <InteractiveText text={ex} glossary={[]} level="A2" />
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
    );
  };

  return (
    <div className="w-full max-w-5xl mx-auto animate-fade-in">
        {/* Level Tabs */}
        <div className="flex justify-center mb-12">
            <div className="bg-white dark:bg-slate-900 p-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-800 inline-flex">
                {LEVELS.map(lvl => (
                    <button
                        key={lvl}
                        onClick={() => setActiveLevel(lvl)}
                        className={`
                            px-6 py-2 rounded-full font-bold text-sm transition-all
                            ${activeLevel === lvl 
                                ? 'bg-french-blue text-white shadow-md' 
                                : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'
                            }
                            ${lvl !== 'A2' ? 'opacity-60' : ''}
                        `}
                    >
                        {lvl}
                    </button>
                ))}
            </div>
        </div>

        {/* Syllabus List */}
        {renderSyllabus()}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { generateQuiz, generateStory, checkApiKeyConfigured } from './services/geminiService';
import { 
    saveQuizToHistory, getSavedQuizzes, deleteSavedQuiz, 
    saveStoryToHistory, getSavedStories, deleteSavedStory,
    checkSupabaseConnection, markCheckpointComplete
} from './services/storageService';
import { QuizSettings, QuizData, StoryData, SavedQuiz, SavedStory, CefrLevel } from './types';
import { QuizForm } from './components/QuizForm';
import { QuizInterface } from './components/QuizInterface';
import { StoryInterface } from './components/StoryInterface';
import { VocabularyExplorer } from './components/VocabularyExplorer';
import { PathExplorer } from './components/PathExplorer';
import { QuizHistory } from './components/QuizHistory';
import { StoryHistory } from './components/StoryHistory';
import { BookOpenIcon, AcademicCapIcon, RectangleStackIcon, SunIcon, MoonIcon, ListBulletIcon, MapIcon } from '@heroicons/react/24/outline';

type Tab = 'quiz' | 'stories' | 'vocabulary' | 'path';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('quiz');
  const [cloudStatus, setCloudStatus] = useState<'connected' | 'offline'>('offline');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // --- THEME STATE ---
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('theme') === 'dark' ||
        (!('theme' in localStorage) && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [darkMode]);

  // --- QUIZ STATE ---
  const [quizData, setQuizData] = useState<QuizData | null>(null);
  const [activeQuizSource, setActiveQuizSource] = useState<'generator' | 'path'>('generator');
  const [activePathContext, setActivePathContext] = useState<{ topic: string, level: string } | null>(null);
  const [savedQuizzes, setSavedQuizzes] = useState<SavedQuiz[]>([]);
  const [showQuizHistory, setShowQuizHistory] = useState(false);

  // --- STORY STATE ---
  const [storyData, setStoryData] = useState<StoryData | null>(null);
  const [savedStories, setSavedStories] = useState<SavedStory[]>([]);
  const [showStoryHistory, setShowStoryHistory] = useState(false);

  // Initialize App
  useEffect(() => {
    const initApp = async () => {
        const hasKey = checkApiKeyConfigured();
        const isConnected = await checkSupabaseConnection();
        console.log(`Diagnostic: API Key ${hasKey}, DB ${isConnected}`);
        setCloudStatus(isConnected ? 'connected' : 'offline');

        try {
            const [qHistory, sHistory] = await Promise.all([
                getSavedQuizzes(),
                getSavedStories()
            ]);
            setSavedQuizzes(qHistory);
            setSavedStories(sHistory);
        } catch (e) {
            console.error("Failed to load history", e);
        }
    };
    initApp();
  }, []);

  // --- QUIZ HANDLERS ---
  const handleCreateQuiz = async (settings: QuizSettings, source: 'generator' | 'path' = 'generator') => {
    setLoading(true);
    setError(null);
    try {
      const response = await generateQuiz(settings);
      if (response && response.quiz) {
          setQuizData(response.quiz);
          setActiveQuizSource(source);
          if (source === 'path') {
              setActivePathContext({ topic: settings.topic, level: settings.level });
          } else {
              setShowQuizHistory(false);
          }

          try {
             // Only save to history if it's a general quiz, or optionally save path quizzes too
             const saved = await saveQuizToHistory(response.quiz);
             setSavedQuizzes(prev => [saved, ...prev]);
          } catch (e) { console.error("DB Save failed", e); }
      }
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectQuiz = (quiz: QuizData) => {
    setQuizData(quiz);
    setActiveQuizSource('generator');
    setShowQuizHistory(false);
  };

  const handleDeleteQuiz = async (id: string) => {
    const prev = savedQuizzes;
    setSavedQuizzes(p => p.filter(q => q.id !== id));
    try { await deleteSavedQuiz(id); } 
    catch { setSavedQuizzes(prev); }
  };

  const closeQuiz = (score?: number, total?: number) => {
      // If closing a path quiz with a passing score (e.g., > 60%), mark progress
      if (activeQuizSource === 'path' && activePathContext && score !== undefined && total !== undefined) {
         if (score >= total * 0.6) { // 60% Passing grade
             markCheckpointComplete(activePathContext.level, activePathContext.topic, score);
         }
      }

      setQuizData(null);
      setActivePathContext(null);
      setActiveQuizSource('generator');
  };

  // --- STORY HANDLERS ---
  const handleCreateStory = async (settings: QuizSettings) => {
    setLoading(true);
    setError(null);
    try {
      const response = await generateStory(settings);
      if (response && response.story) {
          setStoryData(response.story);
          setShowStoryHistory(false);
          try {
             const saved = await saveStoryToHistory(response.story);
             setSavedStories(prev => [saved, ...prev]);
          } catch (e) { console.error("DB Save failed", e); }
      }
    } catch (err: any) {
        setError(err.message);
    } finally {
        setLoading(false);
    }
  };

  const handleSelectStory = (story: StoryData) => {
      setStoryData(story);
      setShowStoryHistory(false);
  };

  const handleDeleteStory = async (id: string) => {
      const prev = savedStories;
      setSavedStories(p => p.filter(s => s.id !== id));
      try { await deleteSavedStory(id); }
      catch { setSavedStories(prev); }
  };

  const closeStory = () => {
      setStoryData(null);
  };

  // --- PATH HANDLER ---
  const handleStartPathQuiz = (topic: string, level: CefrLevel) => {
      handleCreateQuiz({
          topic,
          level,
          difficulty: 'Medium'
      }, 'path');
  };

  // --- RENDER HELPERS ---

  const renderQuizTab = () => {
      if (quizData) {
          return <div className="animate-fade-in-up w-full"><QuizInterface quiz={quizData} onFinish={closeQuiz} /></div>;
      }
      if (showQuizHistory) {
          return (
            <QuizHistory 
                quizzes={savedQuizzes} 
                onSelect={handleSelectQuiz} 
                onDelete={handleDeleteQuiz}
                onBack={() => setShowQuizHistory(false)}
            />
          );
      }
      return (
          <div className="w-full flex flex-col items-center">
              <div className="text-center mb-10 max-w-2xl animate-fade-in">
                  <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6">Test Your Skills</h1>
                  <p className="text-lg text-slate-500 dark:text-slate-400 mb-6">
                      Generate adaptive quizzes tailored to your proficiency level.
                  </p>
                  {savedQuizzes.length > 0 && (
                      <button 
                        onClick={() => setShowQuizHistory(true)}
                        className="inline-flex items-center gap-2 px-5 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full text-slate-600 dark:text-slate-300 text-sm font-medium hover:text-french-blue dark:hover:text-blue-400 hover:border-french-blue dark:hover:border-blue-400 transition-colors shadow-sm"
                      >
                          <RectangleStackIcon className="w-4 h-4" />
                          View Saved Quizzes ({savedQuizzes.length})
                      </button>
                  )}
              </div>
              <div className="animate-fade-in-up w-full flex justify-center">
                  <QuizForm onSubmit={(s) => handleCreateQuiz(s, 'generator')} isLoading={loading} mode="quiz" />
              </div>
          </div>
      );
  };

  const renderStoryTab = () => {
      if (storyData) {
          return <div className="animate-fade-in-up w-full"><StoryInterface story={storyData} onBack={closeStory} /></div>;
      }
      if (showStoryHistory) {
          return (
            <StoryHistory 
                stories={savedStories}
                onSelect={handleSelectStory}
                onDelete={handleDeleteStory}
                onBack={() => setShowStoryHistory(false)}
            />
          );
      }
      return (
          <div className="w-full flex flex-col items-center">
              <div className="text-center mb-10 max-w-2xl animate-fade-in">
                  <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6">Learn through Stories</h1>
                  <p className="text-lg text-slate-500 dark:text-slate-400 mb-6">
                      Generate immersive short stories with instant hover-translation.
                  </p>
                  {savedStories.length > 0 && (
                      <button 
                        onClick={() => setShowStoryHistory(true)}
                        className="inline-flex items-center gap-2 px-5 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full text-slate-600 dark:text-slate-300 text-sm font-medium hover:text-french-blue dark:hover:text-blue-400 hover:border-french-blue dark:hover:border-blue-400 transition-colors shadow-sm"
                      >
                          <RectangleStackIcon className="w-4 h-4" />
                          View Saved Stories ({savedStories.length})
                      </button>
                  )}
              </div>
              <div className="animate-fade-in-up w-full flex justify-center">
                  <QuizForm onSubmit={handleCreateStory} isLoading={loading} mode="story" />
              </div>
          </div>
      );
  };

  const renderPathTab = () => {
      if (quizData) {
          return <div className="animate-fade-in-up w-full"><QuizInterface quiz={quizData} onFinish={closeQuiz} /></div>;
      }
      return (
        <div className="w-full flex flex-col items-center">
             <div className="text-center mb-10 max-w-2xl animate-fade-in">
                  <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-800 dark:text-slate-100 mb-6">Learning Path</h1>
                  <p className="text-lg text-slate-500 dark:text-slate-400 mb-6">
                      Follow a structured syllabus to master French step-by-step.
                  </p>
             </div>
             <PathExplorer onStartQuiz={handleStartPathQuiz} />
        </div>
      );
  };

  return (
