import { StudyGuideContent, CefrLevel } from '../types';
import { generateStudyGuide } from '../services/geminiService';
import { getStudyGuide, saveStudyGuide, getSavedQuizzesByTopic } from '../services/storageService';
import { InteractiveText } from './InteractiveText';
import { ArrowLeftIcon, BookOpenIcon, ExclamationTriangleIcon, PlayCircleIcon, LightBulbIcon, RectangleStackIcon, ClockIcon } from '@heroicons/react/24/solid';

interface StudyGuideViewProps {
  topic: string;
  level: CefrLevel;
  allowCumulative: boolean;
  onBack: () => void;
  onStartQuiz: (cumulative: boolean) => void;
  onViewHistory: (topic: string) => void;
}

export const StudyGuideView: React.FC<StudyGuideViewProps> = ({ topic, level, allowCumulative, onBack, onStartQuiz, onViewHistory }) => {
  const [content, setContent] = useState<StudyGuideContent | null>(null);
  const [loading, setLoading] = useState(true);
  const [isCumulative, setIsCumulative] = useState(false);
  const [savedCount, setSavedCount] = useState(0);

  useEffect(() => {
    loadGuide();
    checkHistory();
  }, [topic, level]);

  const loadGuide = async () => {
    setLoading(true);
    try {
      // 1. Try DB first
      const cached = await getStudyGuide(topic, level);
      if (cached) {
        setContent(cached);
        setLoading(false);
        return;
      }

      // 2. Generate if missing
      const response = await generateStudyGuide(topic, level);
      const newGuide = response.guide;

      setContent(newGuide);

      // 3. Save to DB
      await saveStudyGuide(topic, level, newGuide);
    } catch (e) {
      console.error("Failed to load guide", e);
    } finally {
      setLoading(false);
    }
  };

  const checkHistory = async () => {
    try {
        const history = await getSavedQuizzesByTopic(topic);
        setSavedCount(history.length);
    } catch(e) { console.error(e); }
  };

  if (loading) {
     return (
        <div className="w-full max-w-3xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl p-12 flex flex-col items-center justify-center min-h-[500px] transition-colors">
            <div className="relative mb-8">
              <div className="w-20 h-20 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
              <div className="w-20 h-20 border-4 border-french-blue rounded-full border-t-transparent animate-spin absolute top-0 left-0"></div>
            </div>
            <h3 className="text-2xl font-serif font-bold text-slate-800 dark:text-slate-100 animate-pulse">
              Consulting the Professor...
            </h3>
            <p className="text-slate-500 dark:text-slate-400 mt-2">
               Preparing study notes for "{topic}"
            </p>
         </div>
     );
  }

  if (!content) return <div>Error loading content.</div>;

  return (
    <div className="w-full max-w-4xl mx-auto animate-fade-in pb-12">
        <button 
          onClick={onBack}
          className="mb-6 flex items-center gap-2 text-slate-500 dark:text-slate-400 hover:text-french-blue dark:hover:text-blue-400 transition-colors font-medium"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          Back to Path
        </button>

        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-hidden border border-slate-100 dark:border-slate-800 transition-colors">
            {/* Header */}
            <div className="bg-french-blue dark:bg-slate-800 p-8 text-white relative">
                 <div className="absolute top-0 right-0 p-4 opacity-10">
                     <BookOpenIcon className="w-32 h-32" />
                 </div>
                 <span className="inline-block px-3 py-1 bg-white/20 rounded-full text-xs font-bold tracking-wider mb-3 uppercase">
                    {level} Study Guide
                 </span>
                 <h1 className="text-4xl font-serif font-bold relative z-10">{topic}</h1>

                 {savedCount > 0 && (
                     <button 
                        onClick={() => onViewHistory(topic)}
                        className="mt-4 flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm font-medium transition-colors border border-white/20"
                     >
                        <ClockIcon className="w-4 h-4" />
                        View {savedCount} Past Quiz{savedCount !== 1 ? 'zes' : ''}
                     </button>
                 )}
            </div>

            <div className="p-8 md:p-12 space-y-10">

                {/* Concept */}
                <section>
                    <div className="flex items-center gap-3 mb-4">
                        <div className="p-2 bg-blue-100 dark:bg-blue-900/30 text-french-blue dark:text-blue-300 rounded-lg">
                             <LightBulbIcon className="w-6 h-6" />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-100">Concept</h2>
                    </div>
                    <p className="text-lg leading-relaxed text-slate-700 dark:text-slate-300">
                        {content.concept_explanation}
                    </p>
                </section>

                <hr className="border-slate-100 dark:border-slate-800" />

                {/* Key Rules */}
                <section>
                    <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-4 uppercase tracking-wide">Key Rules</h3>
                    <ul className="space-y-3">
                        {content.key_rules.map((rule, idx) => (
                            <li key={idx} className="flex items-start gap-3 text-slate-700 dark:text-slate-300">
                                <span className="mt-1.5 w-1.5 h-1.5 rounded-full bg-french-blue dark:bg-blue-500 flex-shrink-0"></span>
                                <span className="leading-relaxed">{rule}</span>
                            </li>
                        ))}
                    </ul>
                </section>

                {/* Exceptions (Conditional) */}
                {content.exceptions && content.exceptions.length > 0 && (
                    <section className="bg-amber-50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-800/50 rounded-xl p-6">
                        <div className="flex items-center gap-2 mb-4 text-amber-700 dark:text-amber-500">
                            <ExclamationTriangleIcon className="w-6 h-6" />
                            <h3 className="text-lg font-bold uppercase tracking-wide">Exceptions & Warnings</h3>
                        </div>
                        <ul className="space-y-2">
                             {content.exceptions.map((ex, idx) => (
                                 <li key={idx} className="text-amber-900 dark:text-amber-200/80 text-sm md:text-base">
                                     • {ex}
                                 </li>
                             ))}
                        </ul>
                    </section>
                )}

                {/* Examples */}
                <section>
                    <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-6 uppercase tracking-wide">Examples in Context</h3>
                    <div className="grid gap-4">
                        {content.examples.map((ex, idx) => (
                            <div key={idx} className="p-4 rounded-lg bg-slate-50 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800">
                                <div className="text-lg font-medium text-french-blue dark:text-blue-300 mb-1 font-serif">
                                    <InteractiveText text={ex.french} glossary={[]} level={level} />
                                </div>
                                <div className="text-slate-500 dark:text-slate-500 italic text-sm">{ex.english}</div>
                            </div>
                        ))}
                    </div>
                </section>

                {/* Action Area */}
                <div className="pt-8 flex flex-col items-center gap-6">

                    {allowCumulative && (
                        <label className="group flex items-center gap-4 cursor-pointer p-4 rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50 hover:bg-white dark:hover:bg-slate-800 hover:border-french-blue dark:hover:border-blue-500 transition-all w-full max-w-lg">
                            <div className={`
                                w-6 h-6 rounded border flex items-center justify-center transition-colors
                                ${isCumulative 
                                    ? 'bg-french-blue dark:bg-blue-500 border-french-blue dark:border-blue-500 text-white' 
                                    : 'bg-white dark:bg-slate-800 border-slate-300 dark:border-slate-600'
                                }
                            `}>
                                <input 
                                    type="checkbox" 
                                    checked={isCumulative} 
                                    onChange={(e) => setIsCumulative(e.target.checked)}
                                    className="hidden"
                                />
                                {isCumulative && <svg className="w-4 h-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" /></svg>}
                            </div>
                            <div className="flex-grow">
                                <h4 className="font-bold text-slate-800 dark:text-slate-100 group-hover:text-french-blue dark:group-hover:text-blue-400 transition-colors flex items-center gap-2">
                                    <RectangleStackIcon className="w-4 h-4" />
                                    Include All Previous Topics
                                </h4>
                                <p className="text-sm text-slate-500 dark:text-slate-400">Generate a comprehensive quiz covering everything up to this point.</p>
                            </div>
                        </label>
                    )}

                    <div className="text-center">
                        <p className="text-slate-500 dark:text-slate-400 mb-4">Ready to test your knowledge?</p>
                        <button 
                            onClick={() => onStartQuiz(isCumulative)}
                            className="flex items-center gap-2 px-8 py-4 bg-french-dark dark:bg-slate-700 text-white rounded-full font-bold text-lg hover:bg-black dark:hover:bg-slate-600 transition-all shadow-xl hover:shadow-2xl hover:-translate-y-1"
                        >
                            <PlayCircleIcon className="w-6 h-6" />
                            {isCumulative ? 'Start Cumulative Quiz' : 'Start Topic Quiz'}
                        </button>
                    </div>
                </div>

            </div>
        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { CefrLevel, PathCheckpoint, UserProgress } from '../types';
import { A2_SYLLABUS } from '../data/syllabus';
import { getPathProgress, markCheckpointComplete } from '../services/storageService';
import { CheckCircleIcon, PlayCircleIcon, LockClosedIcon, BookOpenIcon, ChevronRightIcon } from '@heroicons/react/24/solid';
import { InteractiveText } from './InteractiveText';
import { StudyGuideView } from './StudyGuideView';

interface PathExplorerProps {
  onStartQuiz: (topic: string, level: CefrLevel) => void;
  onViewHistory: (topic: string) => void;
}

const LEVELS: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];

export const PathExplorer: React.FC<PathExplorerProps> = ({ onStartQuiz, onViewHistory }) => {
  const [activeLevel, setActiveLevel] = useState<CefrLevel>('A2');
  const [progress, setProgress] = useState<UserProgress[]>([]);
  const [loading, setLoading] = useState(false);

  // Navigation State
  const [selectedTopic, setSelectedTopic] = useState<string | null>(null);

  useEffect(() => {
    loadProgress();
  }, [activeLevel]);

  const loadProgress = async () => {
    setLoading(true);
    try {
      const data = await getPathProgress(activeLevel);
      setProgress(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const getCheckpointStatus = (title: string, index: number) => {
    const entry = progress.find(p => p.checkpoint_title === title);
    if (entry?.completed) return { status: 'completed', score: entry.score };

    // Previously locked logic removed to enable all topics
    return { status: 'unlocked', score: 0 };
  };

  const handleStartQuizFromGuide = (cumulative: boolean) => {
      if (!selectedTopic) return;

      let quizTopic = selectedTopic;

      if (cumulative && activeLevel === 'A2') {
          const currentIndex = A2_SYLLABUS.findIndex(t => t.title === selectedTopic);
          if (currentIndex > 0) {
              const previousTitles = A2_SYLLABUS.slice(0, currentIndex + 1).map(t => t.title);
              // Construct a prompt-friendly string containing all topics
              quizTopic = `Cumulative Review of: ${previousTitles.join(', ')}`;
          }
      }

      setSelectedTopic(null); // Close the guide
      onStartQuiz(quizTopic, activeLevel);
  };

  // --- RENDERERS ---

  if (selectedTopic) {
      const currentIndex = A2_SYLLABUS.findIndex(t => t.title === selectedTopic);
      const allowCumulative = currentIndex > 0;

      return (
          <StudyGuideView 
             topic={selectedTopic} 
             level={activeLevel} 
             allowCumulative={allowCumulative}
             onBack={() => setSelectedTopic(null)}
             onStartQuiz={handleStartQuizFromGuide}
             onViewHistory={onViewHistory}
          />
      );
  }

  const renderSyllabus = () => {
    // Currently only A2 is implemented as per spec
    if (activeLevel !== 'A2') {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center animate-fade-in">
                <LockClosedIcon className="w-16 h-16 text-slate-200 dark:text-slate-800 mb-4" />
                <h3 className="text-xl font-bold text-slate-400 dark:text-slate-600">Coming Soon</h3>
                <p className="text-slate-400 dark:text-slate-500 mt-2 max-w-sm">
                    The {activeLevel} path is currently under construction. Please try A2.
                </p>
            </div>
        );
    }

    // Determine the next recommended step (first incomplete item) to highlight
    const firstIncompleteIndex = A2_SYLLABUS.findIndex(item => !progress.find(p => p.checkpoint_title === item.title)?.completed);

    return (
        <div className="max-w-3xl mx-auto py-8 relative">
            {/* Vertical Line */}
            <div className="absolute left-6 md:left-8 top-12 bottom-12 w-0.5 bg-slate-200 dark:bg-slate-800 z-0"></div>

            {A2_SYLLABUS.map((checkpoint, index) => {
                const { status, score } = getCheckpointStatus(checkpoint.title, index);
                const isLocked = status === 'locked'; // Always false now
                const isCompleted = status === 'completed';
                const isRecommended = index === firstIncompleteIndex;

                return (
                    <div key={index} className={`relative z-10 pl-20 md:pl-24 mb-12 last:mb-0 group ${isLocked ? 'opacity-50 grayscale' : 'opacity-100'}`}>
                        {/* Connector Dot */}
                        <div className={`
                            absolute left-3 md:left-5 top-6 -translate-x-1/2 w-6 h-6 md:w-8 md:h-8 rounded-full border-4 flex items-center justify-center transition-colors shadow-sm bg-white dark:bg-slate-900
                            ${isCompleted 
                                ? 'border-green-500 text-green-500' 
                                : isLocked 
                                    ? 'border-slate-300 dark:border-slate-700 text-slate-300' 
                                    : 'border-french-blue dark:border-blue-500 text-french-blue dark:text-blue-500'
                            }
                        `}>
                            {isCompleted && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-green-500" />}
                            {/* Pulse only the recommended next step to avoid visual noise */}
                            {!isCompleted && !isLocked && isRecommended && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-french-blue dark:bg-blue-500 animate-pulse" />}
                        </div>

                        {/* Content Card */}
                        <div 
                            onClick={() => !isLocked && setSelectedTopic(checkpoint.title)}
                            className={`
                            bg-white dark:bg-slate-900 rounded-2xl p-6 border transition-all duration-300
                            ${isLocked 
                                ? 'border-slate-100 dark:border-slate-800 cursor-not-allowed' 
                                : isCompleted
                                    ? 'border-green-200 dark:border-green-900/50 shadow-sm cursor-pointer hover:border-green-300 dark:hover:border-green-800'
                                    : 'border-french-blue dark:border-blue-600 shadow-md ring-1 ring-french-blue/10 cursor-pointer hover:shadow-xl hover:-translate-y-1'
                            }
                        `}>
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-3">
                                <div>
                                    <h3 className="text-xl font-bold font-serif text-slate-800 dark:text-slate-100 group-hover:text-french-blue dark:group-hover:text-blue-400 transition-colors">
                                        {checkpoint.title}
                                    </h3>
                                    {isCompleted && (
                                        <span className="inline-flex items-center gap-1 text-xs font-bold text-green-600 dark:text-green-400 mt-1">
                                            <CheckCircleIcon className="w-3 h-3" />
                                            Completed (Best: {score}/10)
                                        </span>
                                    )}
                                </div>
                                {!isLocked && (
                                    <div className="flex items-center text-sm font-bold text-french-blue dark:text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity -translate-x-2 group-hover:translate-x-0">
                                        Open Guide <ChevronRightIcon className="w-4 h-4 ml-1" />
                                    </div>
                                )}
                            </div>

                            <p className="text-slate-600 dark:text-slate-400 mb-4 leading-relaxed">
                                {checkpoint.description}
                            </p>

                            <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-4 border border-slate-100 dark:border-slate-800">
                                <span className="text-xs font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block tracking-wider">Examples</span>
                                <ul className="space-y-2">
                                    {checkpoint.examples.map((ex, i) => (
                                        <li key={i} className="text-sm text-slate-700 dark:text-slate-300 italic">
                                            • <InteractiveText text={ex} glossary={[]} level="A2" />
                                        </li>
                                    ))}
                                </ul>
                            </div>

                            {!isLocked && (
                                <div className="mt-4 pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-end">
                                     <button className="flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-french-blue dark:text-slate-400 dark:hover:text-blue-400 transition-colors">
                                         <BookOpenIcon className="w-4 h-4" />
                                         Study Concept
                                     </button>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
        </div>
    );
  };

  return (
    <div className="w-full max-w-5xl mx-auto animate-fade-in">
        {/* Level Tabs */}
        <div className="flex justify-center mb-12">
            <div className="bg-white dark:bg-slate-900 p-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-800 inline-flex">
                {LEVELS.map(lvl => (
                    <button
                        key={lvl}
                        onClick={() => setActiveLevel(lvl)}
                        className={`
                            px-6 py-2 rounded-full font-bold text-sm transition-all
                            ${activeLevel === lvl 
                                ? 'bg-french-blue text-white shadow-md' 
                                : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'
                            }
                            ${lvl !== 'A2' ? 'opacity-60' : ''}
                        `}
                    >
                        {lvl}
                    </button>
                ))}
            </div>
        </div>

        {/* Syllabus List */}
        {renderSyllabus()}
    </div>
  );
};

import React from 'react';
import { SavedQuiz, QuizData } from '../types';
import { TrashIcon, PlayCircleIcon, ArrowLeftIcon, CalendarDaysIcon } from '@heroicons/react/24/solid';

interface QuizHistoryProps {
  quizzes: SavedQuiz[];
  onSelect: (quiz: QuizData) => void;
  onDelete: (id: string) => void;
  onBack: () => void;
  filterTopic?: string | null;
}

export const QuizHistory: React.FC<QuizHistoryProps> = ({ quizzes, onSelect, onDelete, onBack, filterTopic }) => {

  const formatDate = (timestamp: number) => {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(new Date(timestamp));
  };

  return (
    <div className="w-full max-w-4xl mx-auto animate-fade-in">
      {/* Header */}
      <div className="flex items-center justify-between mb-8">
        <button 
          onClick={onBack}
          className="flex items-center gap-2 text-slate-500 dark:text-slate-400 hover:text-french-blue dark:hover:text-blue-400 transition-colors font-medium"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          {filterTopic ? 'Back to Guide' : 'Back to Generator'}
        </button>
        <div className="text-right">
            <h2 className="text-2xl font-serif font-bold text-slate-800 dark:text-slate-100">Saved Quizzes</h2>
            {filterTopic && <p className="text-sm text-slate-500 dark:text-slate-400">Filter: {filterTopic}</p>}
        </div>
      </div>

      {quizzes.length === 0 ? (
        <div className="text-center py-20 bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800">
           <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-400 dark:text-slate-500">
              <CalendarDaysIcon className="w-8 h-8" />
           </div>
           <h3 className="text-lg font-medium text-slate-700 dark:text-slate-300">No quizzes saved {filterTopic ? 'for this topic' : 'yet'}</h3>
           <p className="text-slate-500 dark:text-slate-400 mt-2">Generate a quiz to see it here.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {quizzes.map((item) => (
            <div 
              key={item.id} 
              className="bg-white dark:bg-slate-900 p-6 rounded-xl shadow-sm border border-slate-100 dark:border-slate-800 hover:shadow-md transition-all group relative overflow-hidden"
            >
              <div className="absolute top-0 left-0 w-1 h-full bg-french-blue dark:bg-blue-500 opacity-0 group-hover:opacity-100 transition-opacity"></div>

              <div className="flex justify-between items-start mb-4 pl-2">
                <div>
                   <span className="inline-block px-2 py-1 bg-blue-50 dark:bg-blue-900/20 text-french-blue dark:text-blue-300 text-xs font-bold rounded mb-2">
                      {item.data.cefr_level} • {item.data.sub_difficulty}
                   </span>
                   <h3 className="font-serif font-bold text-lg text-slate-800 dark:text-slate-100 leading-tight">
                     {item.data.topic}
                   </h3>
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); onDelete(item.id); }}
                  className="p-2 text-slate-300 dark:text-slate-600 hover:text-red-500 dark:hover:text-red-400 transition-colors rounded-full hover:bg-red-50 dark:hover:bg-red-900/20"
                  title="Delete Quiz"
                >
                  <TrashIcon className="w-5 h-5" />
                </button>
              </div>

              <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-50 dark:border-slate-800 pl-2">
                 <span className="text-xs text-slate-400 dark:text-slate-500 font-medium">
                   {formatDate(item.created_at)}
                 </span>
                 <button
                    onClick={() => onSelect(item.data)}
                    className="flex items-center gap-2 text-sm font-bold text-french-blue dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 transition-colors"
                 >
                    Play Again
                    <PlayCircleIcon className="w-5 h-5" />
                 </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

