import React, { useState, useEffect } from 'react';
import { CefrLevel, PathCheckpoint, UserProgress } from '../types';
import { A2_SYLLABUS, B1_SYLLABUS } from '../data/syllabus';
import { getPathProgress, markCheckpointComplete } from '../services/storageService';
import { CheckCircleIcon, PlayCircleIcon, LockClosedIcon, BookOpenIcon, ChevronRightIcon } from '@heroicons/react/24/solid';
import { InteractiveText } from './InteractiveText';
import { StudyGuideView } from './StudyGuideView';

interface PathExplorerProps {
  onStartQuiz: (topic: string, level: CefrLevel) => void;
  onViewHistory: (topic: string) => void;
  initialTopic?: string | null;
  onTopicOpened?: () => void;
}

const LEVELS: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];

export const PathExplorer: React.FC<PathExplorerProps> = ({ onStartQuiz, onViewHistory, initialTopic, onTopicOpened }) => {
  const [activeLevel, setActiveLevel] = useState<CefrLevel>('A2');
  const [progress, setProgress] = useState<UserProgress[]>([]);
  const [loading, setLoading] = useState(false);

  // Navigation State
  const [selectedTopic, setSelectedTopic] = useState<string | null>(null);

  useEffect(() => {
    loadProgress();
  }, [activeLevel]);

  // Handle auto-open of topic if returning from quiz
  useEffect(() => {
      if (initialTopic) {
          setSelectedTopic(initialTopic);
          if (onTopicOpened) onTopicOpened();
      }
  }, [initialTopic]);

  const loadProgress = async () => {
    setLoading(true);
    try {
      const data = await getPathProgress(activeLevel);
      setProgress(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const getSyllabusForLevel = (level: CefrLevel): PathCheckpoint[] => {
      if (level === 'A2') return A2_SYLLABUS;
      if (level === 'B1') return B1_SYLLABUS;
      return [];
  };

  const getCheckpointStatus = (title: string, index: number) => {
    const entry = progress.find(p => p.checkpoint_title === title);
    if (entry?.completed) return { status: 'completed', score: entry.score };

    // Previously locked logic removed to enable all topics
    return { status: 'unlocked', score: 0 };
  };

  const handleStartQuizFromGuide = (cumulative: boolean) => {
      if (!selectedTopic) return;

      let quizTopic = selectedTopic;
      const currentSyllabus = getSyllabusForLevel(activeLevel);

      if (cumulative && currentSyllabus.length > 0) {
          const currentIndex = currentSyllabus.findIndex(t => t.title === selectedTopic);
          if (currentIndex > 0) {
              const previousTitles = currentSyllabus.slice(0, currentIndex + 1).map(t => t.title);
              // Construct a prompt-friendly string containing all topics
              quizTopic = `Cumulative Review of: ${previousTitles.join(', ')}`;
          }
      }

      // We don't nullify selectedTopic here immediately if we want to return to it, 
      // but the quiz view replaces this component anyway.
      setSelectedTopic(null); 
      onStartQuiz(quizTopic, activeLevel);
  };

  // --- RENDERERS ---

  if (selectedTopic) {
      const currentSyllabus = getSyllabusForLevel(activeLevel);
      const currentIndex = currentSyllabus.findIndex(t => t.title === selectedTopic);
      const allowCumulative = currentIndex > 0;

      return (
          <StudyGuideView 
             topic={selectedTopic} 
             level={activeLevel} 
             allowCumulative={allowCumulative}
             onBack={() => setSelectedTopic(null)}
             onStartQuiz={handleStartQuizFromGuide}
             onViewHistory={onViewHistory}
          />
      );
  }

  const renderSyllabus = () => {
    const currentSyllabus = getSyllabusForLevel(activeLevel);

    // If syllabus is empty (A1 or B2), show Coming Soon
    if (currentSyllabus.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center animate-fade-in">
                <LockClosedIcon className="w-16 h-16 text-slate-200 dark:text-slate-800 mb-4" />
                <h3 className="text-xl font-bold text-slate-400 dark:text-slate-600">Coming Soon</h3>
                <p className="text-slate-400 dark:text-slate-500 mt-2 max-w-sm">
                    The {activeLevel} path is currently under construction. Please try A2 or B1.
                </p>
            </div>
        );
    }

    // Determine the next recommended step (first incomplete item) to highlight
    const firstIncompleteIndex = currentSyllabus.findIndex(item => !progress.find(p => p.checkpoint_title === item.title)?.completed);

    return (
        <div className="max-w-3xl mx-auto py-8 relative">
            {/* Vertical Line */}
            <div className="absolute left-6 md:left-8 top-12 bottom-12 w-0.5 bg-slate-200 dark:bg-slate-800 z-0"></div>

            {currentSyllabus.map((checkpoint, index) => {
                const { status, score } = getCheckpointStatus(checkpoint.title, index);
                const isLocked = status === 'locked'; // Always false now
                const isCompleted = status === 'completed';
                const isRecommended = index === firstIncompleteIndex;

                return (
                    <div key={index} className={`relative z-10 pl-20 md:pl-24 mb-12 last:mb-0 group ${isLocked ? 'opacity-50 grayscale' : 'opacity-100'}`}>
                        {/* Connector Dot */}
                        <div className={`
                            absolute left-3 md:left-5 top-6 -translate-x-1/2 w-6 h-6 md:w-8 md:h-8 rounded-full border-4 flex items-center justify-center transition-colors shadow-sm bg-white dark:bg-slate-900
                            ${isCompleted 
                                ? 'border-green-500 text-green-500' 
                                : isLocked 
                                    ? 'border-slate-300 dark:border-slate-700 text-slate-300' 
                                    : 'border-french-blue dark:border-blue-500 text-french-blue dark:text-blue-500'
                            }
                        `}>
                            {isCompleted && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-green-500" />}
                            {/* Pulse only the recommended next step to avoid visual noise */}
                            {!isCompleted && !isLocked && isRecommended && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-french-blue dark:bg-blue-500 animate-pulse" />}
                        </div>

                        {/* Content Card */}
                        <div 
                            onClick={() => !isLocked && setSelectedTopic(checkpoint.title)}
                            className={`
                            bg-white dark:bg-slate-900 rounded-2xl p-6 border transition-all duration-300
                            ${isLocked 
                                ? 'border-slate-100 dark:border-slate-800 cursor-not-allowed' 
                                : isCompleted
                                    ? 'border-green-200 dark:border-green-900/50 shadow-sm cursor-pointer hover:border-green-300 dark:hover:border-green-800'
                                    : 'border-french-blue dark:border-blue-600 shadow-md ring-1 ring-french-blue/10 cursor-pointer hover:shadow-xl hover:-translate-y-1'
                            }
                        `}>
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-3">
                                <div>
                                    <h3 className="text-xl font-bold font-serif text-slate-800 dark:text-slate-100 group-hover:text-french-blue dark:group-hover:text-blue-400 transition-colors">
                                        {checkpoint.title}
                                    </h3>
                                    {isCompleted && (
                                        <span className="inline-flex items-center gap-1 text-xs font-bold text-green-600 dark:text-green-400 mt-1">
                                            <CheckCircleIcon className="w-3 h-3" />
                                            Completed (Best: {score}/10)
                                        </span>
                                    )}
                                </div>
                                {!isLocked && (
                                    <div className="flex items-center text-sm font-bold text-french-blue dark:text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity -translate-x-2 group-hover:translate-x-0">
                                        Open Guide <ChevronRightIcon className="w-4 h-4 ml-1" />
                                    </div>
                                )}
                            </div>

                            <p className="text-slate-600 dark:text-slate-400 mb-4 leading-relaxed">
                                {checkpoint.description}
                            </p>

                            <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-4 border border-slate-100 dark:border-slate-800">
                                <span className="text-xs font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block tracking-wider">Examples</span>
                                <ul className="space-y-2">
                                    {checkpoint.examples.map((ex, i) => (
                                        <li key={i} className="text-sm text-slate-700 dark:text-slate-300 italic">
                                            • <InteractiveText text={ex} glossary={[]} level={activeLevel} />
                                        </li>
                                    ))}
                                </ul>
                            </div>

                            {!isLocked && (
                                <div className="mt-4 pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-end">
                                     <button className="flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-french-blue dark:text-slate-400 dark:hover:text-blue-400 transition-colors">
                                         <BookOpenIcon className="w-4 h-4" />
                                         Study Concept
                                     </button>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
        </div>
    );
  };

  return (
    <div className="w-full max-w-5xl mx-auto animate-fade-in">
        {/* Level Tabs */}
        <div className="flex justify-center mb-12">
            <div className="bg-white dark:bg-slate-900 p-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-800 inline-flex">
                {LEVELS.map(lvl => (
                    <button
                        key={lvl}
                        onClick={() => setActiveLevel(lvl)}
                        className={`
                            px-6 py-2 rounded-full font-bold text-sm transition-all
                            ${activeLevel === lvl 
                                ? 'bg-french-blue text-white shadow-md' 
                                : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'
                            }
                            ${lvl !== 'A2' && lvl !== 'B1' ? 'opacity-60' : ''}
                        `}
                    >
                        {lvl}
                    </button>
                ))}
            </div>
        </div>

        {/* Syllabus List */}
        {renderSyllabus()}
    </div>
  );
};

import { supabase, isSupabaseConfigured } from './supabaseClient';
import { QuizData, StoryData, SavedQuiz, SavedStory, VocabularyEntry, CefrLevel, WordDetail, UserProgress, StudyGuideDB, StudyGuideContent, PathCheckpoint } from '../types';

const LOCAL_QUIZ_KEY = 'lumiere_local_quizzes';
const LOCAL_STORY_KEY = 'lumiere_local_stories';
const LOCAL_VOCAB_PREFIX = 'lumiere_vocab_'; 
const LOCAL_PROGRESS_KEY = 'lumiere_progress';
const LOCAL_GUIDES_KEY = 'lumiere_study_guides';

const getUserId = () => {
  const KEY = 'lumiere_device_id';
  let id = localStorage.getItem(KEY);
  if (!id) {
    id = crypto.randomUUID();
    localStorage.setItem(KEY, id);
  }
  return id;
};

const getLocalItems = <T>(key: string): T[] => {
    try {
        const item = localStorage.getItem(key);
        return item ? JSON.parse(item) : [];
    } catch {
        return [];
    }
};

const saveLocalItems = <T>(key: string, items: T[]) => {
    localStorage.setItem(key, JSON.stringify(items));
};

export const checkSupabaseConnection = async (): Promise<boolean> => {
  if (!isSupabaseConfigured()) return false;
  try {
    const { error } = await supabase.from('quizzes').select('id', { count: 'exact', head: true });
    return !error;
  } catch (e) {
    return false;
  }
};

// --- QUIZZES ---
export const saveQuizToHistory = async (quiz: QuizData): Promise<SavedQuiz> => {
  const userId = getUserId();
  const timestamp = Date.now();
  if (isSupabaseConfigured()) {
    try {
        // We now save topic and level as separate columns for easier querying
        const { data, error } = await supabase.from('quizzes').insert([{ 
            user_id: userId, 
            data: quiz,
            topic: quiz.topic,
            level: quiz.cefr_level
        }]).select().single();
        if (!error) return { id: data.id, created_at: new Date(data.created_at).getTime(), data: data.data };
    } catch (err) {}
  }
  const newSavedQuiz: SavedQuiz = { id: crypto.randomUUID(), created_at: timestamp, data: quiz };
  const current = getLocalItems<SavedQuiz>(LOCAL_QUIZ_KEY);
  saveLocalItems(LOCAL_QUIZ_KEY, [newSavedQuiz, ...current]);
  return newSavedQuiz;
};

export const getSavedQuizzes = async (): Promise<SavedQuiz[]> => {
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('quizzes').select('*').order('created_at', { ascending: false });
        if (!error) return data.map((row: any) => ({ id: row.id, created_at: new Date(row.created_at).getTime(), data: row.data }));
    } catch (err) {}
  }
  return getLocalItems<SavedQuiz>(LOCAL_QUIZ_KEY);
};

export const getSavedQuizzesByTopic = async (topic: string): Promise<SavedQuiz[]> => {
    if (isSupabaseConfigured()) {
      try {
          // Optimized query using the new column
          const { data, error } = await supabase.from('quizzes')
            .select('*')
            .eq('topic', topic)
            .order('created_at', { ascending: false });

          if (!error) return data.map((row: any) => ({ id: row.id, created_at: new Date(row.created_at).getTime(), data: row.data }));
      } catch (err) {}
    }
    // Local fallback filter
    const allLocal = getLocalItems<SavedQuiz>(LOCAL_QUIZ_KEY);
    return allLocal.filter(q => q.data.topic === topic).sort((a,b) => b.created_at - a.created_at);
  };

export const deleteSavedQuiz = async (id: string): Promise<void> => {
  if (isSupabaseConfigured()) {
    try { await supabase.from('quizzes').delete().eq('id', id); } catch (err) {}
  }
  const current = getLocalItems<SavedQuiz>(LOCAL_QUIZ_KEY);
  saveLocalItems(LOCAL_QUIZ_KEY, current.filter(q => q.id !== id));
};

// --- STORIES ---
export const saveStoryToHistory = async (story: StoryData): Promise<SavedStory> => {
  const userId = getUserId();
  const timestamp = Date.now();
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('stories').insert([{ user_id: userId, data: story }]).select().single();
        if (!error) return { id: data.id, created_at: new Date(data.created_at).getTime(), data: data.data };
    } catch (err) {}
  }
  const newSavedStory: SavedStory = { id: crypto.randomUUID(), created_at: timestamp, data: story };
  const current = getLocalItems<SavedStory>(LOCAL_STORY_KEY);
  saveLocalItems(LOCAL_STORY_KEY, [newSavedStory, ...current]);
  return newSavedStory;
};

export const getSavedStories = async (): Promise<SavedStory[]> => {
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('stories').select('*').order('created_at', { ascending: false });
        if (!error) return data.map((row: any) => ({ id: row.id, created_at: new Date(row.created_at).getTime(), data: row.data }));
    } catch (err) {}
  }
  return getLocalItems<SavedStory>(LOCAL_STORY_KEY);
};

export const deleteSavedStory = async (id: string): Promise<void> => {
  if (isSupabaseConfigured()) {
    try { await supabase.from('stories').delete().eq('id', id); } catch (err) {}
  }
  const current = getLocalItems<SavedStory>(LOCAL_STORY_KEY);
