// --- VOCABULARY ---

export const clearVocabularyByLevel = async (level: CefrLevel): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').delete().eq('level', level);
    } catch (e) {}
  }
  localStorage.removeItem(`${LOCAL_VOCAB_PREFIX}${level}`);
};

export const getVocabularyByLevel = async (level: CefrLevel): Promise<VocabularyEntry[]> => {
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.from('vocabulary').select('*').eq('level', level);
      if (!error && data && data.length > 0) return data as VocabularyEntry[];
    } catch (e: any) {}
  }
  return getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${level}`);
};

export const saveVocabularyList = async (level: CefrLevel, words: VocabularyEntry[]): Promise<void> => {
  const cleanWords = words.map(w => ({ ...w, level, details: null }));
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').insert(cleanWords);
      return;
    } catch (e: any) {}
  }
  saveLocalItems(`${LOCAL_VOCAB_PREFIX}${level}`, cleanWords);
};

export const saveVocabularyEntry = async (entry: VocabularyEntry): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').upsert(entry, { onConflict: 'word' });
      return;
    } catch (e: any) {}
  }
  const key = `${LOCAL_VOCAB_PREFIX}${entry.level}`;
  const list = getLocalItems<VocabularyEntry>(key);
  const idx = list.findIndex(w => w.word.toLowerCase() === entry.word.toLowerCase());
  if (idx !== -1) list[idx] = entry; else list.push(entry);
  saveLocalItems(key, list);
};

export const getWordDetailsFromDB = async (word: string): Promise<WordDetail | null> => {
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.from('vocabulary').select('details').ilike('word', word).limit(1).single();
      if (!error && data?.details) return data.details as WordDetail;
    } catch (e) {}
  }
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) {
    const list = getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${lvl}`);
    const found = list.find(w => w.word.toLowerCase() === word.toLowerCase());
    if (found && found.details) return found.details;
  }
  return null;
};

export const updateWordDetailsInDB = async (word: string, details: WordDetail): Promise<void> => {
  if (isSupabaseConfigured()) {
    try {
      await supabase.from('vocabulary').update({ details: details }).eq('word', word);
      return;
    } catch (e) {}
  }
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) {
    const key = `${LOCAL_VOCAB_PREFIX}${lvl}`;
    const list = getLocalItems<VocabularyEntry>(key);
    const idx = list.findIndex(w => w.word === word);
    if (idx !== -1) {
      list[idx].details = details;
      saveLocalItems(key, list);
      return;
    }
  }
};

export const searchVocabulary = async (query: string): Promise<VocabularyEntry[]> => {
  if (!query || query.length < 2) return [];
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase.from('vocabulary').select('*').ilike('word', `${query}%`).limit(8);
      if (!error && data) return data as VocabularyEntry[];
    } catch (e) {}
  }
  const allWords: VocabularyEntry[] = [];
  const levels: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];
  for (const lvl of levels) allWords.push(...getLocalItems<VocabularyEntry>(`${LOCAL_VOCAB_PREFIX}${lvl}`));
  return allWords.filter(w => w.word.toLowerCase().startsWith(query.toLowerCase())).slice(0, 8);
};

// --- PATH / PROGRESS ---

export const getPathProgress = async (level: string): Promise<UserProgress[]> => {
  const userId = getUserId();
  if (isSupabaseConfigured()) {
    try {
       const { data, error } = await supabase.from('user_progress').select('*').eq('user_id', userId).eq('level_id', level);
       if (!error && data) return data as UserProgress[];
    } catch(e) {}
  }
  // Local fallback
  const allProgress = getLocalItems<UserProgress>(LOCAL_PROGRESS_KEY);
  return allProgress.filter(p => p.level_id === level);
};

export const markCheckpointComplete = async (level: string, title: string, score: number): Promise<void> => {
  const userId = getUserId();
  const entry: UserProgress = {
      level_id: level,
      checkpoint_title: title,
      completed: true,
      score: score
  };

  if (isSupabaseConfigured()) {
    try {
       await supabase.from('user_progress').upsert({
         user_id: userId,
         ...entry
       }, { onConflict: 'user_id, level_id, checkpoint_title' });
       return;
    } catch(e) {}
  }

  // Local Fallback
  const allProgress = getLocalItems<UserProgress>(LOCAL_PROGRESS_KEY);
  const idx = allProgress.findIndex(p => p.level_id === level && p.checkpoint_title === title);
  if (idx > -1) {
      // Keep highest score
      if (score > allProgress[idx].score) allProgress[idx].score = score;
      allProgress[idx].completed = true;
  } else {
      allProgress.push(entry);
  }
  saveLocalItems(LOCAL_PROGRESS_KEY, allProgress);
};

// --- STUDY GUIDES & SYLLABUS ---

export const getStudyGuide = async (topic: string, level: string): Promise<StudyGuideContent | null> => {
  if (isSupabaseConfigured()) {
    try {
        const { data, error } = await supabase.from('study_guides')
            .select('content')
            .eq('level_id', level)
            .eq('topic_id', topic)
            .single();
        if (!error && data) return data.content as StudyGuideContent;
    } catch (e) {}
  }

  // Local Fallback
  const guides = getLocalItems<StudyGuideDB>(LOCAL_GUIDES_KEY);
  const found = guides.find(g => g.level_id === level && g.topic_id === topic);
  return found ? found.content : null;
};

export const saveStudyGuide = async (topic: string, level: string, content: StudyGuideContent): Promise<void> => {
   if (isSupabaseConfigured()) {
       try {
           await supabase.from('study_guides').upsert({
               level_id: level,
               topic_id: topic,
               content: content
           }, { onConflict: 'level_id, topic_id' });
           return;
       } catch (e) {}
   }

   // Local Fallback
   const guides = getLocalItems<StudyGuideDB>(LOCAL_GUIDES_KEY);
   const idx = guides.findIndex(g => g.level_id === level && g.topic_id === topic);
   const newEntry: StudyGuideDB = { level_id: level, topic_id: topic, content };

   if (idx > -1) guides[idx] = newEntry;
   else guides.push(newEntry);

   saveLocalItems(LOCAL_GUIDES_KEY, guides);
};

export const getSyllabusList = async (level: string): Promise<PathCheckpoint[]> => {
  if (isSupabaseConfigured()) {
    try {
      const { data, error } = await supabase
        .from('study_guides')
        .select('topic_id, content')
        .eq('level_id', level)
        .order('created_at', { ascending: true }); // Assumption: inserted in desired order

      if (!error && data && data.length > 0) {
        return data.map((row: any) => {
            const content = row.content as StudyGuideContent;
            // Truncate description for the card view
            const description = content.concept_explanation || "Study guide available.";
            const shortDesc = description.length > 120 ? description.substring(0, 120) + "..." : description;

            const examples = Array.isArray(content.examples) 
                ? content.examples.slice(0, 3).map((ex: any) => typeof ex === 'string' ? ex : ex.french) 
                : [];

            return {
                title: row.topic_id,
                description: shortDesc,
                examples: examples
            };
        });
      }
    } catch (e) {
      console.warn("Failed to fetch syllabus from DB", e);
    }
  }
  return [];
};

import React, { useState, useEffect } from 'react';
import { CefrLevel, PathCheckpoint, UserProgress } from '../types';
import { A2_SYLLABUS, B1_SYLLABUS } from '../data/syllabus';
import { getPathProgress, markCheckpointComplete, getSyllabusList } from '../services/storageService';
import { CheckCircleIcon, PlayCircleIcon, LockClosedIcon, BookOpenIcon, ChevronRightIcon } from '@heroicons/react/24/solid';
import { InteractiveText } from './InteractiveText';
import { StudyGuideView } from './StudyGuideView';

interface PathExplorerProps {
  onStartQuiz: (topic: string, level: CefrLevel) => void;
  onViewHistory: (topic: string) => void;
  initialTopic?: string | null;
  onTopicOpened?: () => void;
}

const LEVELS: CefrLevel[] = ['A1', 'A2', 'B1', 'B2'];

export const PathExplorer: React.FC<PathExplorerProps> = ({ onStartQuiz, onViewHistory, initialTopic, onTopicOpened }) => {
  const [activeLevel, setActiveLevel] = useState<CefrLevel>('A2');
  const [syllabus, setSyllabus] = useState<PathCheckpoint[]>([]);
  const [progress, setProgress] = useState<UserProgress[]>([]);
  const [loading, setLoading] = useState(false);

  // Navigation State
  const [selectedTopic, setSelectedTopic] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, [activeLevel]);

  // Handle auto-open of topic if returning from quiz
  useEffect(() => {
      if (initialTopic) {
          setSelectedTopic(initialTopic);
          if (onTopicOpened) onTopicOpened();
      }
  }, [initialTopic]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [prog, dbSyllabus] = await Promise.all([
        getPathProgress(activeLevel),
        getSyllabusList(activeLevel)
      ]);

      setProgress(prog);

      if (dbSyllabus && dbSyllabus.length > 0) {
        setSyllabus(dbSyllabus);
      } else {
        // Fallback to static lists if DB is empty
        if (activeLevel === 'A2') setSyllabus(A2_SYLLABUS);
        else if (activeLevel === 'B1') setSyllabus(B1_SYLLABUS);
        else setSyllabus([]);
      }
    } catch (e) {
      console.error(e);
      // Fallback on error
      if (activeLevel === 'A2') setSyllabus(A2_SYLLABUS);
      else if (activeLevel === 'B1') setSyllabus(B1_SYLLABUS);
      else setSyllabus([]);
    } finally {
      setLoading(false);
    }
  };

  const getCheckpointStatus = (title: string, index: number) => {
    const entry = progress.find(p => p.checkpoint_title === title);
    if (entry?.completed) return { status: 'completed', score: entry.score };

    // Previously locked logic removed to enable all topics
    return { status: 'unlocked', score: 0 };
  };

  const handleStartQuizFromGuide = (cumulative: boolean) => {
      if (!selectedTopic) return;

      let quizTopic = selectedTopic;

      if (cumulative && syllabus.length > 0) {
          const currentIndex = syllabus.findIndex(t => t.title === selectedTopic);
          if (currentIndex > 0) {
              const previousTitles = syllabus.slice(0, currentIndex + 1).map(t => t.title);
              // Construct a prompt-friendly string containing all topics
              quizTopic = `Cumulative Review of: ${previousTitles.join(', ')}`;
          }
      }

      // We don't nullify selectedTopic here immediately if we want to return to it, 
      // but the quiz view replaces this component anyway.
      setSelectedTopic(null); 
      onStartQuiz(quizTopic, activeLevel);
  };

  // --- RENDERERS ---

  if (selectedTopic) {
      const currentIndex = syllabus.findIndex(t => t.title === selectedTopic);
      const allowCumulative = currentIndex > 0;

      return (
          <StudyGuideView 
             topic={selectedTopic} 
             level={activeLevel} 
             allowCumulative={allowCumulative}
             onBack={() => setSelectedTopic(null)}
             onStartQuiz={handleStartQuizFromGuide}
             onViewHistory={onViewHistory}
          />
      );
  }

  const renderSyllabus = () => {
    // If syllabus is empty (A1 or B2, or DB empty/failed), show Coming Soon
    if (syllabus.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center animate-fade-in">
                <LockClosedIcon className="w-16 h-16 text-slate-200 dark:text-slate-800 mb-4" />
                <h3 className="text-xl font-bold text-slate-400 dark:text-slate-600">Coming Soon</h3>
                <p className="text-slate-400 dark:text-slate-500 mt-2 max-w-sm">
                    The {activeLevel} path is currently under construction or loading.
                </p>
            </div>
        );
    }

    // Determine the next recommended step (first incomplete item) to highlight
    const firstIncompleteIndex = syllabus.findIndex(item => !progress.find(p => p.checkpoint_title === item.title)?.completed);

    return (
        <div className="max-w-3xl mx-auto py-8 relative">
            {/* Vertical Line */}
            <div className="absolute left-6 md:left-8 top-12 bottom-12 w-0.5 bg-slate-200 dark:bg-slate-800 z-0"></div>

            {syllabus.map((checkpoint, index) => {
                const { status, score } = getCheckpointStatus(checkpoint.title, index);
                const isLocked = status === 'locked'; // Always false now
                const isCompleted = status === 'completed';
                const isRecommended = index === firstIncompleteIndex;

                return (
                    <div key={index} className={`relative z-10 pl-20 md:pl-24 mb-12 last:mb-0 group ${isLocked ? 'opacity-50 grayscale' : 'opacity-100'}`}>
                        {/* Connector Dot */}
                        <div className={`
                            absolute left-3 md:left-5 top-6 -translate-x-1/2 w-6 h-6 md:w-8 md:h-8 rounded-full border-4 flex items-center justify-center transition-colors shadow-sm bg-white dark:bg-slate-900
                            ${isCompleted 
                                ? 'border-green-500 text-green-500' 
                                : isLocked 
                                    ? 'border-slate-300 dark:border-slate-700 text-slate-300' 
                                    : 'border-french-blue dark:border-blue-500 text-french-blue dark:text-blue-500'
                            }
                        `}>
                            {isCompleted && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-green-500" />}
                            {/* Pulse only the recommended next step to avoid visual noise */}
                            {!isCompleted && !isLocked && isRecommended && <div className="w-2 h-2 md:w-3 md:h-3 rounded-full bg-french-blue dark:bg-blue-500 animate-pulse" />}
                        </div>

                        {/* Content Card */}
                        <div 
                            onClick={() => !isLocked && setSelectedTopic(checkpoint.title)}
                            className={`
                            bg-white dark:bg-slate-900 rounded-2xl p-6 border transition-all duration-300
                            ${isLocked 
                                ? 'border-slate-100 dark:border-slate-800 cursor-not-allowed' 
                                : isCompleted
                                    ? 'border-green-200 dark:border-green-900/50 shadow-sm cursor-pointer hover:border-green-300 dark:hover:border-green-800'
                                    : 'border-french-blue dark:border-blue-600 shadow-md ring-1 ring-french-blue/10 cursor-pointer hover:shadow-xl hover:-translate-y-1'
                            }
                        `}>
                            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-3">
                                <div>
                                    <h3 className="text-xl font-bold font-serif text-slate-800 dark:text-slate-100 group-hover:text-french-blue dark:group-hover:text-blue-400 transition-colors">
                                        {checkpoint.title}
                                    </h3>
                                    {isCompleted && (
                                        <span className="inline-flex items-center gap-1 text-xs font-bold text-green-600 dark:text-green-400 mt-1">
                                            <CheckCircleIcon className="w-3 h-3" />
                                            Completed (Best: {score}/10)
                                        </span>
                                    )}
                                </div>
                                {!isLocked && (
                                    <div className="flex items-center text-sm font-bold text-french-blue dark:text-blue-400 opacity-0 group-hover:opacity-100 transition-opacity -translate-x-2 group-hover:translate-x-0">
                                        Open Guide <ChevronRightIcon className="w-4 h-4 ml-1" />
                                    </div>
                                )}
                            </div>

                            <p className="text-slate-600 dark:text-slate-400 mb-4 leading-relaxed">
                                {checkpoint.description}
                            </p>

                            <div className="bg-slate-50 dark:bg-slate-800/50 rounded-lg p-4 border border-slate-100 dark:border-slate-800">
                                <span className="text-xs font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block tracking-wider">Examples</span>
                                <ul className="space-y-2">
                                    {checkpoint.examples.map((ex, i) => (
                                        <li key={i} className="text-sm text-slate-700 dark:text-slate-300 italic">
                                            • <InteractiveText text={ex} glossary={[]} level={activeLevel} />
                                        </li>
                                    ))}
                                </ul>
                            </div>

                            {!isLocked && (
                                <div className="mt-4 pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-end">
                                     <button className="flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-french-blue dark:text-slate-400 dark:hover:text-blue-400 transition-colors">
                                         <BookOpenIcon className="w-4 h-4" />
                                         Study Concept
                                     </button>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
        </div>
    );
  };

  return (
    <div className="w-full max-w-5xl mx-auto animate-fade-in">
        {/* Level Tabs */}
        <div className="flex justify-center mb-12">
            <div className="bg-white dark:bg-slate-900 p-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-800 inline-flex">
                {LEVELS.map(lvl => (
                    <button
                        key={lvl}
                        onClick={() => setActiveLevel(lvl)}
                        className={`
                            px-6 py-2 rounded-full font-bold text-sm transition-all
                            ${activeLevel === lvl 
                                ? 'bg-french-blue text-white shadow-md' 
                                : 'text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'
                            }
                            ${lvl !== 'A2' && lvl !== 'B1' ? 'opacity-60' : ''}
                        `}
                    >
                        {lvl}
                    </button>
                ))}
            </div>
        </div>

        {loading && (
             <div className="text-center py-20 animate-pulse">
                <div className="inline-block w-8 h-8 border-4 border-slate-200 dark:border-slate-800 border-t-french-blue rounded-full animate-spin mb-4"></div>
                <p className="text-slate-400 dark:text-slate-500">Updating Path...</p>
             </div>
        )}

        {!loading && renderSyllabus()}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { StudyGuideContent, CefrLevel } from '../types';
import { generateStudyGuide } from '../services/geminiService';
import { getStudyGuide, saveStudyGuide, getSavedQuizzesByTopic } from '../services/storageService';
import { InteractiveText } from './InteractiveText';
import { ArrowLeftIcon, BookOpenIcon, ExclamationTriangleIcon, PlayCircleIcon, LightBulbIcon, RectangleStackIcon, ClockIcon } from '@heroicons/react/24/solid';

interface StudyGuideViewProps {
  topic: string;
  level: CefrLevel;
  allowCumulative: boolean;
  onBack: () => void;
  onStartQuiz: (cumulative: boolean) => void;
  onViewHistory: (topic: string) => void;
}

export const StudyGuideView: React.FC<StudyGuideViewProps> = ({ topic, level, allowCumulative, onBack, onStartQuiz, onViewHistory }) => {
  const [content, setContent] = useState<StudyGuideContent | null>(null);
  const [loading, setLoading] = useState(true);
  const [isCumulative, setIsCumulative] = useState(false);
  const [savedCount, setSavedCount] = useState(0);

  useEffect(() => {
    loadGuide();
    checkHistory();
  }, [topic, level]);

  const loadGuide = async () => {
    setLoading(true);
    try {
      // 1. Try DB first
      const cached = await getStudyGuide(topic, level);
      if (cached) {
        setContent(cached);
        setLoading(false);
        return;
      }

      // 2. Generate if missing
      const response = await generateStudyGuide(topic, level);
      const newGuide = response.guide;

      setContent(newGuide);

      // 3. Save to DB
      await saveStudyGuide(topic, level, newGuide);
    } catch (e) {
      console.error("Failed to load guide", e);
    } finally {
      setLoading(false);
    }
  };

  const checkHistory = async () => {
    try {
        const history = await getSavedQuizzesByTopic(topic);
        setSavedCount(history.length);
    } catch(e) { console.error(e); }
  };

  if (loading) {
     return (
        <div className="w-full max-w-3xl mx-auto bg-white dark:bg-slate-900 rounded-2xl shadow-xl p-12 flex flex-col items-center justify-center min-h-[500px] transition-colors">
            <div className="relative mb-8">
              <div className="w-20 h-20 border-4 border-slate-100 dark:border-slate-800 rounded-full"></div>
              <div className="w-20 h-20 border-4 border-french-blue rounded-full border-t-transparent animate-spin absolute top-0 left-0"></div>
            </div>
            <h3 className="text-2xl font-serif font-bold text-slate-800 dark:text-slate-100 animate-pulse">
              Consulting the Professor...
            </h3>
            <p className="text-slate-500 dark:text-slate-400 mt-2">
               Preparing study notes for "{topic}"
            </p>
         </div>
     );
  }

  if (!content) return <div className="text-center p-8 text-red-500">Error loading content. Please try again.</div>;

  return (
    <div className="w-full max-w-4xl mx-auto animate-fade-in pb-12">
        <button 
          onClick={onBack}
          className="mb-6 flex items-center gap-2 text-slate-500 dark:text-slate-400 hover:text-french-blue dark:hover:text-blue-400 transition-colors font-medium"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          Back to Path
        </button>

        <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-xl overflow-hidden border border-slate-100 dark:border-slate-800 transition-colors">
            {/* Header */}
            <div className="bg-french-blue dark:bg-slate-800 p-8 text-white relative">
                 <div className="absolute top-0 right-0 p-4 opacity-10">
                     <BookOpenIcon className="w-32 h-32" />
                 </div>
                 <span className="inline-block px-3 py-1 bg-white/20 rounded-full text-xs font-bold tracking-wider mb-3 uppercase">
                    {level} Study Guide
                 </span>
                 <h1 className="text-4xl font-serif font-bold relative z-10">{topic}</h1>

                 {savedCount > 0 && (
                     <button 
                        onClick={() => onViewHistory(topic)}
                        className="mt-4 flex items-center gap-2 px-4 py-2 bg-white/10 hover:bg-white/20 rounded-lg text-sm font-medium transition-colors border border-white/20"
                     >
                        <ClockIcon className="w-4 h-4" />
                        View {savedCount} Past Quiz{savedCount !== 1 ? 'zes' : ''}
                     </button>
                 )}
            </div>

            <div className="p-8 md:p-12 space-y-10">

                {/* Concept */}
                <section>
                    <div className="flex items-center gap-3 mb-4">
                        <div className="p-2 bg-blue-100 dark:bg-blue-900/30 text-french-blue dark:text-blue-300 rounded-lg">
                             <LightBulbIcon className="w-6 h-6" />
                        </div>
                        <h2 className="text-2xl font-bold text-slate-800 dark:text-slate-100">Concept</h2>
                    </div>
                    <p className="text-lg leading-relaxed text-slate-700 dark:text-slate-300">
                        {content.concept_explanation}
                    </p>
                </section>

                <hr className="border-slate-100 dark:border-slate-800" />

                {/* Key Rules */}
                <section>
                    <h3 className="text-lg font-bold text-slate-800 dark:text-slate-100 mb-4 uppercase tracking-wide">Key Rules</h3>
                    <ul className="space-y-3">
                        {(content.key_rules || []).map((rule, idx) => (
