                                <span className="leading-relaxed">{rule}</span>
                            </li>
                        ))}
                        {(!content.key_rules || content.key_rules.length === 0) && (
                            <li className="text-slate-500 italic">No specific rules available.</li>
                        )}
                    </ul>
                </section>

                {/* Exceptions (Conditional) */}
